const PLANNER_DRAG_HANDLE_SIZE: f32 = 22.0;

/// Cadence's Planner drag handle uses Radiant's standard grip chrome while
/// retaining pass-through capture so insertion targets can follow the pointer.
#[derive(Clone, Debug)]
struct PlannerDragHandleWidget {
    inner: InteractiveRowWidget,
}

impl PlannerDragHandleWidget {
    fn new() -> Self {
        Self {
            inner: InteractiveRowWidget::new(
                0,
                ui::WidgetSizing::fixed(Vector2::new(
                    PLANNER_DRAG_HANDLE_SIZE,
                    PLANNER_DRAG_HANDLE_SIZE,
                )),
            )
            .with_drag(),
        }
    }
}

impl Widget for PlannerDragHandleWidget {
    fn common(&self) -> &WidgetCommon {
        &self.inner.common
    }

    fn common_mut(&mut self) -> &mut WidgetCommon {
        &mut self.inner.common
    }

    fn handle_input(&mut self, bounds: Rect, input: WidgetInput) -> Option<WidgetOutput> {
        match self.inner.handle_input(bounds, input) {
            Some(ui::InteractiveRowMessage::Drag(message)) => Some(WidgetOutput::typed(message)),
            _ => None,
        }
    }

    fn synchronize_from_previous(&mut self, previous: &dyn Widget) {
        let Some(previous) = previous.as_any().downcast_ref::<Self>() else {
            return;
        };
        Widget::synchronize_from_previous(&mut self.inner, &previous.inner);
    }

    fn accepts_pointer_move(&self) -> bool {
        true
    }

    fn allows_captured_pointer_pass_through(&self) -> bool {
        true
    }

    fn append_paint(
        &self,
        primitives: &mut Vec<PaintPrimitive>,
        bounds: Rect,
        layout: &LayoutOutput,
        theme: &ThemeTokens,
    ) {
        let mut handle = DragHandleWidget::new(0, self.inner.common.sizing);
        handle.common = self.inner.common.clone();
        Widget::append_paint(&handle, primitives, bounds, layout, theme);
    }
}

impl TrackCardChromeWidget {
    fn new(selected: bool, favorite: bool) -> Self {
        Self {
            common: WidgetCommon::fixed(0, 1.0, 1.0).without_default_chrome(),
            selected,
            favorite,
        }
    }
}

impl Widget for TrackCardChromeWidget {
    fn common(&self) -> &WidgetCommon {
        &self.common
    }

    fn common_mut(&mut self) -> &mut WidgetCommon {
        &mut self.common
    }

    fn accepts_pointer_move(&self) -> bool {
        false
    }

    fn accepts_pointer_input(&self, _input: &WidgetInput) -> bool {
        false
    }

    fn handle_input(&mut self, _bounds: Rect, _input: WidgetInput) -> Option<WidgetOutput> {
        None
    }

    fn append_paint(
        &self,
        primitives: &mut Vec<PaintPrimitive>,
        bounds: Rect,
        _layout: &LayoutOutput,
        theme: &ThemeTokens,
    ) {
        if !bounds.has_finite_positive_area() {
            return;
        }

        let points = track_card_points(bounds);
        primitives.push(PaintPrimitive::FillPolygon(PaintFillPolygon {
            widget_id: self.common.id,
            points: Arc::clone(&points),
            color: track_card_fill(self.favorite, theme),
        }));
        primitives.push(PaintPrimitive::StrokePolygon(PaintStrokePolygon {
            widget_id: self.common.id,
            points,
            color: if self.selected {
                TRACK_CARD_SELECTED_CORAL
            } else {
                theme.grid_strong
            },
            width: TRACK_CARD_OUTLINE_WIDTH,
        }));
        let rail_vertical_inset = TRACK_CARD_RAIL_VERTICAL_INSET.min(bounds.height() * 0.5);
        let rail_edge_inset = TRACK_CARD_RAIL_EDGE_INSET.min(bounds.width());
        let rail_width = TRACK_CARD_RAIL_WIDTH.min((bounds.width() - rail_edge_inset).max(0.0));
        let rail = Rect::from_min_max(
            Point::new(
                bounds.min.x + rail_edge_inset,
                bounds.min.y + rail_vertical_inset,
            ),
            Point::new(
                bounds.min.x + rail_edge_inset + rail_width,
                bounds.max.y - rail_vertical_inset,
            ),
        );
        if rail.has_finite_positive_area() {
            primitives.push(PaintPrimitive::FillRect(PaintFillRect {
                widget_id: self.common.id,
                rect: rail,
                color: if self.selected {
                    TRACK_CARD_SELECTED_CORAL
                } else {
                    theme.grid_strong
                },
            }));
        }
    }
}

fn track_card_points(bounds: Rect) -> Arc<[Point]> {
    let chamfer = TRACK_CARD_CHAMFER.min(bounds.width().min(bounds.height()) * 0.5);
    [
        Point::new(bounds.min.x, bounds.min.y),
        Point::new(bounds.max.x, bounds.min.y),
        Point::new(bounds.max.x, bounds.max.y - chamfer),
        Point::new(bounds.max.x - chamfer, bounds.max.y),
        Point::new(bounds.min.x, bounds.max.y),
    ]
    .into()
}

fn track_card_fill(favorite: bool, theme: &ThemeTokens) -> ui::Rgba8 {
    favorite_fill(theme.bg_primary, favorite, theme)
}

fn favorite_fill(base: ui::Rgba8, favorite: bool, theme: &ThemeTokens) -> ui::Rgba8 {
    if favorite {
        base.blend_toward(theme.surface_overlay, TRACK_CARD_FAVORITE_FILL_BLEND)
    } else {
        base
    }
}

fn track_card_chrome(selected: bool, favorite: bool) -> ui::View<Message> {
    ui::custom_widget(TrackCardChromeWidget::new(selected, favorite), |_| None).fill()
}

