#[derive(Clone, Debug)]
struct NoteDraft {
    owner: NoteOwner,
    note_id: Option<String>,
    nonce: u64,
    time_millis: u64,
    body: String,
}

impl NoteDraft {
    fn identity(&self) -> NoteDraftIdentity {
        NoteDraftIdentity {
            owner: self.owner.clone(),
            note_id: self.note_id.clone(),
            nonce: self.nonce,
        }
    }

    fn address(&self) -> Option<NoteAddress> {
        self.note_id
            .as_ref()
            .map(|note_id| note_address_for_owner(&self.owner, note_id))
    }
}

