impl AppState {
    fn loading() -> Self {
        Self {
            library_load_state: LibraryLoadState::Loading,
            status: String::from("Loading local library…"),
            ..Self::default()
        }
    }
}

fn allocate_note_draft_nonce(state: &mut AppState) -> u64 {
    state.next_note_draft_nonce = state
        .next_note_draft_nonce
        .checked_add(1)
        .expect("note draft nonce overflow");
    state.next_note_draft_nonce
}

fn active_draft_matches(draft: Option<&NoteDraft>, identity: &NoteDraftIdentity) -> bool {
    draft.is_some_and(|draft| draft.identity().eq(identity))
}

fn playback_shortcut(state: &AppState, press: ui::KeyPress) -> ui::ShortcutResolution<Message> {
    let comment_draft_active = state.draft_note.is_some() || state.reference_draft_note.is_some();

    if press == ui::KeyPress::new(ui::KeyCode::Escape) {
        ui::ShortcutResolution::action(Message::StopPlayback)
    } else if !comment_draft_active && press == ui::KeyPress::new(ui::KeyCode::N) {
        ui::ShortcutResolution::action(Message::NewNoteAtCurrentTime)
    } else if !comment_draft_active && press == ui::KeyPress::new(ui::KeyCode::Space) {
        ui::ShortcutResolution::action(Message::TogglePlayback)
    } else {
        ui::ShortcutResolution::unhandled()
    }
}

fn animation_requested(state: &AppState) -> bool {
    state.transport_playing
        || state.transport_polling
        || state.reference_transport_playing
        || state.reference_transport_polling
        || live_animation_requested(&state.transport, state.live_spectrogram_revision)
        || state.reference_transport.as_ref().is_some_and(|transport| {
            live_animation_requested(transport, state.reference_live_spectrogram_revision)
        })
        || state.audition_pending_play_track_id.is_some()
        || state.pending_comment_playback.is_some()
        || state.playhead_drag_active
        || state.reference_playhead_drag_active
        || !matches!(state.paired_playback_guard, PairedPlaybackGuard::Idle)
}

fn live_animation_requested(transport: &transport::AudioTransport, visible_revision: u64) -> bool {
    let state = transport.live_frame_state();
    state.pending || state.revision > visible_revision
}

fn retained_live_spectrogram_revision(state: &AppState) -> u64 {
    if state.transport_playing || state.reference_transport_playing {
        0
    } else {
        frame_revision_mix(&[
            state.live_spectrogram_revision,
            state.reference_live_spectrogram_revision,
        ])
    }
}

fn live_spectrogram_source_has_frame(state: &AppState, source: AuditionSource) -> bool {
    match source {
        AuditionSource::Main => state.live_spectrogram.is_some(),
        AuditionSource::Reference => state.reference_live_spectrogram.is_some(),
    }
}

fn live_spectrogram_presence_revision(state: &AppState) -> u64 {
    if state.transport_playing || state.reference_transport_playing {
        let source = review_spectrogram_source(state);
        frame_revision_mix(&[
            source as u64,
            live_spectrogram_source_has_frame(state, source) as u64,
        ])
    } else {
        frame_revision_mix(&[
            state.live_spectrogram.is_some() as u64,
            state.reference_live_spectrogram.is_some() as u64,
        ])
    }
}

fn frame_surface_revisions(state: &mut AppState) -> SurfaceRevisions {
    let selected_track = selected_track(state);
    let structure = frame_revision_mix(&[
        workspace_mode_key(state.workspace_mode),
        state.library.tracks.len() as u64,
        frame_revision_text(state.library.selected_track_id.as_deref()),
        frame_revision_text(state.waveform_track_id.as_deref()),
        frame_revision_text(state.reference_waveform_track_id.as_deref()),
        state.waveform.is_some() as u64,
        state.reference_waveform.is_some() as u64,
        state.waveform_busy as u64,
        state.reference_waveform_busy as u64,
        selected_track.is_some_and(|track| track.reference_path.is_some()) as u64,
        state.draft_note.is_some() as u64,
        state.reference_draft_note.is_some() as u64,
    ]);
    let layout = frame_revision_mix(&[
        state.live_spectrogram_height.to_bits() as u64,
        state.library.tracks.len() as u64,
    ]);
    let projection = frame_revision_mix(&[
        // Playback positions and the live graph are painted by the transient
        // overlay while active. These booleans still invalidate once at
        // start/stop so the retained base scene catches up at the boundary.
        state.transport_playing as u64,
        state.reference_transport_playing as u64,
        state.transport_polling as u64,
        state.reference_transport_polling as u64,
        state.transport_waiting_token.is_some() as u64,
        state.reference_transport_waiting_token.is_some() as u64,
        state.waveform_progress.map_or(0, f32::to_bits) as u64,
        state.reference_waveform_progress.map_or(0, f32::to_bits) as u64,
        // The header follows the displayed source while active. Once playback
        // is stopped, preserve the existing all-source final-frame behavior.
        live_spectrogram_presence_revision(state),
        // Active live Spectrum and Waterfall frames are repainted by the
        // transient overlay. Once playback is stopped, accepted frame
        // revisions must reproject the retained scene so the final analyzer
        // rows are included.
        retained_live_spectrogram_revision(state),
        state.live_spectrogram_mode as u64,
        spectrogram::clamp_history_scale(state.live_spectrogram_history_scale).to_bits() as u64,
        state.audition_source as u64,
        state.audition_queue_index as u64,
        state.audition_auto_advance as u64,
        state.audition_pending_play_track_id.is_some() as u64,
        frame_revision_text(Some(&state.status)),
    ]);
    SurfaceRevisions::new(structure, layout, projection)
}

fn live_playback_overlay() -> ui::TransientOverlay<AppState> {
    ui::TransientOverlay::new(LIVE_PLAYBACK_OVERLAY_KEY)
        .paint_only()
        .fps(APP_FRAME_CLOCK_FPS)
        .when(|state: &mut AppState| state.transport_playing || state.reference_transport_playing)
        .paint(paint_live_playback_overlay)
}

fn waveform_overlay_bounds(
    context: &radiant::runtime::TransientOverlayContext<'_>,
    widget_id: u64,
    height: f32,
) -> Option<Rect> {
    let painted = context.plan.first_widget_rect(widget_id)?;
    let bounds = Rect::from_min_max(
        Point::new(painted.min.x, painted.max.y - height),
        Point::new(painted.max.x, painted.max.y),
    );
    bounds.has_finite_positive_area().then_some(bounds)
}

fn playback_ratio_for_source(state: &AppState, source: AuditionSource) -> Option<f32> {
    let selected_track_id = state.library.selected_track_id.as_deref()?;
    match source {
        AuditionSource::Main => {
            if !state.transport_playing
                || state.waveform_track_id.as_deref() != Some(selected_track_id)
            {
                return None;
            }
            let waveform = state.waveform.as_ref()?;
            waveform::ratio_for_millis(state.transport_position_millis, waveform.duration_millis)
        }
        AuditionSource::Reference => {
            if !state.reference_transport_playing
                || state.reference_waveform_track_id.as_deref() != Some(selected_track_id)
            {
                return None;
            }
            let waveform = state.reference_waveform.as_ref()?;
            waveform::ratio_for_millis(
                state.reference_transport_position_millis,
                waveform.duration_millis,
            )
        }
    }
}

fn paint_live_playback_overlay(
    state: &mut AppState,
    context: radiant::runtime::TransientOverlayContext<'_>,
    primitives: &mut Vec<PaintPrimitive>,
) {
    let theme = ThemeTokens::default();
    if let Some(ratio) = playback_ratio_for_source(state, AuditionSource::Main)
        && let Some(bounds) =
            waveform_overlay_bounds(&context, waveform::MAIN_WAVEFORM_WIDGET_ID, WAVEFORM_HEIGHT)
    {
        waveform::paint_playhead_overlay(
            primitives,
            bounds,
            waveform::WaveformSource::Main,
            ratio,
            &theme,
        );
    }
    if let Some(ratio) = playback_ratio_for_source(state, AuditionSource::Reference)
        && let Some(bounds) = waveform_overlay_bounds(
            &context,
            waveform::REFERENCE_WAVEFORM_WIDGET_ID,
            REFERENCE_WAVEFORM_HEIGHT,
        )
    {
        waveform::paint_playhead_overlay(
            primitives,
            bounds,
            waveform::WaveformSource::Reference,
            ratio,
            &theme,
        );
    }

    let frame = selected_track(state).and_then(|track| {
        let source = review_spectrogram_source(state);
        current_live_frame_for_source(state, &track.id, source)
    });
    let Some(bounds) = context.plan.first_widget_rect(LIVE_SPECTROGRAM_BODY_ID) else {
        return;
    };
    if let Some(frame) = frame {
        spectrogram::paint_overlay_cached(
            frame,
            state.live_spectrogram_mode,
            state.live_spectrogram_history_scale,
            bounds,
            primitives,
            &theme,
            &mut state.live_spectrogram_overlay_cache,
        );
    }
}

fn workspace_mode_key(mode: WorkspaceMode) -> u64 {
    match mode {
        WorkspaceMode::Review => 0,
        WorkspaceMode::Planner => 1,
        WorkspaceMode::Audition => 2,
    }
}

fn frame_revision_text(value: Option<&str>) -> u64 {
    value.map_or(0, |text| {
        text.bytes().fold(0xcbf2_9ce4_8422_2325, |hash, byte| {
            hash.wrapping_mul(0x0000_0100_0000_01b3) ^ u64::from(byte)
        })
    })
}

fn frame_revision_mix(values: &[u64]) -> u64 {
    values.iter().fold(0x9e37_79b9_7f4a_7c15, |hash, value| {
        hash.rotate_left(7).wrapping_mul(0x9e37_79b9_7f4a_7c15)
            ^ value.wrapping_add(0x517c_c1b7_2722_0a95)
    })
}

fn native_launch_options() -> NativeRunOptions {
    let mut options = NativeRunOptions::default();
    options.window.behavior.maximized = true;
    options.window.behavior.integrated_titlebar = true;
    options
        .window
        .behavior
        .integrated_titlebar_drag_region_height = Some(42.0);
    options
}

fn main() -> radiant::Result {
    let _instance_lock = match storage::acquire_instance_lock() {
        Ok(lock) => lock,
        Err(error) => {
            eprintln!("Could not start Cadence: {error}");
            return Ok(());
        }
    };

    radiant::app(AppState::loading())
        .options(native_launch_options())
        .title("Cadence — local track review")
        .size(1180, 720)
        .min_size(900, 560)
        .view(project_surface)
        .auxiliary_windows(reference_settings_auxiliary_windows)
        .presentation(
            ui::presentation()
                .frame_clock(
                    ui::FrameClock::message(Message::Frame)
                        .when(|state| animation_requested(state))
                        .fps(APP_FRAME_CLOCK_FPS)
                        .surface_revisions(frame_surface_revisions),
                )
                .transient_overlay(live_playback_overlay()),
        )
        .on_startup(|_state, context| schedule_library_load(context))
        .shortcuts(|state, _pending, press, _focus| playback_shortcut(state, press))
        .handle_message(update)
        .run()
}

fn schedule_library_load(context: &mut ui::UiUpdateContext<Message>) {
    context
        .business()
        .blocking_io("cadence-load-library")
        .run(|_| storage::load_library(), Message::LibraryLoaded);
}

fn library_is_ready(state: &AppState) -> bool {
    state.library_load_state == LibraryLoadState::Ready
}

fn library_unavailable_status(state: &AppState) -> &'static str {
    match state.library_load_state {
        LibraryLoadState::Loading => "The library is still loading.",
        LibraryLoadState::Ready => "",
        LibraryLoadState::RecoveryRequired => {
            "The library needs recovery before it can be changed."
        }
    }
}

fn activate_loaded_library(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    library: storage::Library,
) {
    state.audio_import_in_flight = None;
    state.pending_import_commit = None;
    state.library = library;
    reset_comments_windows(state);
    state.library_revision = 0;
    state.persisted_library_revision = 0;
    state.save_in_flight = None;
    state.save_admission_pending = false;
    storage::normalize_planner_order(&mut state.library);
    let (startup_track_id, startup_selection_changed) =
        normalize_startup_track_selection(&mut state.library);
    refresh_selected_track_index(state);
    state.status = if state.library.tracks.is_empty() {
        String::from("Ready — import a track to begin.")
    } else {
        format!(
            "{} local track{} loaded.",
            state.library.tracks.len(),
            plural(state.library.tracks.len())
        )
    };
    state.library_load_state = LibraryLoadState::Ready;
    if state.workspace_mode == WorkspaceMode::Audition {
        rebuild_audition_queue(state);
    }
    state.review_cursor_millis = 0;
    state.draft_note = None;
    state.reference_draft_note = None;
    rollback_persisted_note_drag(state);
    rollback_reference_persisted_note_drag(state);
    state.reference_playhead_drag_active = false;
    state.selected_note_id = None;
    state.hovered_note_id = None;
    state.selected_reference_note_id = None;
    state.hovered_reference_note_id = None;
    state.comment_source = CommentSource::Main;
    state.comment_source_explicit = false;
    close_stage_menu(state);
    close_status_menu(state);
    close_reference_menu(state);
    close_settings(state);
    state.remove_confirmation_track_id = None;
    reset_transport(state);
    reset_reference_transport(state);
    state.reference_match_enabled = false;
    if startup_selection_changed {
        schedule_library_save(state, context);
    }
    if let Some(track_id) = startup_track_id.as_deref() {
        context.focus(library_track_title_id(track_id));
    }
    schedule_selected_waveform_decode(state, context);
    schedule_selected_reference_decode(state, context);
    schedule_next_pending_library_operation(state, context);
}

fn retry_library_load(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if state.library_load_state != LibraryLoadState::RecoveryRequired {
        return;
    }
    state.library_load_state = LibraryLoadState::Loading;
    state.status = String::from("Retrying local library load…");
    schedule_library_load(context);
    context.request_repaint();
}

fn preserve_library_and_start_fresh(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if state.library_load_state != LibraryLoadState::RecoveryRequired || state.busy {
        return;
    }
    state.busy = true;
    state.status = String::from("Preserving the unreadable library and starting fresh…");
    context
        .business()
        .blocking_io("cadence-preserve-library-recovery")
        .run(
            |_| storage::preserve_unreadable_library_and_start_fresh(),
            Message::LibraryRecoveryCompleted,
        );
    context.request_repaint();
}

const MAIN_SOURCE_MISMATCH_STATUS: &str = "Source changed since import. Use Replace to review the new version; existing comments were kept.";
const REFERENCE_SOURCE_MISMATCH_STATUS: &str =
    "Reference source changed since import. Remove it from the reference catalog and re-import it.";

fn source_error_is_mismatch(error: &str) -> bool {
    error.contains("Audio source changed")
}

fn main_source_is_mismatched(state: &AppState) -> bool {
    state.main_source_mismatch.is_some()
}

fn reference_source_is_mismatched(state: &AppState) -> bool {
    state.reference_source_mismatch.is_some()
}

fn reject_main_source_mismatch(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) -> bool {
    if !main_source_is_mismatched(state) {
        return false;
    }
    state.status = String::from(MAIN_SOURCE_MISMATCH_STATUS);
    context.request_repaint();
    true
}

fn reject_reference_source_mismatch(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) -> bool {
    if !reference_source_is_mismatched(state) {
        return false;
    }
    state.status = String::from(REFERENCE_SOURCE_MISMATCH_STATUS);
    context.request_repaint();
    true
}

fn preserve_source_mismatch_status(state: &mut AppState) {
    if main_source_is_mismatched(state) {
        state.status = String::from(MAIN_SOURCE_MISMATCH_STATUS);
    } else if reference_source_is_mismatched(state) {
        state.status = String::from(REFERENCE_SOURCE_MISMATCH_STATUS);
    }
}

fn mark_main_transport_source_mismatch(state: &mut AppState) {
    let path = state
        .waveform_source_ticket
        .as_ref()
        .map(|ticket| ticket.path().to_owned())
        .or_else(|| selected_track(state).map(|track| track.path.clone()))
        .or_else(|| state.main_source_mismatch.clone())
        .unwrap_or_default();
    state.main_source_mismatch = Some(path);
    state.waveform_generation = state.waveform_generation.wrapping_add(1);
    state.waveform = None;
    state.waveform_source_ticket = None;
    state.waveform_track_id = None;
    state.waveform_busy = false;
    state.waveform_pending = None;
    state.waveform_progress = None;
    state.waveform_in_flight = None;
    if let Some(cancellation) = state.waveform_cancellation.take() {
        cancellation.cancel();
    }
    clear_pending_seek_intent(state, AuditionSource::Main);
    clear_live_spectrogram(state, AuditionSource::Main);
    state.loop_selections.clear(AuditionSource::Main);
    state.playhead_drag_active = false;
    state.transport_playing = false;
    state.transport_polling = false;
    state.transport_waiting_token = None;
    state.audition_auto_advance = false;
    state.audition_play_token = None;
    state.audition_pending_play_track_id = None;
    state.reference_match_enabled = false;
    if state
        .pending_comment_playback
        .as_ref()
        .is_some_and(|pending| matches!(&pending.address.owner, NoteOwner::MainTrack(_)))
    {
        cancel_pending_comment_playback(state);
    }
}

fn mark_reference_transport_source_mismatch(state: &mut AppState) {
    let path = state
        .reference_waveform_source_ticket
        .as_ref()
        .map(|ticket| ticket.path().to_owned())
        .or_else(|| selected_track(state).and_then(|track| track.reference_path.clone()))
        .or_else(|| state.reference_source_mismatch.clone())
        .unwrap_or_default();
    state.reference_source_mismatch = Some(path);
    state.reference_waveform_generation = state.reference_waveform_generation.wrapping_add(1);
    state.reference_waveform = None;
    state.reference_waveform_source_ticket = None;
    state.reference_waveform_track_id = None;
    state.reference_waveform_busy = false;
    state.reference_waveform_pending = None;
    state.reference_waveform_progress = None;
    state.reference_waveform_in_flight = None;
    if let Some(cancellation) = state.reference_waveform_cancellation.take() {
        cancellation.cancel();
    }
    clear_pending_seek_intent(state, AuditionSource::Reference);
    clear_live_spectrogram(state, AuditionSource::Reference);
    state.loop_selections.clear(AuditionSource::Reference);
    state.reference_playhead_drag_active = false;
    state.reference_transport_playing = false;
    state.reference_transport_polling = false;
    state.reference_transport_waiting_token = None;
    state.reference_transport_loaded = false;
    state.reference_only_playback = false;
    state.reference_match_enabled = false;
    if state
        .pending_comment_playback
        .as_ref()
        .is_some_and(|pending| matches!(&pending.address.owner, NoteOwner::ReferenceTrack(_)))
    {
        cancel_pending_comment_playback(state);
    }
}

fn handle_main_transport_source_mismatch(state: &mut AppState) {
    mark_main_transport_source_mismatch(state);
    if paired_playback_intended(state) {
        cleanup_transport_failure(state, String::from(MAIN_SOURCE_MISMATCH_STATUS), None);
    } else {
        reset_transport(state);
        state.status = String::from(MAIN_SOURCE_MISMATCH_STATUS);
    }
}

fn handle_reference_transport_source_mismatch(state: &mut AppState) {
    let paired = paired_playback_intended(state);
    mark_reference_transport_source_mismatch(state);
    if paired {
        cleanup_reference_transport_source_mismatch(
            state,
            String::from(REFERENCE_SOURCE_MISMATCH_STATUS),
        );
    } else {
        reset_reference_transport(state);
        state.status = String::from(REFERENCE_SOURCE_MISMATCH_STATUS);
    }
}

fn cleanup_reference_transport_source_mismatch(state: &mut AppState, error: String) -> String {
    if let Some(root_error) = cleanup_any_error(state) {
        let root_error = root_error.to_owned();
        state.status = root_error.clone();
        return root_error;
    }

    let reference_unload = invalidate_reference_transport_after_failure(state);
    state.paired_playback_guard = PairedPlaybackGuard::StoppingReference {
        root_error: error.clone(),
        reference_unload,
        pending_reset_main: false,
        pending_reset_reference: false,
    };
    set_audition_source(state, AuditionSource::Main);
    state.transport.set_output_gain(main_output_gain(state));
    progress_paired_playback_cleanup_initial(state);
    state.status = error.clone();
    error
}

fn main_annotations_available(state: &AppState) -> bool {
    selected_track(state).is_some_and(|track| track.source_provenance().verified_proof().is_some())
}

fn reference_annotations_available(state: &AppState) -> bool {
    selected_track(state)
        .and_then(|track| track.reference_path.as_ref())
        .and_then(|path| {
            state
                .library
                .reference_tracks
                .iter()
                .find(|reference| &reference.path == path)
        })
        .is_some_and(|reference| reference.source_provenance().verified_proof().is_some())
}

fn historical_source_warning(
    owner: &HistoricalBindingOwner,
    path: &Path,
    note_count: usize,
) -> String {
    let owner_label = match owner {
        HistoricalBindingOwner::Main { .. } => "main track",
        HistoricalBindingOwner::Reference { .. } => "reference",
    };
    format!(
        "Historical comments for this {owner_label} are retained but not bound to the current file ({note_count} comment{}). Bind them explicitly to {}.",
        plural(note_count),
        path.display()
    )
}

fn reject_unknown_main_source(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) -> bool {
    let Some(track) = selected_track(state) else {
        return false;
    };
    if !track.source_provenance().is_unknown() {
        return false;
    }
    state.status = historical_source_warning(
        &HistoricalBindingOwner::Main {
            track_id: track.id.clone(),
        },
        &track.path,
        track.notes.len(),
    );
    context.request_repaint();
    true
}

fn reject_unknown_reference_source(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) -> bool {
    let Some(track) = selected_track(state) else {
        return false;
    };
    let Some(path) = track.reference_path.as_ref() else {
        return false;
    };
    let Some(reference) = state
        .library
        .reference_tracks
        .iter()
        .find(|reference| &reference.path == path)
    else {
        return false;
    };
    if !reference.source_provenance().is_unknown() {
        return false;
    }
    state.status = historical_source_warning(
        &HistoricalBindingOwner::Reference { path: path.clone() },
        path,
        reference.notes.len(),
    );
    context.request_repaint();
    true
}

fn historical_binding_candidate(
    state: &AppState,
    owner: HistoricalBindingOwner,
) -> Option<HistoricalBindingCandidate> {
    match owner.clone() {
        HistoricalBindingOwner::Main { track_id } => {
            let track = state
                .library
                .tracks
                .iter()
                .find(|track| track.id == track_id)?;
            let ticket = state.waveform_source_ticket.as_ref()?;
            (state.library.selected_track_id.as_deref() == Some(track_id.as_str())
                && state.waveform_track_id.as_deref() == Some(track_id.as_str())
                && ticket.path() == track.path
                && track.source_provenance().is_unknown())
            .then_some(HistoricalBindingCandidate {
                owner,
                path: track.path.clone(),
                note_count: track.notes.len(),
                generation: state.waveform_generation,
                displayed_proof: ticket.proof().clone(),
            })
        }
        HistoricalBindingOwner::Reference { path } => {
            let track = selected_track(state)?;
            let reference = state
                .library
                .reference_tracks
                .iter()
                .find(|reference| reference.path == path)?;
            let ticket = state.reference_waveform_source_ticket.as_ref()?;
            (track.reference_path.as_ref() == Some(&path)
                && state.reference_waveform_track_id.as_deref() == Some(track.id.as_str())
                && ticket.path() == path
                && reference.source_provenance().is_unknown())
            .then_some(HistoricalBindingCandidate {
                owner,
                path,
                note_count: reference.notes.len(),
                generation: state.reference_waveform_generation,
                displayed_proof: ticket.proof().clone(),
            })
        }
    }
}

fn current_historical_binding_ticket(
    state: &AppState,
    candidate: &HistoricalBindingCandidate,
) -> Option<crate::source::VerifiedSourceTicket> {
    match &candidate.owner {
        HistoricalBindingOwner::Main { track_id } => (state.library.selected_track_id.as_deref()
            == Some(track_id.as_str())
            && state.waveform_track_id.as_deref() == Some(track_id.as_str())
            && state.waveform_generation == candidate.generation)
            .then(|| state.waveform_source_ticket.clone())
            .flatten(),
        HistoricalBindingOwner::Reference { path } => {
            let selected_track_id = selected_track(state)
                .filter(|track| track.reference_path.as_ref() == Some(path))
                .map(|track| track.id.as_str());
            (selected_track_id == state.reference_waveform_track_id.as_deref()
                && state.reference_waveform_generation == candidate.generation)
                .then(|| state.reference_waveform_source_ticket.clone())
                .flatten()
        }
    }
}

fn binding_owner_is_still_unknown(
    state: &AppState,
    candidate: &HistoricalBindingCandidate,
) -> bool {
    match &candidate.owner {
        HistoricalBindingOwner::Main { track_id } => state
            .library
            .tracks
            .iter()
            .find(|track| track.id == *track_id && track.path == candidate.path)
            .is_some_and(|track| track.source_provenance().is_unknown()),
        HistoricalBindingOwner::Reference { path } => state
            .library
            .reference_tracks
            .iter()
            .find(|reference| &reference.path == path)
            .is_some_and(|reference| reference.source_provenance().is_unknown()),
    }
}

fn clear_historical_binding(state: &mut AppState) {
    state.historical_binding_confirmation = None;
    let was_in_flight = state.historical_binding_in_flight.is_some();
    if let Some(cancellation) = state.historical_binding_cancellation.as_ref() {
        cancellation.cancel();
    }
    state.historical_binding_in_flight = None;
    state.historical_binding_cancellation = None;
    if was_in_flight {
        state.busy = false;
    }
}

fn decode_or_load_cached_waveform(
    path: &Path,
    expected_proof: Option<crate::source::AudioSourceProof>,
    should_cancel: impl Fn() -> bool,
    mut on_progress: impl FnMut(audio::WaveformProgress),
) -> Result<audio::VerifiedWaveform, String> {
    if should_cancel() {
        return Err(String::from("cancelled"));
    }

    // A proof-bearing catalog record can take the cache fast path using only
    // the current metadata stamp. This is the only branch that deliberately
    // avoids reading encoded bytes.
    if let Some(expected) = expected_proof.as_ref() {
        let cache_path = storage::waveform_cache_path(path, expected);
        if let Some(cached) = audio::load_waveform_cache(path, &cache_path)
            && cached.ticket().proof() == expected
        {
            let current_stamp = source::stamp_file(path).map_err(|error| error.to_string())?;
            if cached.ticket().stamp() == current_stamp {
                let ticket = source::VerifiedSourceTicket::new(
                    path.to_path_buf(),
                    expected.clone(),
                    current_stamp,
                )?;
                ticket
                    .validate_current(&should_cancel)
                    .map_err(|error| error.to_string())?;
                if should_cancel() {
                    return Err(String::from("cancelled"));
                }
                let waveform = cached.waveform().clone();
                on_progress(audio::WaveformProgress {
                    waveform: waveform.clone(),
                    progress: Some(1.0),
                });
                return Ok(audio::VerifiedWaveform::new(waveform, ticket));
            }

            // A changed stamp must be hashed exactly once. Equal bytes may
            // reuse the payload while refreshing its durable stamp; changed
            // bytes become an explicit source mismatch rather than a miss.
            let verified =
                source::open_and_hash(path, &should_cancel).map_err(|error| error.to_string())?;
            if verified.proof() != expected {
                return Err(format!(
                    "Audio source changed since import: {}",
                    path.display()
                ));
            }
            let ticket = verified.ticket();
            let waveform = cached.waveform().clone();
            let _ = audio::write_waveform_cache_if_unchanged(path, &cache_path, &ticket, &waveform);
            ticket
                .validate_current(&should_cancel)
                .map_err(|error| error.to_string())?;
            if should_cancel() {
                return Err(String::from("cancelled"));
            }
            on_progress(audio::WaveformProgress {
                waveform: waveform.clone(),
                progress: Some(1.0),
            });
            return Ok(audio::VerifiedWaveform::new(waveform, ticket));
        }
    }

    // Legacy records (and proof-key misses) hash first so the cache key and
    // returned ticket are bound to the same opened handle used for decode.
    let verified =
        source::open_and_hash(path, &should_cancel).map_err(|error| error.to_string())?;
    let discovered_proof = verified.proof().clone();
    if expected_proof
        .as_ref()
        .is_some_and(|expected| expected != &discovered_proof)
    {
        return Err(format!(
            "Audio source changed since import: {}",
            path.display()
        ));
    }
    let cache_path = storage::waveform_cache_path(path, &discovered_proof);
    if let Some(cached) = audio::load_waveform_cache(path, &cache_path)
        && cached.ticket().proof() == &discovered_proof
    {
        let ticket = verified.ticket();
        let waveform = cached.waveform().clone();
        if cached.ticket().stamp() != ticket.stamp() {
            let _ = audio::write_waveform_cache_if_unchanged(path, &cache_path, &ticket, &waveform);
        }
        ticket
            .validate_current(&should_cancel)
            .map_err(|error| error.to_string())?;
        if should_cancel() {
            return Err(String::from("cancelled"));
        }
        on_progress(audio::WaveformProgress {
            waveform: waveform.clone(),
            progress: Some(1.0),
        });
        return Ok(audio::VerifiedWaveform::new(waveform, ticket));
    }

    // Do not publish decoder previews until the retained-handle source fence has
    // accepted the completed waveform. A cache miss must never make an
    // unverified version visible while the encoded source can still change.
    let result = audio::decode_waveform_from_verified_source(verified, &should_cancel, |_| {});
    if should_cancel() {
        return Err(String::from("cancelled"));
    }
    if let Ok(verified_waveform) = &result {
        let _ = audio::write_waveform_cache_if_unchanged(
            path,
            &cache_path,
            verified_waveform.ticket(),
            verified_waveform.waveform(),
        );
        verified_waveform
            .ticket()
            .validate_current(&should_cancel)
            .map_err(|error| error.to_string())?;
        if should_cancel() {
            return Err(String::from("cancelled"));
        }
        on_progress(audio::WaveformProgress {
            waveform: verified_waveform.waveform().clone(),
            progress: Some(1.0),
        });
    }
    result
}

fn start_waveform_decode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    request: WaveformDecodeRequest,
) {
    debug_assert!(state.waveform_in_flight.is_none());
    let WaveformDecodeRequest {
        track_id,
        path,
        generation,
        expected_proof,
    } = request.clone();
    state.waveform_in_flight = Some(request);
    state.waveform_busy = true;
    state.loop_selections.clear(AuditionSource::Main);
    if !paired_playback_cleanup_active(state) && !main_source_is_mismatched(state) {
        state.status = format!("Preparing MAIN waveform and loudness · {}…", path.display());
    }
    let progress_track_id = track_id.clone();
    let completion_track_id = track_id;
    let cancellation = ui::CancellationToken::new();
    state.waveform_cancellation = Some(cancellation.clone());
    let worker_cancellation = cancellation.clone();
    context
        .business()
        .background("cadence-decode-waveform")
        .stream_latest(
            move |_work, sink| {
                decode_or_load_cached_waveform(
                    &path,
                    expected_proof,
                    || worker_cancellation.is_cancelled(),
                    |progress| {
                        let _ = sink.emit(progress);
                    },
                )
            },
            move |progress| Message::DecodeProgress {
                track_id: progress_track_id.clone(),
                generation,
                progress,
            },
            move |result| Message::DecodeCompleted {
                track_id: completion_track_id.clone(),
                generation,
                result,
            },
        );
    context.request_repaint();
}

fn schedule_waveform_decode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    track_id: String,
    path: PathBuf,
) {
    clear_historical_binding(state);
    state.waveform_generation = state.waveform_generation.wrapping_add(1);
    if state.main_source_mismatch.as_ref() != Some(&path) {
        state.main_source_mismatch = None;
    }
    let expected_proof = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == track_id && track.path == path)
        .and_then(|track| track.source_provenance().verified_proof().cloned());
    let request = WaveformDecodeRequest {
        track_id,
        path,
        generation: state.waveform_generation,
        expected_proof,
    };
    state.waveform_busy = true;
    state.waveform = None;
    state.waveform_source_ticket = None;
    state.waveform_track_id = None;
    state.waveform_progress = None;
    state.loop_selections.clear(AuditionSource::Main);
    if state.waveform_in_flight.is_some() {
        state.waveform_pending = Some(request);
        if let Some(cancellation) = state.waveform_cancellation.as_ref() {
            cancellation.cancel();
        }
        if !paired_playback_cleanup_active(state)
            && !main_source_is_mismatched(state)
            && let Some(pending) = state.waveform_pending.as_ref()
        {
            state.status = format!(
                "Preparing MAIN waveform and loudness · {}…",
                pending.path.display()
            );
        }
        context.request_repaint();
        return;
    }
    state.waveform_pending = None;
    start_waveform_decode(state, context, request);
}

fn reset_waveform_decode(state: &mut AppState) {
    clear_historical_binding(state);
    state.waveform_generation = state.waveform_generation.wrapping_add(1);
    state.waveform_pending = None;
    if let Some(cancellation) = state.waveform_cancellation.as_ref() {
        cancellation.cancel();
    }
    state.waveform_busy = false;
    state.waveform = None;
    state.waveform_source_ticket = None;
    state.main_source_mismatch = None;
    state.waveform_track_id = None;
    state.waveform_progress = None;
    state.loop_selections.clear(AuditionSource::Main);
}

fn schedule_selected_waveform_decode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    let selected = state
        .library
        .selected_track_id
        .as_ref()
        .and_then(|id| state.library.tracks.iter().find(|track| &track.id == id))
        .map(|track| (track.id.clone(), track.path.clone()));
    if let Some((track_id, path)) = selected {
        schedule_waveform_decode(state, context, track_id, path);
    } else {
        reset_waveform_decode(state);
        context.request_repaint();
    }
}

fn start_reference_waveform_decode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    request: WaveformDecodeRequest,
) {
    debug_assert!(state.reference_waveform_in_flight.is_none());
    let WaveformDecodeRequest {
        track_id,
        path,
        generation,
        expected_proof,
    } = request.clone();
    state.reference_waveform_in_flight = Some(request);
    state.reference_waveform_busy = true;
    state.loop_selections.clear(AuditionSource::Reference);
    let progress_track_id = track_id.clone();
    let completion_track_id = track_id;
    let cancellation = ui::CancellationToken::new();
    state.reference_waveform_cancellation = Some(cancellation.clone());
    let worker_cancellation = cancellation.clone();
    context
        .business()
        .background("cadence-decode-reference-waveform")
        .stream_latest(
            move |_work, sink| {
                decode_or_load_cached_waveform(
                    &path,
                    expected_proof,
                    || worker_cancellation.is_cancelled(),
                    |progress| {
                        let _ = sink.emit(progress);
                    },
                )
            },
            move |progress| Message::ReferenceDecodeProgress {
                track_id: progress_track_id.clone(),
                generation,
                progress,
            },
            move |result| Message::ReferenceDecodeCompleted {
                track_id: completion_track_id.clone(),
                generation,
                result,
            },
        );
    context.request_repaint();
}

fn schedule_reference_waveform_decode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    track_id: String,
    path: PathBuf,
) {
    clear_historical_binding(state);
    state.reference_waveform_generation = state.reference_waveform_generation.wrapping_add(1);
    if state.reference_source_mismatch.as_ref() != Some(&path) {
        state.reference_source_mismatch = None;
    }
    let expected_proof = state
        .library
        .reference_tracks
        .iter()
        .find(|reference| reference.path == path)
        .and_then(|reference| reference.source_provenance().verified_proof().cloned());
    let request = WaveformDecodeRequest {
        track_id,
        path,
        generation: state.reference_waveform_generation,
        expected_proof,
    };
    state.reference_waveform_busy = true;
    state.reference_waveform = None;
    state.reference_waveform_source_ticket = None;
    state.reference_waveform_track_id = None;
    state.reference_waveform_progress = None;
    state.loop_selections.clear(AuditionSource::Reference);
    if state.reference_waveform_in_flight.is_some() {
        state.reference_waveform_pending = Some(request);
        if let Some(cancellation) = state.reference_waveform_cancellation.as_ref() {
            cancellation.cancel();
        }
        context.request_repaint();
        return;
    }
    state.reference_waveform_pending = None;
    start_reference_waveform_decode(state, context, request);
}

fn reset_reference_waveform_decode(state: &mut AppState) {
    clear_historical_binding(state);
    state.reference_waveform_generation = state.reference_waveform_generation.wrapping_add(1);
    state.reference_waveform_pending = None;
    if let Some(cancellation) = state.reference_waveform_cancellation.as_ref() {
        cancellation.cancel();
    }
    state.reference_waveform_busy = false;
    state.reference_waveform = None;
    state.reference_waveform_source_ticket = None;
    state.reference_source_mismatch = None;
    state.reference_waveform_track_id = None;
    state.reference_waveform_progress = None;
    state.loop_selections.clear(AuditionSource::Reference);
}

fn schedule_selected_reference_decode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    let selected = state
        .library
        .selected_track_id
        .as_ref()
        .and_then(|id| state.library.tracks.iter().find(|track| &track.id == id))
        .and_then(|track| {
            track
                .reference_path
                .clone()
                .map(|path| (track.id.clone(), path))
        });
    if let Some((track_id, path)) = selected {
        schedule_reference_waveform_decode(state, context, track_id, path);
    } else {
        reset_reference_waveform_decode(state);
        context.request_repaint();
    }
}

fn current_loudness_match_gain_db(state: &AppState) -> Option<f32> {
    let primary_lufs = state
        .waveform
        .as_ref()
        .filter(|_| {
            state.library.selected_track_id.as_deref() == state.waveform_track_id.as_deref()
        })
        .and_then(|waveform| waveform.integrated_lufs);
    let reference_lufs = state
        .reference_waveform
        .as_ref()
        .filter(|_| {
            state.library.selected_track_id.as_deref()
                == state.reference_waveform_track_id.as_deref()
        })
        .and_then(|waveform| waveform.integrated_lufs);
    audio::loudness_match_gain_db(primary_lufs, reference_lufs)
}

fn current_lufs_meter_value(state: &AppState, track_id: &str) -> Option<f32> {
    let position_millis = state.transport_position_millis;
    state
        .waveform
        .as_ref()
        .filter(|_| state.waveform_track_id.as_deref() == Some(track_id))
        .and_then(|waveform| audio::loudness_at_position(waveform, position_millis))
}

fn current_reference_lufs_meter_value(state: &AppState, track_id: &str) -> Option<f32> {
    let position_millis = state.reference_transport_position_millis;
    state
        .reference_waveform
        .as_ref()
        .filter(|_| state.reference_waveform_track_id.as_deref() == Some(track_id))
        .and_then(|waveform| audio::loudness_at_position(waveform, position_millis))
}

fn reference_output_gain(state: &AppState) -> f32 {
    reference_output_gain_for_source(state, state.audition_source)
}

fn reference_output_gain_for_source(state: &AppState, source: AuditionSource) -> f32 {
    if cleanup_any_active(state) {
        return 0.0;
    }
    let match_gain = state
        .reference_match_enabled
        .then(|| current_loudness_match_gain_db(state))
        .flatten()
        .map_or(1.0, audio::linear_gain_for_db);
    if source == AuditionSource::Reference {
        transport::normalize_output_gain(state.audition_volume * match_gain)
    } else {
        0.0
    }
}

fn main_output_gain(state: &AppState) -> f32 {
    let cleanup_has_paused_main = matches!(
        state.paired_playback_guard,
        PairedPlaybackGuard::StoppingMain {
            main_pause_acknowledged: true,
            ..
        }
    );
    if (cleanup_has_paused_main
        || !matches!(
            state.paired_playback_guard,
            PairedPlaybackGuard::StoppingMain { .. }
        ))
        && state.audition_source == AuditionSource::Main
    {
        state.audition_volume
    } else {
        0.0
    }
}

fn sync_audition_output_gains(state: &AppState) {
    if !cleanup_any_active(state) || cleanup_owns_main(state) {
        state.transport.set_output_gain(main_output_gain(state));
    }
    if let Some(reference_transport) = state.reference_transport.as_ref() {
        reference_transport.set_output_gain(if cleanup_any_active(state) {
            0.0
        } else {
            reference_output_gain(state)
        });
    }
}

fn update(state: &mut AppState, message: Message, context: &mut ui::UiUpdateContext<Message>) {
    match message {
        Message::ImportPressed => request_import(state, context),
        Message::FilePicked(result) => match result {
            Ok(PlatformResponse::Path(path)) => schedule_import(state, context, path),
            Ok(PlatformResponse::Canceled) => {
                state.status = String::from("Import canceled.");
                schedule_next_pending_library_operation(state, context);
                context.request_repaint();
            }
            Ok(response) => {
                state.status = format!("Unexpected file-picker response: {response:?}");
                schedule_next_pending_library_operation(state, context);
                context.request_repaint();
            }
            Err(error) => {
                state.status = format!("Could not open the file picker: {error}");
                schedule_next_pending_library_operation(state, context);
                context.request_repaint();
            }
        },
        Message::ReplacePressed(track_id) => request_replace(state, context, track_id),
        Message::ReplaceFilePicked { track_id, result } => match result {
            Ok(PlatformResponse::Path(path)) => schedule_replace(state, context, track_id, path),
            Ok(PlatformResponse::Canceled) => {
                state.status = String::from("Replace canceled.");
                schedule_next_pending_library_operation(state, context);
                context.request_repaint();
            }
            Ok(response) => {
                state.status = format!("Unexpected file-picker response: {response:?}");
                schedule_next_pending_library_operation(state, context);
                context.request_repaint();
            }
            Err(error) => {
                state.status = format!("Could not open the file picker: {error}");
                schedule_next_pending_library_operation(state, context);
                context.request_repaint();
            }
        },
        Message::ReferencePressed(track_id) => request_reference(state, context, track_id),
        Message::ReferenceFilesPicked { track_id, paths } => {
            state.busy = false;
            if paths.is_empty() {
                state.status = String::from("Reference import canceled.");
                schedule_next_pending_library_operation(state, context);
            } else {
                schedule_reference_import(state, context, track_id, paths);
            }
            context.request_repaint();
        }
        Message::AddReferenceTracksPressed => request_add_reference_tracks(state, context),
        Message::ReferenceCatalogFilesPicked(paths) => {
            state.busy = false;
            if paths.is_empty() {
                state.status = String::from("Reference catalog import canceled.");
                schedule_next_pending_library_operation(state, context);
            } else {
                schedule_reference_catalog_import(state, context, paths);
            }
            context.request_repaint();
        }
        Message::ReferenceCatalogImportCompleted { path, result } => {
            if state.pending_import_commit.as_ref()
                != Some(&PendingImportCommit::Catalog { path: path.clone() })
            {
                return;
            }
            state.pending_import_commit = None;
            state.busy = false;
            if !library_is_ready(state) {
                state.status = library_unavailable_status(state).to_string();
                context.request_repaint();
                return;
            }
            state.reference_catalog_import_completed = state
                .reference_catalog_import_completed
                .saturating_add(1)
                .min(state.reference_catalog_import_total);
            if result.is_err() {
                state.reference_catalog_import_failed = state
                    .reference_catalog_import_failed
                    .saturating_add(1)
                    .min(state.reference_catalog_import_completed);
            }
            match result {
                Ok(library) => {
                    state.library = library;
                    reset_comments_windows(state);
                    refresh_selected_track_index(state);
                    mark_library_snapshot_persisted(state);
                    state.status = format!(
                        "Added {} to the reference catalog.",
                        reference_track_name(&path)
                    );
                }
                Err(error) => state.status = error,
            }
            if state.pending_reference_catalog_paths.is_empty() {
                let total = state.reference_catalog_import_total;
                let failed = state.reference_catalog_import_failed;
                if total > 1 {
                    state.status = format!(
                        "Added {} of {} reference tracks; {} failed.",
                        total.saturating_sub(failed),
                        total,
                        failed
                    );
                }
                state.reference_catalog_import_total = 0;
                state.reference_catalog_import_completed = 0;
                state.reference_catalog_import_failed = 0;
                schedule_next_pending_library_operation(state, context);
            } else {
                schedule_next_reference_catalog_import(state, context);
            }
            context.request_repaint();
        }
        Message::AudioImportPreflightCompleted { request, result } => {
            complete_audio_import_preflight(state, context, request, result);
        }
        Message::RequestBindHistoricalComments(owner) => {
            if state.busy || !library_is_ready(state) {
                return;
            }
            let Some(candidate) = historical_binding_candidate(state, owner) else {
                state.status = String::from(
                    "The current verified source is unavailable; historical comments were not bound.",
                );
                context.request_repaint();
                return;
            };
            state.historical_binding_confirmation = Some(candidate.clone());
            state.status = format!(
                "Confirm binding {} historical comment{} to {}.",
                candidate.note_count,
                plural(candidate.note_count),
                candidate.path.display()
            );
            context.request_repaint();
        }
        Message::ConfirmBindHistoricalComments(candidate) => {
            start_historical_binding(state, context, candidate);
        }
        Message::CancelBindHistoricalComments(candidate) => {
            let matches_confirmation =
                state.historical_binding_confirmation.as_ref() == Some(&candidate);
            let matches_in_flight = state
                .historical_binding_in_flight
                .as_ref()
                .is_some_and(|request| request.candidate == candidate);
            if !matches_confirmation && !matches_in_flight {
                return;
            }
            if matches_in_flight {
                clear_historical_binding(state);
                state.busy = false;
                state.status = String::from(
                    "Historical comment binding canceled; retained comments were not changed.",
                );
            } else if let Some(candidate) = state.historical_binding_confirmation.take() {
                state.status = historical_source_warning(
                    &candidate.owner,
                    &candidate.path,
                    candidate.note_count,
                );
            }
            context.request_repaint();
        }
        Message::HistoricalBindingCompleted { request, result } => {
            complete_historical_binding(state, context, request, result);
        }
        Message::FileDropped(drop) => {
            if drop.phase == ui::NativeFileDropPhase::Drop
                && let Some(path) = drop.path
            {
                schedule_import(state, context, path);
            }
        }
        Message::LibraryLoaded(result) => {
            clear_planner_drag(state);
            match result {
                Ok(library) => activate_loaded_library(state, context, library),
                Err(error) => {
                    state.library_load_state = LibraryLoadState::RecoveryRequired;
                    state.status =
                        format!("Could not load the local library: {error} Recovery is required.");
                }
            }
            context.request_repaint();
        }
        Message::RetryLibraryLoad => retry_library_load(state, context),
        Message::PreserveLibraryAndStartFresh => preserve_library_and_start_fresh(state, context),
        Message::LibraryRecoveryCompleted(result) => {
            state.busy = false;
            match result {
                Ok(backup_path) => {
                    activate_loaded_library(state, context, storage::Library::default());
                    state.status = format!(
                        "Started a fresh library. The unreadable file was preserved at {}.",
                        backup_path.display()
                    );
                }
                Err(error) => {
                    state.library_load_state = LibraryLoadState::RecoveryRequired;
                    state.status = format!("Could not start a fresh library: {error}");
                }
            }
            context.request_repaint();
        }
        Message::ImportCompleted(result) => {
            if !matches!(
                state.pending_import_commit.as_ref(),
                Some(PendingImportCommit::Main)
            ) {
                return;
            }
            state.pending_import_commit = None;
            let failed = result.is_err();
            state.busy = false;
            if !library_is_ready(state) {
                state.status = library_unavailable_status(state).to_string();
                context.request_repaint();
                return;
            }
            record_import_attempt(state, failed);
            clear_planner_drag(state);
            match result {
                Ok(library) => {
                    state.status = format!(
                        "{} local track{} — all changes saved.",
                        library.tracks.len(),
                        plural(library.tracks.len())
                    );
                    state.library = library;
                    reset_comments_windows(state);
                    refresh_selected_track_index(state);
                    mark_library_snapshot_persisted(state);
                    if state.workspace_mode == WorkspaceMode::Audition {
                        reconcile_audition_queue(state);
                    }
                    state.review_cursor_millis = 0;
                    state.draft_note = None;
                    state.reference_draft_note = None;
                    rollback_persisted_note_drag(state);
                    rollback_reference_persisted_note_drag(state);
                    state.reference_playhead_drag_active = false;
                    state.selected_note_id = None;
                    state.hovered_note_id = None;
                    state.selected_reference_note_id = None;
                    state.hovered_reference_note_id = None;
                    state.comment_source = CommentSource::Main;
                    state.comment_source_explicit = false;
                    close_stage_menu(state);
                    close_status_menu(state);
                    close_reference_menu(state);
                    state.remove_confirmation_track_id = None;
                    reset_transport(state);
                    reset_reference_transport(state);
                    state.reference_match_enabled = false;
                    schedule_selected_waveform_decode(state, context);
                    schedule_selected_reference_decode(state, context);
                }
                Err(error) => {
                    state.status = error;
                }
            }
            finish_import_batch(state);
            schedule_next_pending_library_operation(state, context);
            context.request_repaint();
        }
        Message::ReplaceCompleted { track_id, result } => {
            if state.pending_import_commit.as_ref()
                != Some(&PendingImportCommit::Replacement {
                    track_id: track_id.clone(),
                })
            {
                return;
            }
            state.pending_import_commit = None;
            state.busy = false;
            if !library_is_ready(state) {
                state.status = library_unavailable_status(state).to_string();
                context.request_repaint();
                return;
            }
            clear_planner_drag(state);
            match result {
                Ok(library) => {
                    let title = library
                        .tracks
                        .iter()
                        .find(|track| track.id == track_id)
                        .map(|track| track.title.clone())
                        .unwrap_or_else(|| String::from("track"));
                    state.library = library;
                    reset_comments_windows(state);
                    refresh_selected_track_index(state);
                    mark_library_snapshot_persisted(state);
                    if state.workspace_mode == WorkspaceMode::Audition {
                        reconcile_audition_queue(state);
                    }
                    state.review_cursor_millis = 0;
                    state.draft_note = None;
                    state.reference_draft_note = None;
                    rollback_persisted_note_drag(state);
                    rollback_reference_persisted_note_drag(state);
                    state.reference_playhead_drag_active = false;
                    state.selected_note_id = None;
                    state.hovered_note_id = None;
                    state.selected_reference_note_id = None;
                    state.hovered_reference_note_id = None;
                    close_stage_menu(state);
                    close_status_menu(state);
                    close_reference_menu(state);
                    state.remove_confirmation_track_id = None;
                    reset_transport(state);
                    reset_reference_transport(state);
                    state.reference_match_enabled = false;
                    state.status = format!("Replaced {title}; existing comments were cleared.");
                    schedule_selected_waveform_decode(state, context);
                    schedule_selected_reference_decode(state, context);
                }
                Err(error) => state.status = error,
            }
            schedule_next_pending_library_operation(state, context);
            context.request_repaint();
        }
        Message::ReferenceImportCompleted {
            track_id,
            path,
            result,
        } => {
            if state.pending_import_commit.as_ref()
                != Some(&PendingImportCommit::AssignedReference {
                    track_id: track_id.clone(),
                    path: path.clone(),
                })
            {
                return;
            }
            state.pending_import_commit = None;
            let failed = result.is_err();
            state.busy = false;
            if !library_is_ready(state) {
                state.status = library_unavailable_status(state).to_string();
                context.request_repaint();
                return;
            }
            record_import_attempt(state, failed);
            match result {
                Ok(library) => {
                    state.library = library;
                    reset_comments_windows(state);
                    refresh_selected_track_index(state);
                    mark_library_snapshot_persisted(state);
                    if state.reference_import_selected_path.is_none() {
                        state.reference_import_selected_path = Some(path);
                    }
                    let title = state
                        .library
                        .tracks
                        .iter()
                        .find(|track| track.id == track_id)
                        .map(|track| track.title.clone())
                        .unwrap_or_else(|| String::from("track"));
                    state.status = format!("Reference track added for {title}.");
                }
                Err(error) => state.status = error,
            }
            let has_more = !state.pending_reference_paths.is_empty();
            if has_more {
                schedule_next_pending_reference_import(state, context);
            } else {
                let selected_path = state.reference_import_selected_path.take();
                state.pending_reference_track_id = None;
                if let Some(path) = selected_path {
                    match storage::set_reference_track_selection(
                        &mut state.library,
                        &track_id,
                        path,
                    ) {
                        Ok(changed) if changed => schedule_library_save(state, context),
                        Ok(_) => {}
                        Err(error) => state.status = error,
                    }
                }
                finish_import_batch(state);
                if state.library.selected_track_id.as_deref() == Some(track_id.as_str()) {
                    reset_reference_transport(state);
                    state.reference_match_enabled = false;
                    schedule_selected_reference_decode(state, context);
                }
                schedule_next_pending_library_operation(state, context);
            }
            close_reference_menu(state);
            context.request_repaint();
        }
        Message::ReferenceSelectionCompleted {
            request_id,
            track_id,
            path,
            result,
        } => {
            complete_reference_selection_commit(state, context, request_id, track_id, path, result)
        }
        Message::ToggleReferenceMenu(track_id) => {
            if library_is_ready(state)
                && !state.busy
                && state
                    .library
                    .tracks
                    .iter()
                    .any(|track| track.id == track_id)
            {
                if state.reference_menu_track_id.as_deref() == Some(track_id.as_str()) {
                    close_reference_menu(state);
                } else {
                    close_stage_menu(state);
                    close_status_menu(state);
                    state.reference_menu_track_id = Some(track_id);
                    state.reference_menu_anchor = Some(keyboard_reference_menu_anchor());
                }
                context.request_repaint();
            }
        }
        Message::ToggleReferenceMenuAt { track_id, position } => {
            if library_is_ready(state)
                && !state.busy
                && state
                    .library
                    .tracks
                    .iter()
                    .any(|track| track.id == track_id)
            {
                if state.reference_menu_track_id.as_deref() == Some(track_id.as_str()) {
                    close_reference_menu(state);
                } else {
                    close_stage_menu(state);
                    close_status_menu(state);
                    state.reference_menu_track_id = Some(track_id);
                    state.reference_menu_anchor =
                        Some(reference_menu_anchor_from_pointer(position));
                }
                context.request_repaint();
            }
        }
        Message::ToggleSettings => {
            toggle_settings(state, context);
        }
        Message::CloseSettings => {
            close_settings(state);
            context.request_repaint();
        }
        Message::DecodeProgress {
            track_id,
            generation,
            progress,
        } => {
            if !decode_progress_is_current(state, &track_id, generation) {
                return;
            }
            if main_source_is_mismatched(state) {
                return;
            }
            state.waveform_track_id = Some(track_id);
            state.waveform_progress = progress.progress;
            state.waveform = Some(progress.waveform);
            context.request_repaint();
        }
        Message::DecodeCompleted {
            track_id,
            generation,
            result,
        } => {
            let Some(retired_request) =
                take_matching_waveform_in_flight(state, &track_id, generation)
            else {
                return;
            };
            state.waveform_cancellation = None;
            if let Some(pending) = state.waveform_pending.take() {
                start_waveform_decode(state, context, pending);
                return;
            }
            if !decode_result_is_current(state, &track_id, generation) {
                return;
            }
            state.waveform_progress = None;
            state.waveform_busy = false;
            let pending_audition = state.workspace_mode == WorkspaceMode::Audition
                && state.audition_pending_play_track_id.as_deref() == Some(track_id.as_str());
            match result {
                Ok(verified) => {
                    let ticket = verified.ticket().clone();
                    let ticket_is_current = ticket.path() == retired_request.path
                        && retired_request
                            .expected_proof
                            .as_ref()
                            .is_none_or(|proof| proof == ticket.proof());
                    if !ticket_is_current {
                        state.waveform = None;
                        state.waveform_source_ticket = None;
                        state.waveform_track_id = None;
                        state.main_source_mismatch = Some(retired_request.path.clone());
                        reset_transport(state);
                        state.reference_match_enabled = false;
                        state.status = String::from(MAIN_SOURCE_MISMATCH_STATUS);
                        context.request_repaint();
                        return;
                    }
                    let ticket = verified.ticket().clone();
                    let waveform = verified.into_waveform();
                    state.waveform_track_id = Some(track_id.clone());
                    state.main_source_mismatch = None;
                    state.status = String::from("Waveform ready.");
                    state.waveform_source_ticket = Some(ticket);
                    state.waveform = Some(waveform);
                    if let Some(ticket) = state.waveform_source_ticket.clone().filter(|ticket| {
                        selected_track(state).is_some_and(|track| {
                            track.id == track_id && track.path == ticket.path()
                        })
                    }) {
                        clear_live_spectrogram(state, AuditionSource::Main);
                        match state.transport.load(
                            state.transport_generation,
                            ticket,
                            state
                                .waveform
                                .as_ref()
                                .map_or(0, |waveform| waveform.duration_millis),
                        ) {
                            Ok(token) => begin_transport_polling(state, token),
                            Err(error) => {
                                state.status = error;
                                if pending_audition {
                                    state.audition_auto_advance = false;
                                    state.audition_play_token = None;
                                    state.audition_pending_play_track_id = None;
                                    advance_audition(state, context);
                                }
                            }
                        }
                    } else {
                        state.status = String::from(
                            "Audio source verification is unavailable; playback is disabled.",
                        );
                        if pending_audition {
                            state.audition_auto_advance = false;
                            state.audition_play_token = None;
                            state.audition_pending_play_track_id = None;
                        }
                    }
                }
                Err(error) if error == "cancelled" => {
                    state.waveform = None;
                    state.waveform_source_ticket = None;
                    state.waveform_track_id = None;
                    if state
                        .pending_comment_playback
                        .as_ref()
                        .is_some_and(|pending| {
                            matches!(
                                &pending.address.owner,
                                NoteOwner::MainTrack(owner_id) if owner_id == &track_id
                            )
                        })
                    {
                        cancel_pending_comment_playback(state);
                    }
                }
                Err(error) => {
                    state.waveform = None;
                    state.waveform_source_ticket = None;
                    state.waveform_track_id = None;
                    if source_error_is_mismatch(&error) {
                        state.main_source_mismatch = Some(retired_request.path.clone());
                        reset_transport(state);
                        state.reference_match_enabled = false;
                        state.status = String::from(MAIN_SOURCE_MISMATCH_STATUS);
                    } else if !main_source_is_mismatched(state) {
                        state.status = format!("Waveform unavailable: {error}");
                    }
                    if state
                        .pending_comment_playback
                        .as_ref()
                        .is_some_and(|pending| {
                            matches!(
                                &pending.address.owner,
                                NoteOwner::MainTrack(owner_id) if owner_id == &track_id
                            )
                        })
                    {
                        cancel_pending_comment_playback(state);
                    }
                    if pending_audition {
                        state.audition_auto_advance = false;
                        state.audition_play_token = None;
                        state.audition_pending_play_track_id = None;
                        advance_audition(state, context);
                    }
                }
            }
            context.request_repaint();
        }
        Message::ReferenceDecodeProgress {
            track_id,
            generation,
            progress,
        } => {
            if !reference_decode_progress_is_current(state, &track_id, generation) {
                return;
            }
            if reference_source_is_mismatched(state) || main_source_is_mismatched(state) {
                return;
            }
            state.reference_waveform_track_id = Some(track_id);
            state.reference_waveform_progress = progress.progress;
            state.reference_waveform = Some(progress.waveform);
            context.request_repaint();
        }
        Message::ReferenceDecodeCompleted {
            track_id,
            generation,
            result,
        } => {
            let Some(retired_request) =
                take_matching_reference_waveform_in_flight(state, &track_id, generation)
            else {
                return;
            };
            state.reference_waveform_cancellation = None;
            if let Some(pending) = state.reference_waveform_pending.take() {
                start_reference_waveform_decode(state, context, pending);
                return;
            }
            if !reference_decode_result_is_current(state, &track_id, generation) {
                return;
            }
            state.reference_waveform_progress = None;
            state.reference_waveform_busy = false;
            match result {
                Ok(verified) => {
                    let ticket = verified.ticket().clone();
                    let ticket_is_current = ticket.path() == retired_request.path
                        && retired_request
                            .expected_proof
                            .as_ref()
                            .is_none_or(|proof| proof == ticket.proof());
                    if !ticket_is_current {
                        state.reference_waveform = None;
                        state.reference_waveform_source_ticket = None;
                        state.reference_waveform_track_id = None;
                        state.reference_source_mismatch = Some(retired_request.path.clone());
                        reset_reference_transport(state);
                        state.reference_match_enabled = false;
                        state.status = String::from(REFERENCE_SOURCE_MISMATCH_STATUS);
                        context.request_repaint();
                        return;
                    }
                    let waveform = verified.into_waveform();
                    state.reference_waveform_track_id = Some(track_id);
                    state.reference_waveform_source_ticket = Some(ticket);
                    state.reference_waveform = Some(waveform);
                    state.reference_source_mismatch = None;
                }
                Err(error) if error == "cancelled" => {
                    state.reference_waveform = None;
                    state.reference_waveform_source_ticket = None;
                    state.reference_waveform_track_id = None;
                    if state
                        .pending_comment_playback
                        .as_ref()
                        .is_some_and(|pending| {
                            matches!(
                                &pending.address.owner,
                                NoteOwner::ReferenceTrack(path) if path == &retired_request.path
                            )
                        })
                    {
                        cancel_pending_comment_playback(state);
                    }
                }
                Err(error) => {
                    state.reference_waveform = None;
                    state.reference_waveform_source_ticket = None;
                    state.reference_waveform_track_id = None;
                    if source_error_is_mismatch(&error) {
                        state.reference_source_mismatch = Some(retired_request.path.clone());
                        reset_reference_transport(state);
                        state.reference_match_enabled = false;
                        state.status = String::from(REFERENCE_SOURCE_MISMATCH_STATUS);
                    } else if !reference_source_is_mismatched(state) {
                        state.status = format!("Reference waveform unavailable: {error}");
                    }
                    if state
                        .pending_comment_playback
                        .as_ref()
                        .is_some_and(|pending| {
                            matches!(
                                &pending.address.owner,
                                NoteOwner::ReferenceTrack(path) if path == &retired_request.path
                            )
                        })
                    {
                        cancel_pending_comment_playback(state);
                    }
                }
            }
            context.request_repaint();
        }
        Message::Frame => {
            let was_audition_playing = state.workspace_mode == WorkspaceMode::Audition
                && state.audition_auto_advance
                && state.transport_playing;
            let was_main_playing = !state.reference_only_playback && state.transport_playing;
            let was_reference_playing = state.reference_transport_playing;
            let mut cleanup_was_reference_only = matches!(
                state.paired_playback_guard,
                PairedPlaybackGuard::StoppingReference { .. }
            );
            let cleanup_was_owning_main = cleanup_owns_main(state);
            update_reference_transport(state);
            cleanup_was_reference_only |= matches!(
                state.paired_playback_guard,
                PairedPlaybackGuard::StoppingReference { .. }
            );
            let cleanup_was_owning_main = cleanup_was_owning_main || cleanup_owns_main(state);
            if cleanup_any_active(state) {
                progress_paired_playback_cleanup(state);
            }
            let snapshot = state.transport.snapshot();
            let audition_play_acknowledged = state.workspace_mode == WorkspaceMode::Audition
                && state.audition_auto_advance
                && state
                    .audition_play_token
                    .is_some_and(|token| transport_command_is_confirmed(snapshot, token));
            let pending_audition = state.workspace_mode == WorkspaceMode::Audition
                && state.audition_pending_play_track_id.is_some();
            let mut main_snapshot_applied = false;
            let mut block_main_snapshot = cleanup_was_owning_main || cleanup_owns_main(state);
            let mut main_transport_source_mismatch = false;
            if snapshot.generation == state.transport_generation {
                if let Some(warning) = state
                    .transport
                    .take_analysis_warning(state.transport_generation)
                    && !block_main_snapshot
                {
                    state.status = format!("Live spectrogram unavailable: {warning}");
                }
                if let Some(error) = state.transport.take_error(state.transport_generation) {
                    if source_error_is_mismatch(&error) {
                        let paired = paired_playback_intended(state);
                        handle_main_transport_source_mismatch(state);
                        main_transport_source_mismatch = true;
                        block_main_snapshot = paired;
                    } else if paired_playback_intended(state) {
                        state.playhead_drag_active = false;
                        state.transport_playing = false;
                        state.transport_polling = false;
                        state.transport_waiting_token = None;
                        state.audition_auto_advance = false;
                        state.audition_play_token = None;
                        state.audition_pending_play_track_id = None;
                        cleanup_transport_failure(state, error, None);
                        block_main_snapshot = true;
                    } else if cleanup_any_active(state) {
                        // A reference-only cleanup owns no main state. Keep
                        // its first error while allowing main snapshots.
                    } else if !block_main_snapshot {
                        state.playhead_drag_active = false;
                        state.transport_playing = false;
                        state.transport_polling = false;
                        state.transport_waiting_token = None;
                        state.audition_auto_advance = false;
                        state.audition_play_token = None;
                        state.audition_pending_play_track_id = None;
                        state.status = error;
                    }
                    if !block_main_snapshot
                        && !main_transport_source_mismatch
                        && !cleanup_any_active(state)
                        && pending_audition
                    {
                        advance_audition(state, context);
                    }
                } else if !block_main_snapshot
                    && state
                        .transport_waiting_token
                        .is_none_or(|token| transport_command_is_confirmed(snapshot, token))
                {
                    state.transport_waiting_token = None;
                    apply_transport_snapshot(state, snapshot);
                    main_snapshot_applied = true;
                }
            }
            if block_main_snapshot {
                progress_paired_playback_cleanup(state);
                refresh_live_spectrograms(state);
                preserve_source_mismatch_status(state);
                return;
            }
            if cleanup_was_reference_only {
                refresh_live_spectrograms(state);
                preserve_source_mismatch_status(state);
                return;
            }
            let natural_audition_completion = main_snapshot_applied
                && (was_audition_playing || audition_play_acknowledged)
                && state.workspace_mode == WorkspaceMode::Audition
                && !state.transport_playing
                && !state.transport_polling
                && state.transport_waiting_token.is_none()
                && snapshot.ready
                && !snapshot.playing
                && state.waveform_track_id.as_deref() == state.library.selected_track_id.as_deref()
                && state
                    .waveform
                    .as_ref()
                    .is_some_and(|waveform| snapshot.position_millis >= waveform.duration_millis);
            if natural_audition_completion && state.loop_selections.main.is_none() {
                advance_audition(state, context);
            } else if state.loop_selections.main.is_none() {
                maybe_start_pending_audition(state, context);
            }
            enforce_loop(state, was_main_playing, was_reference_playing);
            maybe_start_pending_comment_playback(state, context);
            maybe_clear_paired_playback_guard_after_idle(state);
            refresh_live_spectrograms(state);
            preserve_source_mismatch_status(state);
        }
        Message::ToggleLiveSpectrogramMode => {
            state.live_spectrogram_mode = state.live_spectrogram_mode.toggled();
            context.request_repaint();
        }
        Message::SetLiveSpectrogramHistoryScale(scale) => {
            state.live_spectrogram_history_scale = spectrogram::clamp_history_scale(scale);
            context.request_repaint();
        }
        Message::ResizeLiveSpectrogram(message) => {
            update_live_spectrogram_resize(state, message);
            context.request_repaint();
        }
        Message::AdmitLibrarySave => {
            if !state.save_admission_pending {
                return;
            }
            state.save_admission_pending = false;
            dispatch_library_save(state, context);
        }
        Message::RetryLibrarySave => retry_library_save(state, context),
        Message::LibrarySaved { attempt, result } => {
            if state.save_in_flight != Some(attempt) {
                return;
            }
            state.save_in_flight = None;
            match result {
                Ok(()) => {
                    state.persisted_library_revision = attempt.revision;
                    if !main_source_is_mismatched(state) && !reference_source_is_mismatched(state) {
                        state.status = String::from("All changes saved locally.");
                    }
                    if library_dirty(state) {
                        request_library_save_admission(state, context);
                    } else {
                        schedule_next_pending_library_operation(state, context);
                    }
                }
                Err(error) => {
                    if main_source_is_mismatched(state) || reference_source_is_mismatched(state) {
                        preserve_source_mismatch_status(state);
                    } else {
                        state.status = error;
                    }
                }
            }
            context.request_repaint();
        }
        Message::SelectTrack(id) => {
            if library_is_ready(state)
                && !state.busy
                && state.library.tracks.iter().any(|track| track.id == id)
            {
                if state.workspace_mode == WorkspaceMode::Audition {
                    state.audition_heard.retain(|heard_id| heard_id != &id);
                }
                select_track_internal(state, context, id, false);
            }
        }
        Message::SelectWorkspace(mode) => {
            set_workspace_mode(state, context, mode);
        }
        Message::SetAuditionFilter(status) => {
            if !library_is_ready(state)
                || state.busy
                || state.workspace_mode != WorkspaceMode::Audition
            {
                return;
            }
            state.audition_status_filter = status;
            close_status_menu(state);
            state.audition_shuffle_round = 0;
            state.audition_auto_advance = false;
            state.audition_play_token = None;
            state.audition_pending_play_track_id = None;
            state.audition_queue_window = ui::VirtualListWindow::default();
            rebuild_audition_queue(state);
            if let Some(track_id) = state.audition_queue.first().cloned() {
                select_track_internal(state, context, track_id, false);
                state.status = format!(
                    "Auditioning {} tracks in {}.",
                    state.audition_queue.len(),
                    status.label()
                );
            } else {
                reset_transport(state);
                reset_reference_transport(state);
                state.status = format!("No tracks in {}.", status.label());
            }
            context.request_repaint();
        }
        Message::SetReviewStatusFilter(status) => {
            if state.review_status_filter != status {
                state.review_status_filter = status;
                close_stage_menu(state);
                close_status_menu(state);
                state.review_library_window = ui::VirtualListWindow::default();
            }
            state.review_filter_menu_open = false;
            context.request_repaint();
        }
        Message::ReviewLibraryWindowChanged(change) => {
            if state.review_library_window != change.window {
                state.review_library_window = change.window;
                if state.status_menu_host == Some(StatusMenuHost::Library) {
                    close_status_menu(state);
                }
                context.request_repaint();
            }
        }
        Message::AuditionQueueWindowChanged(change) => {
            if state.audition_queue_window != change.window {
                state.audition_queue_window = change.window;
                if state.status_menu_host == Some(StatusMenuHost::Audition) {
                    close_status_menu(state);
                }
                context.request_repaint();
            }
        }
        Message::ReferenceSettingsWindowChanged(change) => {
            if state.reference_settings_window != change.window {
                state.reference_settings_window = change.window;
                context.request_repaint();
            }
        }
        Message::CommentsWindowChanged { source, change } => {
            let window = match source {
                CommentSource::Main => &mut state.main_comments_window,
                CommentSource::Reference => &mut state.reference_comments_window,
            };
            if *window != change.window {
                *window = change.window;
                context.request_repaint();
            }
        }
        Message::PlannerColumnWindowChanged { stage, change } => {
            let window = &mut state.planner_windows[planner_stage_index(stage)];
            if *window != change.window {
                *window = change.window;
                if state.status_menu_host == Some(StatusMenuHost::Planner) {
                    close_status_menu(state);
                }
                context.request_repaint();
            }
        }
        Message::ToggleReviewFilterMenu => {
            state.review_filter_menu_open = !state.review_filter_menu_open;
            context.request_repaint();
        }
        Message::SetPlannerStatusFilter(status) => {
            if state.planner_status_filter != status {
                state.planner_status_filter = status;
                close_stage_menu(state);
                close_status_menu(state);
                context.end_drag();
                clear_planner_drag(state);
                state.planner_windows = std::array::from_fn(|_| ui::VirtualListWindow::default());
            }
            context.request_repaint();
        }
        Message::ShuffleAudition => {
            shuffle_audition(state, context);
        }
        Message::ToggleFavorite(id) => {
            if library_is_ready(state)
                && !state.busy
                && let Some(track) = state.library.tracks.iter_mut().find(|track| track.id == id)
            {
                track.favorite = !track.favorite;
                schedule_library_save(state, context);
            }
        }
        Message::ToggleStageMenu(id) => {
            if library_is_ready(state)
                && !state.busy
                && state.library.tracks.iter().any(|track| track.id == id)
            {
                if state.stage_menu_track_id.as_deref() == Some(id.as_str()) {
                    close_stage_menu(state);
                } else {
                    close_status_menu(state);
                    state.stage_menu_track_id = Some(id);
                    state.stage_menu_anchor = Some(keyboard_stage_menu_anchor(state));
                }
                context.request_repaint();
            }
        }
        Message::ToggleStageMenuAt { track_id, position } => {
            if library_is_ready(state)
                && !state.busy
                && state
                    .library
                    .tracks
                    .iter()
                    .any(|track| track.id == track_id)
            {
                if state.stage_menu_track_id.as_deref() == Some(track_id.as_str()) {
                    close_stage_menu(state);
                } else {
                    close_status_menu(state);
                    state.stage_menu_track_id = Some(track_id);
                    state.stage_menu_anchor = Some(stage_menu_anchor_from_pointer(position));
                }
                context.request_repaint();
            }
        }
        Message::SetStage { track_id, stage } => {
            if library_is_ready(state) && !state.busy {
                let changed = match storage::set_track_stage(&mut state.library, &track_id, stage) {
                    Ok(changed) => changed,
                    Err(error) => {
                        state.status = error;
                        context.request_repaint();
                        return;
                    }
                };
                close_stage_menu(state);
                close_status_menu(state);
                clear_planner_drag(state);
                if changed {
                    state.status = format!("Stage set to {}.", stage.label());
                    schedule_library_save(state, context);
                }
                context.request_repaint();
            }
        }
        Message::ToggleStatusMenuAt { track_id, host } => {
            toggle_status_menu(state, track_id, host, context);
        }
        Message::RemoveReferenceTrack(path) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            let selected_affected = selected_track(state)
                .and_then(|track| track.reference_path.as_ref())
                .is_some_and(|selected_path| selected_path == &path);
            let cleared_assignments =
                match storage::remove_reference_track(&mut state.library, &path) {
                    Ok(cleared_assignments) => cleared_assignments,
                    Err(error) => {
                        state.status = error;
                        context.request_repaint();
                        return;
                    }
                };
            close_stage_menu(state);
            close_status_menu(state);
            close_reference_menu(state);
            if selected_affected {
                state.reference_draft_note = None;
                state.selected_reference_note_id = None;
                state.hovered_reference_note_id = None;
                reset_reference_transport(state);
                state.reference_match_enabled = false;
                schedule_selected_reference_decode(state, context);
            }
            state.status = if cleared_assignments == 0 {
                format!(
                    "Removed {} from the reference catalog.",
                    reference_track_name(&path)
                )
            } else {
                format!(
                    "Removed {} and cleared {} track assignment{}.",
                    reference_track_name(&path),
                    cleared_assignments,
                    plural(cleared_assignments)
                )
            };
            schedule_library_save(state, context);
            context.request_repaint();
        }
        Message::SetReferenceTrack { track_id, path } => {
            if !library_is_ready(state) {
                return;
            }
            if state.busy {
                return;
            }
            if library_persistence_pending(state) {
                state.status = String::from(
                    "Saving the library — try selecting a reference again in a moment.",
                );
                context.request_repaint();
                return;
            }
            if !state
                .library
                .tracks
                .iter()
                .any(|track| track.id == track_id)
            {
                state.status = String::from("That track is no longer in the library.");
                close_reference_menu(state);
                context.request_repaint();
                return;
            }
            let Some(expected_proof) = state
                .library
                .reference_tracks
                .iter()
                .find(|reference| reference.path == path)
                .map(|reference| reference.source_provenance().verified_proof().cloned())
            else {
                state.status = String::from(
                    "That reference is no longer in the catalog; remove and re-import it.",
                );
                close_reference_menu(state);
                context.request_repaint();
                return;
            };
            state.next_reference_selection_request_id = state
                .next_reference_selection_request_id
                .checked_add(1)
                .expect("reference selection request id overflow");
            let request = AudioImportRequest {
                target: AudioImportTarget::ReferenceSelection {
                    request_id: state.next_reference_selection_request_id,
                    track_id,
                    expected_proof,
                },
                path: path.clone(),
            };
            state.busy = true;
            state.status = format!("Checking reference {}…", reference_track_name(&path));
            close_reference_menu(state);
            state.audio_import_in_flight = Some(request.clone());
            start_audio_import_preflight(context, request);
            context.request_repaint();
        }
        Message::SetStatus { track_id, status } => {
            if library_is_ready(state) && !state.busy {
                let pending_selected_audition = state.workspace_mode == WorkspaceMode::Audition
                    && state.library.selected_track_id.as_deref() == Some(track_id.as_str())
                    && state.audition_pending_play_track_id.as_deref() == Some(track_id.as_str())
                    && status != state.audition_status_filter;
                let changed = match storage::set_track_status(&mut state.library, &track_id, status)
                {
                    Ok(changed) => changed,
                    Err(error) => {
                        state.status = error;
                        close_status_menu(state);
                        context.request_repaint();
                        return;
                    }
                };
                close_status_menu(state);
                if changed {
                    if state.workspace_mode == WorkspaceMode::Audition {
                        sync_audition_queue_after_status_change(state, &track_id);
                        if pending_selected_audition {
                            disarm_audition_auto_advance(state);
                            advance_audition(state, context);
                        }
                    }
                    state.status = format!("Status set to {}.", status.label());
                    schedule_library_save(state, context);
                }
                context.request_repaint();
            }
        }
        Message::PlannerCardDrag { track_id, message } => {
            if !library_is_ready(state)
                || state.busy
                || state.workspace_mode != WorkspaceMode::Planner
            {
                return;
            }
            if !state
                .library
                .tracks
                .iter()
                .any(|track| track.id == track_id)
            {
                context.end_drag();
                clear_planner_drag(state);
                state.status = String::from("That track is no longer in the library.");
                context.request_repaint();
                return;
            }
            match message {
                ui::DragHandleMessage::Started { .. } => {
                    state.planner_drag_source_track_id = Some(track_id.clone());
                    state.planner_drag_target = None;
                    close_stage_menu(state);
                    close_status_menu(state);
                    state.remove_confirmation_track_id = None;
                    state.planner_drag_pointer = drag_message_position(message);
                    let title = state
                        .library
                        .tracks
                        .iter()
                        .find(|track| track.id == track_id)
                        .map_or_else(|| String::from("track"), |track| track.title.clone());
                    state.status = format!("Dragging {title}…");
                    if let Some(pointer) = state.planner_drag_pointer {
                        context.begin_drag(DragRequest::new(
                            DragPreview::sized(
                                title,
                                Vector2::new(
                                    PLANNER_DRAG_PREVIEW_CARD_WIDTH,
                                    PLANNER_DRAG_PREVIEW_CARD_HEIGHT,
                                ),
                            ),
                            pointer,
                        ));
                    }
                    context.request_repaint();
                }
                ui::DragHandleMessage::Moved { .. } => {
                    if state.planner_drag_source_track_id.as_deref() != Some(track_id.as_str()) {
                        return;
                    }
                    state.planner_drag_pointer = drag_message_position(message);
                    context.request_paint_only();
                }
                ui::DragHandleMessage::Ended { .. } => {
                    if state.planner_drag_source_track_id.as_deref() != Some(track_id.as_str()) {
                        return;
                    }
                    context.end_drag();
                    clear_planner_drag(state);
                    state.status = String::from("Drag canceled.");
                    context.request_repaint();
                }
                ui::DragHandleMessage::Cancelled { .. } => {
                    if state.planner_drag_source_track_id.as_deref() != Some(track_id.as_str()) {
                        return;
                    }
                    context.end_drag();
                    clear_planner_drag(state);
                    state.status = String::from("Drag canceled.");
                    context.request_repaint();
                }
                ui::DragHandleMessage::DoubleActivate { .. } => {
                    context.request_repaint();
                }
            }
        }
        Message::PlannerInsertionHovered(target) => {
            let Some(source_id) = state.planner_drag_source_track_id.as_deref() else {
                return;
            };
            if !planner_insertion_target_is_valid(
                &state.library,
                source_id,
                &target,
                state.planner_status_filter,
            ) {
                if state.planner_drag_target.take().is_some() {
                    context.request_repaint();
                }
                return;
            }
            if state.planner_drag_target.as_ref() == Some(&target) {
                return;
            }
            state.planner_drag_target = Some(target.clone());
            state.status =
                planner_insertion_status(&state.library, &target, state.planner_status_filter);
            context.request_repaint();
        }
        Message::PlannerInsertionHoverCleared(target) => {
            if state.planner_drag_target.as_ref() == Some(&target) {
                state.planner_drag_target = None;
                context.request_repaint();
            }
        }
        Message::PlannerInsertionCleared => {
            if state.planner_drag_target.take().is_some() {
                context.request_repaint();
            }
        }
        Message::PlannerInsertionDropped(target) => {
            if !library_is_ready(state)
                || state.busy
                || state.workspace_mode != WorkspaceMode::Planner
            {
                return;
            }
            let Some(source_id) = state.planner_drag_source_track_id.clone() else {
                return;
            };
            context.end_drag();
            clear_planner_drag(state);
            match storage::move_track_to_planner_slot(
                &mut state.library,
                &source_id,
                target.stage,
                target.slot,
                state.planner_status_filter,
            ) {
                Ok(true) => {
                    close_stage_menu(state);
                    close_status_menu(state);
                    state.status = planner_insertion_status(
                        &state.library,
                        &PlannerInsertionTarget {
                            stage: target.stage,
                            slot: target.slot,
                        },
                        state.planner_status_filter,
                    );
                    schedule_library_save(state, context);
                }
                Ok(false) => {
                    state.status = String::from("Track is already at that position.");
                }
                Err(error) => state.status = error,
            }
            context.request_repaint();
        }
        Message::RequestRemoveTrack(id) => {
            if library_is_ready(state)
                && !state.busy
                && state.library.tracks.iter().any(|track| track.id == id)
            {
                close_stage_menu(state);
                close_status_menu(state);
                state.remove_confirmation_track_id = Some(id);
                state.status = String::from(
                    "Confirm removal from the library. The source audio file will stay on disk.",
                );
                context.request_repaint();
            }
        }
        Message::ConfirmRemoveTrack(id) => {
            if !library_is_ready(state)
                || state.busy
                || state.remove_confirmation_track_id.as_deref() != Some(id.as_str())
            {
                return;
            }
            let selected = state.library.selected_track_id.as_deref() == Some(id.as_str());
            let removed = match storage::remove_track(&mut state.library, &id) {
                Ok(removed) => removed,
                Err(error) => {
                    state.remove_confirmation_track_id = None;
                    state.status = error;
                    context.request_repaint();
                    return;
                }
            };
            refresh_selected_track_index(state);
            reset_comments_windows(state);
            state.remove_confirmation_track_id = None;
            close_stage_menu(state);
            close_status_menu(state);
            clear_planner_drag(state);
            if state.workspace_mode == WorkspaceMode::Audition {
                reconcile_audition_queue(state);
            }
            if selected {
                cancel_pending_comment_playback(state);
                state.draft_note = None;
                state.reference_draft_note = None;
                rollback_persisted_note_drag(state);
                rollback_reference_persisted_note_drag(state);
                state.reference_playhead_drag_active = false;
                state.selected_note_id = None;
                state.hovered_note_id = None;
                state.selected_reference_note_id = None;
                state.hovered_reference_note_id = None;
                state.comment_source = CommentSource::Main;
                state.comment_source_explicit = false;
                state.library.selected_track_id =
                    storage::selection_after_removal(&state.library, removed.0);
                refresh_selected_track_index(state);
                close_reference_menu(state);
                reset_waveform_decode(state);
                reset_reference_waveform_decode(state);
                reset_transport(state);
                reset_reference_transport(state);
                state.reference_match_enabled = false;
            }
            state.status = format!(
                "Removed {} from the library. The source audio file remains on disk.",
                removed.1.title
            );
            schedule_library_save(state, context);
            if selected {
                schedule_selected_waveform_decode(state, context);
                schedule_selected_reference_decode(state, context);
            }
            context.request_repaint();
        }
        Message::CancelRemoveTrack => {
            state.remove_confirmation_track_id = None;
            state.status = String::from("Track kept in the library.");
            context.request_repaint();
        }
        Message::TogglePlayback => toggle_playback(state, context),
        Message::StopPlayback => stop_playback(state, context),
        Message::NewNoteAtCurrentTime => start_note_at_current_time(state, context),
        Message::AuditionPlay => play_audition(state, context),
        Message::AuditionPrevious => previous_audition(state, context),
        Message::AuditionNext => next_audition(state, context),
        Message::SelectAuditionSource(source) => select_audition_source(state, context, source),
        Message::ActivateAuditionSource(source) => activate_audition_source(state, context, source),
        Message::SelectCommentSource(source) => {
            state.comment_source = source;
            state.comment_source_explicit = true;
            if (source == CommentSource::Main && !main_annotations_available(state))
                || (source == CommentSource::Reference && !reference_annotations_available(state))
            {
                let _ = match source {
                    CommentSource::Main => reject_unknown_main_source(state, context),
                    CommentSource::Reference => reject_unknown_reference_source(state, context),
                };
            }
            context.request_repaint();
        }
        Message::ToggleReferenceMatch => {
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
            {
                return;
            }
            if state.reference_match_enabled {
                state.reference_match_enabled = false;
                sync_audition_output_gains(state);
                state.status = String::from("Reference loudness matching disabled.");
            } else {
                let Some(gain_db) = current_loudness_match_gain_db(state) else {
                    state.status = String::from(
                        "Reference matching needs LUFS analysis for both the imported and reference tracks.",
                    );
                    context.request_repaint();
                    return;
                };
                state.reference_match_enabled = true;
                sync_audition_output_gains(state);
                state.status =
                    format!("Reference matched to the imported track · {gain_db:+.1} dB.");
            }
            context.request_repaint();
        }
        Message::AuditionVolumeChanged(edit) => {
            if let Some(volume) = edit.value_change() {
                let volume = transport::normalize_volume(volume);
                state.audition_volume = volume;
                // This gain is applied only by Rodio's output player. The
                // decoder's integrated LUFS value is computed from raw samples.
                sync_audition_output_gains(state);
            }
            if edit.events().iter().any(|event| event.phase.is_terminal()) {
                context.repaint(ui::RepaintScope::Projection);
            } else {
                context.request_paint_only();
            }
        }
        Message::WaveformLoopDragStarted { .. } => {
            if !library_is_ready(state)
                || state.busy
                || state.waveform_busy
                || state.waveform.is_none()
            {
                return;
            }
            if reject_main_source_mismatch(state, context) {
                return;
            }
            disarm_audition_auto_advance(state);
            set_audition_source(state, AuditionSource::Main);
            state.loop_selections.clear(AuditionSource::Main);
            state.status = String::from("Paint a loop across the main waveform…");
            context.request_repaint();
        }
        Message::WaveformLoopDragEnded {
            start_ratio,
            end_ratio,
        } => finish_loop_selection(state, context, AuditionSource::Main, start_ratio, end_ratio),
        Message::WaveformLoopDragCancelled => {
            if !library_is_ready(state) {
                return;
            }
            state.loop_selections.clear(AuditionSource::Main);
            state.status = String::from("Loop selection canceled.");
            context.request_repaint();
        }
        Message::ReferenceLoopDragStarted { .. } => {
            if !library_is_ready(state)
                || state.busy
                || state.reference_waveform_busy
                || state.waveform_busy
            {
                return;
            }
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
            {
                return;
            }
            if selected_reference_details(state).is_none() {
                return;
            }
            disarm_audition_auto_advance(state);
            set_audition_source(state, AuditionSource::Reference);
            state.loop_selections.clear(AuditionSource::Reference);
            state.status = String::from("Paint a loop across the reference waveform…");
            context.request_repaint();
        }
        Message::ReferenceLoopDragEnded {
            start_ratio,
            end_ratio,
        } => finish_loop_selection(
            state,
            context,
            AuditionSource::Reference,
            start_ratio,
            end_ratio,
        ),
        Message::ReferenceLoopDragCancelled => {
            if !library_is_ready(state) {
                return;
            }
            state.loop_selections.clear(AuditionSource::Reference);
            state.status = String::from("Reference loop selection canceled.");
            context.request_repaint();
        }
        Message::ReferenceWaveformClicked { ratio } => {
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
            {
                return;
            }
            seek_reference_waveform_position(state, context, ratio, true)
        }
        Message::ReferenceCommentClicked { ratio } => {
            if !library_is_ready(state) {
                return;
            }
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
                || reject_unknown_reference_source(state, context)
            {
                return;
            }
            state.comment_source = CommentSource::Reference;
            state.comment_source_explicit = true;
            start_reference_comment_draft(state, context, ratio)
        }
        Message::WaveformClicked { ratio, lower } => {
            if !library_is_ready(state) || state.busy || state.waveform_busy {
                return;
            }
            if reject_main_source_mismatch(state, context) {
                return;
            }
            if lower && reject_unknown_main_source(state, context) {
                return;
            }
            let Some(waveform) = state.waveform.as_ref() else {
                return;
            };
            let duration_millis = waveform.duration_millis;
            let time_millis = waveform::millis_for_ratio(ratio, duration_millis);
            if lower {
                state.comment_source = CommentSource::Main;
                state.comment_source_explicit = true;
            }
            state.hovered_note_id = None;
            if lower {
                start_main_note_draft(state, context, time_millis);
            } else {
                set_audition_source(state, AuditionSource::Main);
                state.loop_selections.clear(AuditionSource::Main);
                state.draft_note = None;
                state.selected_note_id = None;
                disarm_audition_auto_advance(state);
                seek_review_position(state, context, ratio, true);
            }
            context.request_repaint();
        }
        Message::WaveformPlayheadDragStarted { ratio } => {
            if !library_is_ready(state)
                || state.busy
                || state.waveform_busy
                || state.waveform.is_none()
            {
                return;
            }
            if reject_main_source_mismatch(state, context) {
                return;
            }
            rollback_persisted_note_drag(state);
            set_audition_source(state, AuditionSource::Main);
            state.loop_selections.clear(AuditionSource::Main);
            state.playhead_drag_active = true;
            state.draft_note = None;
            state.hovered_note_id = None;
            seek_review_position(state, context, ratio, false);
        }
        Message::WaveformPlayheadDragEnded { ratio } => {
            if !state.playhead_drag_active {
                return;
            }
            state.playhead_drag_active = false;
            seek_review_position(state, context, ratio, true);
        }
        Message::WaveformPlayheadDragCancelled => {
            state.playhead_drag_active = false;
            context.request_repaint();
        }
        Message::ReferencePlayheadDragStarted { ratio } => {
            if !library_is_ready(state)
                || state.busy
                || state.waveform_busy
                || state.reference_waveform_busy
            {
                return;
            }
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
            {
                return;
            }
            if selected_reference_details(state).is_none() {
                return;
            }
            rollback_reference_persisted_note_drag(state);
            set_audition_source(state, AuditionSource::Reference);
            state.loop_selections.clear(AuditionSource::Reference);
            state.reference_playhead_drag_active = true;
            state.reference_draft_note = None;
            state.hovered_reference_note_id = None;
            seek_reference_waveform_position(state, context, ratio, false);
        }
        Message::ReferencePlayheadDragEnded { ratio } => {
            if !state.reference_playhead_drag_active {
                return;
            }
            state.reference_playhead_drag_active = false;
            seek_reference_waveform_position(state, context, ratio, true);
        }
        Message::ReferencePlayheadDragCancelled => {
            state.reference_playhead_drag_active = false;
            context.request_repaint();
        }
        Message::CommentDragStarted { ratio, address } => {
            if !library_is_ready(state) || state.busy || state.waveform_busy {
                return;
            }
            if reject_main_source_mismatch(state, context) {
                return;
            }
            if reject_unknown_main_source(state, context) {
                return;
            }
            if let Some(address) = address {
                start_persisted_note_drag(state, context, address);
            } else {
                rollback_persisted_note_drag(state);
                move_draft_note(state, context, ratio);
            }
        }
        Message::CommentDragEnded { ratio } => {
            if !library_is_ready(state) || state.busy || state.waveform_busy {
                return;
            }
            if reject_main_source_mismatch(state, context) {
                return;
            }
            if reject_unknown_main_source(state, context) {
                return;
            }
            if state.persisted_note_drag.is_some() {
                finish_persisted_note_drag(state, context, ratio);
            } else {
                move_draft_note(state, context, ratio);
            }
        }
        Message::CommentDragCancelled => {
            if !library_is_ready(state) {
                return;
            }
            if state.persisted_note_drag.is_some() {
                rollback_persisted_note_drag(state);
            } else {
                state.draft_note = None;
            }
            clear_pending_seek_intent(state, AuditionSource::Main);
            state.status = String::from("Comment canceled.");
            context.request_repaint();
        }
        Message::ReferenceCommentDragStarted { ratio, address } => {
            if !library_is_ready(state)
                || state.busy
                || state.waveform_busy
                || state.reference_waveform_busy
            {
                return;
            }
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
                || reject_unknown_reference_source(state, context)
            {
                return;
            }
            if let Some(address) = address {
                start_reference_persisted_note_drag(state, context, address);
            } else {
                rollback_reference_persisted_note_drag(state);
                move_reference_draft_note(state, context, ratio);
            }
        }
        Message::ReferenceCommentDragEnded { ratio } => {
            if !library_is_ready(state)
                || state.busy
                || state.waveform_busy
                || state.reference_waveform_busy
            {
                return;
            }
            if reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
                || reject_unknown_reference_source(state, context)
            {
                return;
            }
            if state.reference_persisted_note_drag.is_some() {
                finish_reference_persisted_note_drag(state, context, ratio);
            } else {
                move_reference_draft_note(state, context, ratio);
            }
        }
        Message::ReferenceCommentDragCancelled => {
            if !library_is_ready(state) {
                return;
            }
            if state.reference_persisted_note_drag.is_some() {
                rollback_reference_persisted_note_drag(state);
            } else {
                state.reference_draft_note = None;
            }
            clear_pending_seek_intent(state, AuditionSource::Reference);
            state.status = String::from("Reference comment canceled.");
            context.request_repaint();
        }
        Message::DraftNoteChanged { identity, body } => {
            if !active_draft_matches(state.draft_note.as_ref(), &identity) {
                return;
            }
            if !main_annotations_available(state) && reject_unknown_main_source(state, context) {
                return;
            }
            if let Some(draft) = state.draft_note.as_mut() {
                draft.body = body;
                context.request_repaint();
            }
        }
        Message::SaveDraftNote(identity) => {
            if !active_draft_matches(state.draft_note.as_ref(), &identity) {
                return;
            }
            if !main_annotations_available(state) && reject_unknown_main_source(state, context) {
                return;
            }
            save_draft_note(state, context, &identity)
        }
        Message::CancelDraftNote(identity) => {
            if !active_draft_matches(state.draft_note.as_ref(), &identity) {
                return;
            }
            if !library_is_ready(state) {
                return;
            }
            state.draft_note = None;
            rollback_persisted_note_drag(state);
            clear_pending_seek_intent(state, AuditionSource::Main);
            state.status = String::from("Comment canceled.");
            context.request_repaint();
        }
        Message::SelectNote(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_main_source(state, context) {
                return;
            }
            if !is_current_main_note_address(state, &address) {
                return;
            }
            state.comment_source = CommentSource::Main;
            state.comment_source_explicit = true;
            rollback_persisted_note_drag(state);
            let note = selected_track(state)
                .and_then(|track| track.notes.iter().find(|note| note.id == address.note_id))
                .cloned();
            if let Some(note) = note {
                state.selected_note_id = Some(address.clone());
                set_pending_seek_intent(state, AuditionSource::Main, note.time_millis);
                state.review_cursor_millis = note.time_millis;
                state.transport_position_millis = note.time_millis;
                state.draft_note = None;
                reveal_comment_row(state, context, CommentSource::Main, &address);
                state.status = format!(
                    "Selected comment at {}.",
                    format_timestamp(note.time_millis)
                );
                context.request_repaint();
            }
        }
        Message::PlayComment { address } => {
            let source = address.source();
            if (source == CommentSource::Main && !main_annotations_available(state))
                || (source == CommentSource::Reference && !reference_annotations_available(state))
            {
                let _ = match source {
                    CommentSource::Main => reject_unknown_main_source(state, context),
                    CommentSource::Reference => reject_unknown_reference_source(state, context),
                };
                return;
            }
            play_comment(state, context, address)
        }
        Message::CommentHoverStarted(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_main_source(state, context) {
                return;
            }
            if is_current_main_note_address(state, &address)
                && state.hovered_note_id.as_ref() != Some(&address)
            {
                state.hovered_note_id = Some(address);
                context.request_repaint();
            }
        }
        Message::CommentHoverEnded(address) => {
            if state.hovered_note_id.as_ref() == Some(&address) {
                state.hovered_note_id = None;
                context.request_repaint();
            }
        }
        Message::ReferenceCommentHoverStarted(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_reference_source(state, context) {
                return;
            }
            if is_current_reference_note_address(state, &address)
                && state.hovered_reference_note_id.as_ref() != Some(&address)
            {
                state.hovered_reference_note_id = Some(address);
                context.request_repaint();
            }
        }
        Message::ReferenceCommentHoverEnded(address) => {
            if state.hovered_reference_note_id.as_ref() == Some(&address) {
                state.hovered_reference_note_id = None;
                context.request_repaint();
            }
        }
        Message::FocusCommentEditor(editor_id) => {
            context.focus(editor_id);
            context.request_repaint();
        }
        Message::EditNote(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_main_source(state, context) {
                return;
            }
            if !is_current_main_note_address(state, &address) {
                return;
            }
            state.comment_source = CommentSource::Main;
            state.comment_source_explicit = true;
            rollback_persisted_note_drag(state);
            let note = selected_track(state)
                .and_then(|track| track.notes.iter().find(|note| note.id == address.note_id))
                .cloned();
            if let Some(note) = note {
                let editor_id = main_inline_comment_editor_id(&address);
                let nonce = allocate_note_draft_nonce(state);
                set_pending_seek_intent(state, AuditionSource::Main, note.time_millis);
                state.review_cursor_millis = note.time_millis;
                state.transport_position_millis = note.time_millis;
                state.selected_note_id = Some(address.clone());
                state.draft_note = Some(NoteDraft {
                    owner: address.owner.clone(),
                    note_id: Some(note.id),
                    nonce,
                    time_millis: note.time_millis,
                    body: note.body,
                });
                reveal_comment_row(state, context, CommentSource::Main, &address);
                state.status =
                    format!("Editing comment at {}.", format_timestamp(note.time_millis));
                context.request_repaint();
                context.focus(editor_id);
                context.after(
                    Duration::from_millis(1),
                    Message::FocusCommentEditor(editor_id),
                );
            }
        }
        Message::DeleteNote(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_main_source(state, context) {
                return;
            }
            if !is_current_main_note_address(state, &address) {
                return;
            }
            rollback_persisted_note_drag(state);
            let removed = selected_track_mut(state).and_then(|track| {
                track
                    .notes
                    .iter()
                    .position(|note| note.id == address.note_id)
                    .map(|index| track.notes.remove(index))
            });
            if removed.is_some() {
                if state.hovered_note_id.as_ref() == Some(&address) {
                    state.hovered_note_id = None;
                }
                if state
                    .selected_note_id
                    .as_ref()
                    .is_some_and(|selected_address| selected_address == &address)
                {
                    state.selected_note_id = None;
                    clear_pending_seek_intent(state, AuditionSource::Main);
                }
                if state
                    .draft_note
                    .as_ref()
                    .is_some_and(|draft| draft.address().as_ref() == Some(&address))
                {
                    state.draft_note = None;
                }
                state.status = String::from("Comment deleted locally.");
                schedule_library_save(state, context);
            } else {
                state.status = String::from("That comment no longer exists.");
            }
            context.request_repaint();
        }
        Message::ReferenceDraftNoteChanged { identity, body } => {
            if !active_draft_matches(state.reference_draft_note.as_ref(), &identity) {
                return;
            }
            if !reference_annotations_available(state)
                && reject_unknown_reference_source(state, context)
            {
                return;
            }
            if let Some(draft) = state.reference_draft_note.as_mut() {
                draft.body = body;
                context.request_repaint();
            }
        }
        Message::SaveReferenceDraftNote(identity) => {
            if !active_draft_matches(state.reference_draft_note.as_ref(), &identity) {
                return;
            }
            if !reference_annotations_available(state)
                && reject_unknown_reference_source(state, context)
            {
                return;
            }
            save_reference_draft_note(state, context, &identity)
        }
        Message::CancelReferenceDraftNote(identity) => {
            if !active_draft_matches(state.reference_draft_note.as_ref(), &identity) {
                return;
            }
            if !library_is_ready(state) {
                return;
            }
            state.reference_draft_note = None;
            clear_pending_seek_intent(state, AuditionSource::Reference);
            state.status = String::from("Reference comment canceled.");
            context.request_repaint();
        }
        Message::SelectReferenceNote(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_reference_source(state, context) {
                return;
            }
            if !is_current_reference_note_address(state, &address) {
                return;
            }
            state.comment_source = CommentSource::Reference;
            state.comment_source_explicit = true;
            rollback_reference_persisted_note_drag(state);
            let note = selected_reference_notes(state)
                .iter()
                .find(|note| note.id == address.note_id)
                .cloned();
            if let Some(note) = note {
                state.selected_reference_note_id = Some(address.clone());
                set_pending_seek_intent(state, AuditionSource::Reference, note.time_millis);
                state.reference_transport_position_millis = note.time_millis;
                state.reference_draft_note = None;
                reveal_comment_row(state, context, CommentSource::Reference, &address);
                state.status = format!(
                    "Selected reference comment at {}.",
                    format_timestamp(note.time_millis)
                );
                context.request_repaint();
            }
        }
        Message::EditReferenceNote(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_reference_source(state, context) {
                return;
            }
            if !is_current_reference_note_address(state, &address) {
                return;
            }
            state.comment_source = CommentSource::Reference;
            state.comment_source_explicit = true;
            rollback_reference_persisted_note_drag(state);
            let note = selected_reference_notes(state)
                .iter()
                .find(|note| note.id == address.note_id)
                .cloned();
            if let Some(note) = note {
                let editor_id = reference_inline_comment_editor_id(&address);
                let nonce = allocate_note_draft_nonce(state);
                set_pending_seek_intent(state, AuditionSource::Reference, note.time_millis);
                state.selected_reference_note_id = Some(address.clone());
                state.reference_transport_position_millis = note.time_millis;
                state.reference_draft_note = Some(NoteDraft {
                    owner: address.owner.clone(),
                    note_id: Some(note.id),
                    nonce,
                    time_millis: note.time_millis,
                    body: note.body,
                });
                reveal_comment_row(state, context, CommentSource::Reference, &address);
                state.status = format!(
                    "Editing reference comment at {}.",
                    format_timestamp(note.time_millis)
                );
                context.request_repaint();
                context.focus(editor_id);
                context.after(
                    Duration::from_millis(1),
                    Message::FocusCommentEditor(editor_id),
                );
            }
        }
        Message::DeleteReferenceNote(address) => {
            if !library_is_ready(state) || state.busy {
                return;
            }
            if reject_unknown_reference_source(state, context) {
                return;
            }
            if !is_current_reference_note_address(state, &address) {
                return;
            }
            let removed = selected_reference_track_mut(state).and_then(|reference| {
                reference
                    .notes
                    .iter()
                    .position(|note| note.id == address.note_id)
                    .map(|index| reference.notes.remove(index))
            });
            if removed.is_some() {
                if state.selected_reference_note_id.as_ref() == Some(&address) {
                    state.selected_reference_note_id = None;
                    clear_pending_seek_intent(state, AuditionSource::Reference);
                }
                if state.hovered_reference_note_id.as_ref() == Some(&address) {
                    state.hovered_reference_note_id = None;
                }
                if state
                    .reference_draft_note
                    .as_ref()
                    .is_some_and(|draft| draft.address().as_ref() == Some(&address))
                {
                    state.reference_draft_note = None;
                }
                state.status = String::from("Reference comment deleted locally.");
                schedule_library_save(state, context);
            } else {
                state.status = String::from("That reference comment no longer exists.");
            }
            context.request_repaint();
        }
    }
}

fn selected_reference_details(state: &AppState) -> Option<(PathBuf, u64)> {
    if main_source_is_mismatched(state) || reference_source_is_mismatched(state) {
        return None;
    }
    selected_track(state).and_then(|track| {
        let path = track.reference_path.clone()?;
        let duration_millis = state
            .reference_waveform
            .as_ref()
            .filter(|_| {
                !state.reference_waveform_busy
                    && state.reference_waveform_track_id.as_deref() == Some(track.id.as_str())
            })
            .map(|waveform| waveform.duration_millis)?;
        Some((path, duration_millis))
    })
}

fn selected_main_duration(state: &AppState) -> Option<u64> {
    state
        .waveform
        .as_ref()
        .filter(|_| {
            state.library.selected_track_id.as_deref() == state.waveform_track_id.as_deref()
        })
        .map(|waveform| waveform.duration_millis)
}

fn reference_source_ticket_for_path(
    state: &AppState,
    path: &Path,
) -> Option<crate::source::VerifiedSourceTicket> {
    let selected_track_id = state.library.selected_track_id.as_deref()?;
    let track = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == selected_track_id)?;
    if track.reference_path.as_deref() != Some(path)
        || state.reference_waveform_track_id.as_deref() != Some(selected_track_id)
    {
        return None;
    }
    state
        .reference_waveform_source_ticket
        .as_ref()
        .filter(|ticket| ticket.path() == path)
        .cloned()
}

fn projected_loop_bounds(selection: LoopSelection, duration_millis: u64) -> Option<(u64, u64)> {
    let start_millis = waveform::millis_for_ratio(selection.start_ratio, duration_millis);
    let end_millis = waveform::millis_for_ratio(selection.end_ratio, duration_millis);
    (end_millis > start_millis).then_some((start_millis, end_millis))
}

fn selected_duration_for_source(state: &AppState, source: AuditionSource) -> Option<u64> {
    match source {
        AuditionSource::Main => selected_main_duration(state),
        AuditionSource::Reference => {
            selected_reference_details(state).map(|(_, duration)| duration)
        }
    }
}

fn loop_bounds_for_selection(
    state: &AppState,
    source: AuditionSource,
    selection: LoopSelection,
) -> Option<LoopBounds> {
    let (start_millis, end_millis) =
        projected_loop_bounds(selection, selected_duration_for_source(state, source)?)?;
    Some(LoopBounds {
        start_millis,
        end_millis,
    })
}

fn loop_bounds_for_source(state: &AppState, source: AuditionSource) -> Option<LoopBounds> {
    loop_bounds_for_selection(state, source, state.loop_selections.get(source)?)
}

#[cfg(test)]
fn loop_bounds(state: &AppState) -> Option<LoopBounds> {
    loop_bounds_for_source(state, state.audition_source)
}

fn loop_bounds_meet_minimum(bounds: LoopBounds) -> bool {
    bounds.end_millis.saturating_sub(bounds.start_millis) >= MIN_LOOP_MILLIS
}

fn cleanup_any_error(state: &AppState) -> Option<&str> {
    match &state.paired_playback_guard {
        PairedPlaybackGuard::StoppingMain { root_error, .. }
        | PairedPlaybackGuard::StoppingReference { root_error, .. } => Some(root_error),
        _ => None,
    }
}

fn cleanup_any_active(state: &AppState) -> bool {
    cleanup_any_error(state).is_some()
}

fn cleanup_owns_main(state: &AppState) -> bool {
    matches!(
        state.paired_playback_guard,
        PairedPlaybackGuard::StoppingMain { .. }
    )
}

fn paired_playback_cleanup_error(state: &AppState) -> Option<&str> {
    cleanup_any_error(state)
}

fn paired_playback_cleanup_active(state: &AppState) -> bool {
    cleanup_any_active(state)
}

fn paired_playback_intended(state: &AppState) -> bool {
    matches!(
        state.paired_playback_guard,
        PairedPlaybackGuard::ReferenceRequired | PairedPlaybackGuard::Active
    )
}

fn arm_paired_playback_guard(state: &mut AppState) {
    if matches!(state.paired_playback_guard, PairedPlaybackGuard::Idle) {
        state.paired_playback_guard = PairedPlaybackGuard::ReferenceRequired;
    }
}

fn paired_playback_commands_admitted(state: &mut AppState) {
    if matches!(
        state.paired_playback_guard,
        PairedPlaybackGuard::ReferenceRequired
    ) {
        state.paired_playback_guard = PairedPlaybackGuard::Active;
    }
}

fn clear_paired_playback_guard(state: &mut AppState) {
    state.paired_playback_guard = PairedPlaybackGuard::Idle;
}

fn clear_uncommitted_paired_playback_guard(state: &mut AppState) {
    if matches!(
        state.paired_playback_guard,
        PairedPlaybackGuard::ReferenceRequired
    ) {
        clear_paired_playback_guard(state);
    }
}

fn invalidate_reference_transport_after_failure(state: &mut AppState) -> ReferenceUnloadState {
    if let Some(reference_transport) = state.reference_transport.as_ref() {
        reference_transport.set_output_gain(0.0);
    }
    state.reference_transport_generation = state.reference_transport_generation.wrapping_add(1);
    clear_live_spectrogram(state, AuditionSource::Reference);
    state.reference_transport_playing = false;
    state.reference_transport_polling = false;
    state.reference_transport_waiting_token = None;
    state.reference_transport_loaded = false;
    state.reference_only_playback = false;
    state.reference_playhead_drag_active = false;
    rollback_reference_persisted_note_drag(state);

    let Some(reference_transport) = state.reference_transport.as_ref() else {
        return ReferenceUnloadState::Complete;
    };
    match reference_transport.unload(state.reference_transport_generation) {
        Ok(token) => ReferenceUnloadState::AwaitingAcknowledgement(token),
        Err(_) => ReferenceUnloadState::PendingAdmission,
    }
}

fn cleanup_reference_transport_failure(state: &mut AppState, error: String) -> String {
    cleanup_transport_failure(state, error, None)
}

fn cleanup_transport_failure(
    state: &mut AppState,
    error: String,
    accepted_main_pause_token: Option<u64>,
) -> String {
    if let Some(root_error) = cleanup_any_error(state) {
        let root_error = root_error.to_owned();
        state.status = root_error.clone();
        return root_error;
    }

    let paired = paired_playback_intended(state);
    let reference_unload = invalidate_reference_transport_after_failure(state);
    if !paired {
        state.paired_playback_guard = PairedPlaybackGuard::StoppingReference {
            root_error: error.clone(),
            reference_unload,
            pending_reset_main: false,
            pending_reset_reference: false,
        };
        progress_paired_playback_cleanup_initial(state);
        state.status = error.clone();
        return error;
    }

    state.audition_auto_advance = false;
    state.audition_play_token = None;
    state.audition_pending_play_track_id = None;
    state.transport_playing = false;
    state.transport_polling = false;
    state.transport.set_output_gain(0.0);
    let (main_pause_token, main_pause_acknowledged) = if let Some(token) = accepted_main_pause_token
    {
        state.transport_waiting_token = Some(token);
        state.transport_polling = true;
        let snapshot = state.transport.snapshot();
        let acknowledged = snapshot.generation == state.transport_generation
            && transport_command_is_confirmed(snapshot, token);
        if acknowledged {
            state.transport_waiting_token = None;
            state.transport_polling = false;
            (None, true)
        } else {
            (Some(token), false)
        }
    } else {
        state.transport_waiting_token = None;
        (None, false)
    };
    state.paired_playback_guard = PairedPlaybackGuard::StoppingMain {
        root_error: error.clone(),
        main_pause_token,
        main_pause_acknowledged,
        reference_unload,
        pending_reset_main: false,
        pending_reset_reference: false,
    };
    progress_paired_playback_cleanup_initial(state);
    state.status = error.clone();
    error
}

fn progress_paired_playback_cleanup(state: &mut AppState) {
    progress_paired_playback_cleanup_with_reference_retry(state, true);
}

fn progress_paired_playback_cleanup_initial(state: &mut AppState) {
    progress_paired_playback_cleanup_with_reference_retry(state, false);
}

fn progress_paired_playback_cleanup_with_reference_retry(
    state: &mut AppState,
    retry_reference_admission: bool,
) {
    let guard = std::mem::replace(&mut state.paired_playback_guard, PairedPlaybackGuard::Idle);
    match guard {
        PairedPlaybackGuard::StoppingMain {
            root_error,
            mut main_pause_token,
            mut main_pause_acknowledged,
            mut reference_unload,
            pending_reset_main,
            pending_reset_reference,
        } => {
            if !main_pause_acknowledged {
                if let Some(token) = main_pause_token {
                    let snapshot = state.transport.snapshot();
                    if snapshot.generation == state.transport_generation
                        && transport_command_is_confirmed(snapshot, token)
                    {
                        main_pause_token = None;
                        main_pause_acknowledged = true;
                        state.transport_playing = false;
                        state.transport_polling = false;
                        state.transport_waiting_token = None;
                    }
                }
                if !main_pause_acknowledged
                    && main_pause_token.is_none()
                    && let Ok(token) = state.transport.pause(state.transport_generation)
                {
                    main_pause_token = Some(token);
                    begin_transport_polling(state, token);
                }
            }

            reference_unload =
                progress_reference_unload(state, reference_unload, retry_reference_admission);
            if main_pause_acknowledged {
                state.transport.set_output_gain(main_output_gain(state));
            }

            if main_pause_acknowledged && matches!(reference_unload, ReferenceUnloadState::Complete)
            {
                state.paired_playback_guard = PairedPlaybackGuard::Idle;
                if pending_reset_main {
                    reset_transport(state);
                }
                if pending_reset_reference {
                    reset_reference_transport(state);
                }
                sync_audition_output_gains(state);
            } else {
                state.paired_playback_guard = PairedPlaybackGuard::StoppingMain {
                    root_error: root_error.clone(),
                    main_pause_token,
                    main_pause_acknowledged,
                    reference_unload,
                    pending_reset_main,
                    pending_reset_reference,
                };
            }
            state.status = root_error;
        }
        PairedPlaybackGuard::StoppingReference {
            root_error,
            reference_unload,
            pending_reset_main,
            pending_reset_reference,
        } => {
            let reference_unload =
                progress_reference_unload(state, reference_unload, retry_reference_admission);
            if matches!(reference_unload, ReferenceUnloadState::Complete) {
                state.paired_playback_guard = PairedPlaybackGuard::Idle;
                if pending_reset_main {
                    reset_transport(state);
                }
                if pending_reset_reference {
                    reset_reference_transport(state);
                }
                restore_reference_output_gain(state);
            } else {
                state.paired_playback_guard = PairedPlaybackGuard::StoppingReference {
                    root_error: root_error.clone(),
                    reference_unload,
                    pending_reset_main,
                    pending_reset_reference,
                };
            }
            state.status = root_error;
        }
        guard => state.paired_playback_guard = guard,
    }
}

fn progress_reference_unload(
    state: &AppState,
    unload: ReferenceUnloadState,
    retry_admission: bool,
) -> ReferenceUnloadState {
    let Some(reference_transport) = state.reference_transport.as_ref() else {
        return ReferenceUnloadState::Complete;
    };
    match unload {
        ReferenceUnloadState::Complete => ReferenceUnloadState::Complete,
        ReferenceUnloadState::PendingAdmission => {
            if !retry_admission {
                return ReferenceUnloadState::PendingAdmission;
            }
            match reference_transport.unload(state.reference_transport_generation) {
                Ok(token) => ReferenceUnloadState::AwaitingAcknowledgement(token),
                Err(_) => ReferenceUnloadState::PendingAdmission,
            }
        }
        ReferenceUnloadState::AwaitingAcknowledgement(token) => {
            let snapshot = reference_transport.snapshot();
            if snapshot.generation == state.reference_transport_generation
                && transport_command_is_confirmed(snapshot, token)
            {
                ReferenceUnloadState::Complete
            } else {
                ReferenceUnloadState::AwaitingAcknowledgement(token)
            }
        }
    }
}

fn restore_reference_output_gain(state: &AppState) {
    if let Some(reference_transport) = state.reference_transport.as_ref() {
        reference_transport.set_output_gain(reference_output_gain(state));
    }
}

fn maybe_clear_paired_playback_guard_after_idle(state: &mut AppState) {
    if !matches!(
        state.paired_playback_guard,
        PairedPlaybackGuard::ReferenceRequired | PairedPlaybackGuard::Active
    ) {
        return;
    }
    let reference_pending = state
        .reference_transport
        .as_ref()
        .is_some_and(transport::AudioTransport::has_pending_load);
    if !source_transport_is_active(state, AuditionSource::Main)
        && !source_transport_is_active(state, AuditionSource::Reference)
        && !state.transport.has_pending_load()
        && !reference_pending
    {
        clear_paired_playback_guard(state);
    }
}

fn seek_synchronized_positions(
    state: &mut AppState,
    main_position_millis: u64,
    reference_position_millis: u64,
    resume: bool,
) -> Result<(), String> {
    if let Some(error) = paired_playback_cleanup_error(state) {
        return Err(error.to_owned());
    }
    if state.waveform_busy
        || (state.reference_waveform_busy && !reference_source_is_mismatched(state))
    {
        return Err(String::from("Audio analysis is still building."));
    }
    let Some(main_duration_millis) = state
        .waveform
        .as_ref()
        .filter(|_| {
            state.library.selected_track_id.as_deref() == state.waveform_track_id.as_deref()
        })
        .map(|waveform| waveform.duration_millis)
    else {
        return Err(String::from("Audio analysis is still pending."));
    };
    let reference_details = selected_reference_details(state);
    let reference_ticket = reference_details
        .as_ref()
        .and_then(|(path, _)| reference_source_ticket_for_path(state, path));
    if reference_details.is_some() && reference_ticket.is_none() {
        return Err(String::from(
            "Reference source verification is still pending.",
        ));
    }
    if !state.transport.has_command_capacity(1) {
        return Err(String::from(transport::CONTROLS_BUSY_ERROR));
    }
    let reference_was_loaded = state.reference_transport_loaded;
    if reference_details.is_some() {
        if !reference_was_loaded {
            state
                .reference_transport
                .get_or_insert_with(transport::AudioTransport::spawn);
        }
        let reference_transport = state
            .reference_transport
            .get_or_insert_with(transport::AudioTransport::spawn);
        if reference_transport.has_pending_load() {
            return Err(String::from(transport::CONTROLS_BUSY_ERROR));
        }
        let required_slots = if reference_was_loaded { 1 } else { 2 };
        if !reference_transport.has_command_capacity(required_slots) {
            return Err(String::from(transport::CONTROLS_BUSY_ERROR));
        }
        arm_paired_playback_guard(state);
        if !reference_was_loaded {
            clear_live_spectrogram(state, AuditionSource::Reference);
        }
    }
    let main_token = match state.transport.seek(
        state.transport_generation,
        main_position_millis,
        main_duration_millis,
        resume,
    ) {
        Ok(token) => token,
        Err(error) => {
            return Err(if reference_details.is_some() {
                cleanup_reference_transport_failure(state, error)
            } else {
                clear_uncommitted_paired_playback_guard(state);
                error
            });
        }
    };
    clear_pending_seek_intent_if_admitted(state, AuditionSource::Main, main_position_millis);
    begin_transport_polling(state, main_token);
    if let Some((_reference_path, reference_duration_millis)) = reference_details {
        let reference_gain = reference_output_gain(state);
        let reference_transport = state
            .reference_transport
            .get_or_insert_with(transport::AudioTransport::spawn);
        reference_transport.set_output_gain(reference_gain);
        if !reference_was_loaded {
            match reference_transport.load(
                state.reference_transport_generation,
                reference_ticket.expect("reference details require a verified source ticket"),
                reference_duration_millis,
            ) {
                Ok(_) => {}
                Err(error) => {
                    return Err(cleanup_reference_transport_failure(state, error));
                }
            }
            if reference_transport.has_pending_load() {
                return Err(cleanup_reference_transport_failure(
                    state,
                    String::from(transport::CONTROLS_BUSY_ERROR),
                ));
            }
            state.reference_transport_loaded = true;
        }
        let reference_token = match reference_transport.seek(
            state.reference_transport_generation,
            reference_position_millis,
            reference_duration_millis,
            resume,
        ) {
            Ok(token) => token,
            Err(error) => return Err(cleanup_reference_transport_failure(state, error)),
        };
        clear_pending_seek_intent_if_admitted(
            state,
            AuditionSource::Reference,
            reference_position_millis,
        );
        state.reference_transport_waiting_token = Some(reference_token);
        state.reference_transport_polling = true;
        paired_playback_commands_admitted(state);
    }
    state.reference_only_playback = false;
    state.transport_position_millis = main_position_millis;
    state.review_cursor_millis = main_position_millis;
    state.reference_transport_position_millis = reference_position_millis;
    Ok(())
}

fn resume_main_at_position_with_reference(
    state: &mut AppState,
    main_position_millis: u64,
) -> Result<(), String> {
    let reference_position_millis = selected_reference_details(state)
        .map(|(_, duration_millis)| {
            state
                .reference_transport_position_millis
                .min(duration_millis)
        })
        .unwrap_or(state.reference_transport_position_millis);
    seek_synchronized_positions(state, main_position_millis, reference_position_millis, true)
}

fn seek_reference_waveform_position(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    ratio: f32,
    resume: bool,
) {
    if !library_is_ready(state) {
        return;
    }
    if reject_main_source_mismatch(state, context)
        || reject_reference_source_mismatch(state, context)
    {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy || state.waveform_busy || state.reference_waveform_busy {
        return;
    }
    let Some((path, reference_duration_millis)) = selected_reference_details(state) else {
        return;
    };
    let Some(reference_ticket) = reference_source_ticket_for_path(state, &path) else {
        state.status = String::from("Reference source verification is still pending.");
        context.request_repaint();
        return;
    };
    state.loop_selections.clear(AuditionSource::Reference);
    disarm_audition_auto_advance(state);
    set_audition_source(state, AuditionSource::Reference);
    if let Some(reference_transport) = state.reference_transport.as_ref()
        && !state.reference_transport_loaded
        && reference_transport.has_pending_load()
    {
        state.status = String::from(transport::CONTROLS_BUSY_ERROR);
        context.request_repaint();
        return;
    }
    let ratio = waveform::clamp_ratio(ratio);
    let reference_position_millis = waveform::millis_for_ratio(ratio, reference_duration_millis);
    set_pending_seek_intent(state, AuditionSource::Reference, reference_position_millis);
    state.draft_note = None;
    rollback_persisted_note_drag(state);
    state.selected_note_id = None;
    if !resume {
        state.reference_transport_position_millis = reference_position_millis;
        state.reference_only_playback = false;
        state.status = format!(
            "Scrubbing reference at {}.",
            format_timestamp(reference_position_millis)
        );
        context.request_repaint();
        return;
    }
    let reference_gain = reference_output_gain(state);
    if !state.reference_transport_loaded {
        clear_live_spectrogram(state, AuditionSource::Reference);
    }
    let reference_transport = state
        .reference_transport
        .get_or_insert_with(transport::AudioTransport::spawn);
    reference_transport.set_output_gain(reference_gain);
    if !state.reference_transport_loaded {
        if let Err(error) = reference_transport.load(
            state.reference_transport_generation,
            reference_ticket,
            reference_duration_millis,
        ) {
            cleanup_reference_transport_failure(state, error);
            context.request_repaint();
            return;
        }
        if reference_transport.has_pending_load() {
            cleanup_reference_transport_failure(
                state,
                String::from(transport::CONTROLS_BUSY_ERROR),
            );
            context.request_repaint();
            return;
        }
        state.reference_transport_loaded = true;
    }
    match reference_transport.seek(
        state.reference_transport_generation,
        reference_position_millis,
        reference_duration_millis,
        true,
    ) {
        Ok(token) => {
            clear_pending_seek_intent_if_admitted(
                state,
                AuditionSource::Reference,
                reference_position_millis,
            );
            state.reference_transport_position_millis = reference_position_millis;
            state.reference_transport_waiting_token = Some(token);
            state.reference_transport_polling = true;
            state.reference_only_playback = true;
            state.status = format!(
                "Playing reference from {}.",
                format_timestamp(reference_position_millis)
            );
        }
        Err(error) => {
            cleanup_reference_transport_failure(state, error);
        }
    }
    context.request_repaint();
}

fn source_transport_is_active(state: &AppState, source: AuditionSource) -> bool {
    match source {
        AuditionSource::Main => {
            state.transport_playing
                || state.transport_polling
                || state.transport_waiting_token.is_some()
        }
        AuditionSource::Reference => {
            state.reference_transport_playing
                || state.reference_transport_polling
                || state.reference_transport_waiting_token.is_some()
        }
    }
}

fn set_source_position(state: &mut AppState, source: AuditionSource, position_millis: u64) {
    match source {
        AuditionSource::Main => {
            state.transport_position_millis = position_millis;
            state.review_cursor_millis = position_millis;
        }
        AuditionSource::Reference => {
            state.reference_transport_position_millis = position_millis;
        }
    }
}

fn seek_loop_owner(
    state: &mut AppState,
    source: AuditionSource,
    bounds: LoopBounds,
) -> Result<(), String> {
    if let Some(error) = paired_playback_cleanup_error(state) {
        return Err(error.to_owned());
    }
    let duration_millis = selected_duration_for_source(state, source)
        .ok_or_else(|| String::from("Audio analysis is still pending."))?;
    let position_millis = bounds.start_millis.min(duration_millis);
    match source {
        AuditionSource::Main => {
            if state.transport_polling
                || state.transport_waiting_token.is_some()
                || state.transport.has_pending_load()
                || !state.transport.has_command_capacity(1)
            {
                return Err(String::from(transport::CONTROLS_BUSY_ERROR));
            }
            let token = match state.transport.seek(
                state.transport_generation,
                position_millis,
                duration_millis,
                true,
            ) {
                Ok(token) => token,
                Err(error) if paired_playback_intended(state) => {
                    return Err(cleanup_transport_failure(state, error, None));
                }
                Err(error) => return Err(error),
            };
            clear_pending_seek_intent(state, AuditionSource::Main);
            set_source_position(state, source, position_millis);
            begin_transport_polling(state, token);
        }
        AuditionSource::Reference => {
            let Some(reference_transport) = state.reference_transport.as_ref() else {
                return Err(String::from(transport::CONTROLS_BUSY_ERROR));
            };
            if !state.reference_transport_loaded
                || state.reference_transport_polling
                || state.reference_transport_waiting_token.is_some()
                || reference_transport.has_pending_load()
                || !reference_transport.has_command_capacity(1)
            {
                return Err(String::from(transport::CONTROLS_BUSY_ERROR));
            }
            let seek_result = reference_transport.seek(
                state.reference_transport_generation,
                position_millis,
                duration_millis,
                true,
            );
            let token = match seek_result {
                Ok(token) => token,
                Err(error) => return Err(cleanup_reference_transport_failure(state, error)),
            };
            clear_pending_seek_intent(state, AuditionSource::Reference);
            set_source_position(state, source, position_millis);
            state.reference_transport_waiting_token = Some(token);
            state.reference_transport_polling = true;
        }
    }
    Ok(())
}

fn finish_loop_selection(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    owner: AuditionSource,
    start_ratio: f32,
    end_ratio: f32,
) {
    if !library_is_ready(state) {
        return;
    }
    if (owner == AuditionSource::Main && reject_main_source_mismatch(state, context))
        || (owner == AuditionSource::Reference
            && (reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)))
    {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy
        || state.waveform_busy
        || (owner == AuditionSource::Reference && state.reference_waveform_busy)
    {
        return;
    }
    if owner == AuditionSource::Reference && selected_reference_details(state).is_none() {
        return;
    }
    disarm_audition_auto_advance(state);
    set_audition_source(state, owner);
    let start_ratio = waveform::clamp_ratio(start_ratio);
    let end_ratio = waveform::clamp_ratio(end_ratio);
    let (start_ratio, end_ratio) = if start_ratio <= end_ratio {
        (start_ratio, end_ratio)
    } else {
        (end_ratio, start_ratio)
    };
    let candidate_selection = LoopSelection {
        start_ratio,
        end_ratio,
    };
    let Some(bounds) = loop_bounds_for_selection(state, owner, candidate_selection) else {
        state.loop_selections.clear(owner);
        state.status = String::from("Loop cleared.");
        context.request_repaint();
        return;
    };
    if !loop_bounds_meet_minimum(bounds) {
        state.loop_selections.clear(owner);
        state.status = String::from("Loop cleared — select at least 120 ms.");
        context.request_repaint();
        return;
    }

    let owner_was_active = source_transport_is_active(state, owner);
    if owner_was_active && let Err(error) = seek_loop_owner(state, owner, bounds) {
        state.status = error;
        context.request_repaint();
        return;
    }
    state.loop_selections.set(owner, Some(candidate_selection));
    if !owner_was_active {
        set_source_position(state, owner, bounds.start_millis);
    }
    let label = match owner {
        AuditionSource::Main => "Main",
        AuditionSource::Reference => "Reference",
    };
    state.status = format!(
        "{label} loop {}–{}.",
        format_timestamp(bounds.start_millis),
        format_timestamp(bounds.end_millis),
    );
    context.request_repaint();
}

fn select_audition_source(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    source: AuditionSource,
) {
    if !library_is_ready(state) {
        return;
    }
    if (source == AuditionSource::Main && reject_main_source_mismatch(state, context))
        || (source == AuditionSource::Reference
            && (reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)))
    {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy {
        return;
    }
    if source == AuditionSource::Reference {
        if state.reference_waveform_busy {
            state.status = String::from("Reference analysis is still pending.");
            context.request_repaint();
            return;
        }
        if selected_reference_details(state).is_none() {
            state.status = String::from("Import and analyze a reference track first.");
            context.request_repaint();
            return;
        }
    }
    if state.audition_source != source {
        set_audition_source(state, source);
        state.status = match source {
            AuditionSource::Main => String::from("Now hearing the imported track."),
            AuditionSource::Reference => String::from("Now hearing the reference track."),
        };
    }
    context.request_repaint();
}

fn activate_audition_source(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    source: AuditionSource,
) {
    if (source == AuditionSource::Main && reject_main_source_mismatch(state, context))
        || (source == AuditionSource::Reference
            && (reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)))
    {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy {
        return;
    }
    if source == AuditionSource::Reference {
        if state.reference_waveform_busy {
            state.status = String::from("Reference analysis is still pending.");
            context.request_repaint();
            return;
        }
        if selected_reference_details(state).is_none() {
            state.status = String::from("Import and analyze a reference track first.");
            context.request_repaint();
            return;
        }
    }

    let source_active = source_transport_is_active(state, source);
    let playback_active = source_active
        || source_transport_is_active(
            state,
            match source {
                AuditionSource::Main => AuditionSource::Reference,
                AuditionSource::Reference => AuditionSource::Main,
            },
        );
    if !playback_active {
        select_audition_source(state, context, source);
        toggle_playback(state, context);
    } else if source_active {
        if state.audition_source == source {
            stop_playback(state, context);
        } else {
            select_audition_source(state, context, source);
        }
    } else {
        if let Err(error) = start_source_alongside_active(state, source) {
            state.status = error;
            context.request_repaint();
            return;
        }
        state.reference_only_playback = false;
        select_audition_source(state, context, source);
    }
}

fn start_source_alongside_active(
    state: &mut AppState,
    source: AuditionSource,
) -> Result<(), String> {
    if let Some(error) = paired_playback_cleanup_error(state) {
        return Err(error.to_owned());
    }
    match source {
        AuditionSource::Main => {
            let duration_millis = selected_main_duration(state)
                .ok_or_else(|| String::from("Audio analysis is still pending."))?;
            if !state.transport.has_command_capacity(1) {
                return Err(String::from(transport::CONTROLS_BUSY_ERROR));
            }
            arm_paired_playback_guard(state);
            let loop_bounds = loop_bounds_for_source(state, AuditionSource::Main);
            let pending_intent_millis = pending_seek_intent(state, AuditionSource::Main);
            let position_millis =
                playback_start_position(state, AuditionSource::Main, duration_millis, loop_bounds);
            let starts_new_segment = matches!(
                resume_transport_command(state, AuditionSource::Main, position_millis, loop_bounds,),
                ResumeTransportCommand::Seek
            );
            state.transport.set_output_gain(state.audition_volume);
            let result = if starts_new_segment {
                state.transport.seek(
                    state.transport_generation,
                    position_millis,
                    duration_millis,
                    true,
                )
            } else {
                state.transport.play(state.transport_generation)
            };
            match result {
                Ok(token) => {
                    if starts_new_segment && let Some(intent_millis) = pending_intent_millis {
                        clear_pending_seek_intent_if_admitted(
                            state,
                            AuditionSource::Main,
                            intent_millis,
                        );
                    }
                    set_source_position(state, AuditionSource::Main, position_millis);
                    begin_transport_polling(state, token);
                    paired_playback_commands_admitted(state);
                    Ok(())
                }
                Err(error) => {
                    sync_audition_output_gains(state);
                    Err(if paired_playback_intended(state) {
                        cleanup_transport_failure(state, error, None)
                    } else {
                        error
                    })
                }
            }
        }
        AuditionSource::Reference => {
            let (path, duration_millis) = selected_reference_details(state)
                .ok_or_else(|| String::from("Import and analyze a reference track first."))?;
            let reference_ticket = reference_source_ticket_for_path(state, &path)
                .ok_or_else(|| String::from("Reference source verification is still pending."))?;
            let reference_was_loaded = state.reference_transport_loaded;
            let pending_intent_millis = pending_seek_intent(state, AuditionSource::Reference);
            let reference_uses_resume_seek = pending_intent_millis.is_some();
            let required_slots = if reference_was_loaded {
                if reference_uses_resume_seek { 1 } else { 2 }
            } else if reference_uses_resume_seek {
                2
            } else {
                3
            };
            let loop_bounds = loop_bounds_for_source(state, AuditionSource::Reference);
            let position_millis = playback_start_position(
                state,
                AuditionSource::Reference,
                duration_millis,
                loop_bounds,
            );
            let reference_gain = reference_output_gain_for_source(state, AuditionSource::Reference);
            let reference_transport = state
                .reference_transport
                .get_or_insert_with(transport::AudioTransport::spawn);
            if reference_transport.has_pending_load() {
                return Err(String::from(transport::CONTROLS_BUSY_ERROR));
            }
            if !reference_transport.has_command_capacity(required_slots) {
                return Err(String::from(transport::CONTROLS_BUSY_ERROR));
            }
            let reference_transport = reference_transport.clone();
            arm_paired_playback_guard(state);
            if !reference_was_loaded {
                clear_live_spectrogram(state, AuditionSource::Reference);
            }
            let mut loaded = reference_was_loaded;
            let result = {
                reference_transport.set_output_gain(reference_gain);
                let load_result = if !loaded {
                    match reference_transport.load(
                        state.reference_transport_generation,
                        reference_ticket,
                        duration_millis,
                    ) {
                        Ok(_) if !reference_transport.has_pending_load() => {
                            loaded = true;
                            Ok(())
                        }
                        Ok(_) => Err(String::from(transport::CONTROLS_BUSY_ERROR)),
                        Err(error) => Err(error),
                    }
                } else {
                    Ok(())
                };
                load_result.and_then(|()| {
                    let seek_result = reference_transport.seek(
                        state.reference_transport_generation,
                        position_millis,
                        duration_millis,
                        reference_uses_resume_seek,
                    );
                    if seek_result.is_ok()
                        && let Some(intent_millis) = pending_intent_millis
                    {
                        clear_pending_seek_intent_if_admitted(
                            state,
                            AuditionSource::Reference,
                            intent_millis,
                        );
                    }
                    seek_result.and_then(|token| {
                        if reference_uses_resume_seek {
                            Ok(token)
                        } else {
                            reference_transport.play(state.reference_transport_generation)
                        }
                    })
                })
            };
            if loaded {
                state.reference_transport_loaded = true;
            }
            match result {
                Ok(token) => {
                    set_source_position(state, AuditionSource::Reference, position_millis);
                    state.reference_transport_waiting_token = Some(token);
                    state.reference_transport_polling = true;
                    paired_playback_commands_admitted(state);
                    Ok(())
                }
                Err(error) => {
                    sync_audition_output_gains(state);
                    Err(cleanup_reference_transport_failure(state, error))
                }
            }
        }
    }
}

fn set_audition_source(state: &mut AppState, source: AuditionSource) {
    if state.audition_source == source {
        return;
    }
    state.audition_source = source;
    sync_audition_output_gains(state);
    reset_live_spectrogram_segment(state, source);
}

fn play_audition(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) {
        return;
    }
    if reject_main_source_mismatch(state, context) {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy || state.workspace_mode != WorkspaceMode::Audition {
        return;
    }
    let reference_playback_available = !reference_source_is_mismatched(state);
    if state.transport_playing
        || (state.reference_transport_playing && reference_playback_available)
    {
        state.status = String::from("Audition playback is already active.");
        context.request_repaint();
        return;
    }
    let Some(track_id) = state.library.selected_track_id.clone() else {
        state.status = String::from("Select an audition track before playing.");
        context.request_repaint();
        return;
    };
    if !state
        .audition_queue
        .iter()
        .any(|queued_id| queued_id == &track_id)
    {
        state.status = String::from("Select an audition track before playing.");
        context.request_repaint();
        return;
    }

    let waveform_ready = !state.waveform_busy
        && state.waveform_track_id.as_deref() == Some(track_id.as_str())
        && state.waveform.is_some();
    let transport_pending = state.transport_polling
        || state.transport_waiting_token.is_some()
        || state.transport.has_pending_load()
        || (reference_playback_available
            && (state.reference_transport_polling
                || state.reference_transport_waiting_token.is_some()
                || state
                    .reference_transport
                    .as_ref()
                    .is_some_and(transport::AudioTransport::has_pending_load)));
    if !waveform_ready
        || (state.reference_waveform_busy && reference_playback_available)
        || transport_pending
    {
        state.audition_auto_advance = true;
        state.audition_play_token = None;
        state.audition_pending_play_track_id = Some(track_id.clone());
        let title = state
            .library
            .tracks
            .iter()
            .find(|track| track.id == track_id)
            .map_or(track_id, |track| track.title.clone());
        state.status = format!("Loading audition track: {title}…");
        context.request_repaint();
        return;
    }

    // The existing toggle path owns paired main/reference admission. Calling it
    // only after the active-playback guard makes this a one-way Play command.
    state.audition_pending_play_track_id = None;
    toggle_playback(state, context);
}

fn source_position(state: &AppState, source: AuditionSource) -> u64 {
    match source {
        AuditionSource::Main => state.transport_position_millis,
        AuditionSource::Reference => state.reference_transport_position_millis,
    }
}

fn pending_seek_intent(state: &AppState, source: AuditionSource) -> Option<u64> {
    match source {
        AuditionSource::Main => state.pending_main_seek_intent,
        AuditionSource::Reference => state.pending_reference_seek_intent,
    }
}

fn set_pending_seek_intent(state: &mut AppState, source: AuditionSource, position_millis: u64) {
    cancel_pending_comment_playback(state);
    match source {
        AuditionSource::Main => state.pending_main_seek_intent = Some(position_millis),
        AuditionSource::Reference => state.pending_reference_seek_intent = Some(position_millis),
    }
}

fn clear_pending_seek_intent(state: &mut AppState, source: AuditionSource) {
    match source {
        AuditionSource::Main => state.pending_main_seek_intent = None,
        AuditionSource::Reference => state.pending_reference_seek_intent = None,
    }
}

fn clear_pending_seek_intent_if_admitted(
    state: &mut AppState,
    source: AuditionSource,
    admitted_intent_millis: u64,
) {
    // Compare the admitted intent identity, not the transport's normalized position.
    if pending_seek_intent(state, source) == Some(admitted_intent_millis) {
        clear_pending_seek_intent(state, source);
    }
}

fn normalize_position_for_duration(position_millis: u64, duration_millis: u64) -> u64 {
    if position_millis >= duration_millis {
        0
    } else {
        position_millis
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ResumeTransportCommand {
    Play,
    Seek,
}

fn resume_transport_command(
    state: &AppState,
    source: AuditionSource,
    position_millis: u64,
    loop_bounds: Option<LoopBounds>,
) -> ResumeTransportCommand {
    if pending_seek_intent(state, source).is_some()
        || loop_bounds.is_some()
        || position_millis != source_position(state, source)
    {
        ResumeTransportCommand::Seek
    } else {
        ResumeTransportCommand::Play
    }
}

fn playback_start_position(
    state: &AppState,
    source: AuditionSource,
    duration_millis: u64,
    loop_bounds: Option<LoopBounds>,
) -> u64 {
    if let Some(intent_millis) = pending_seek_intent(state, source) {
        return normalize_position_for_duration(intent_millis, duration_millis);
    }
    let stored_position_millis = source_position(state, source);
    if let Some(bounds) = loop_bounds {
        if stored_position_millis >= bounds.start_millis
            && stored_position_millis < bounds.end_millis
        {
            stored_position_millis.min(duration_millis)
        } else {
            bounds.start_millis.min(duration_millis)
        }
    } else {
        normalize_position_for_duration(stored_position_millis, duration_millis)
    }
}

fn previous_audition(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    move_audition(state, context, AuditionMove::Previous);
}

fn next_audition(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    move_audition(state, context, AuditionMove::Next);
}

#[derive(Clone, Copy)]
enum AuditionMove {
    Previous,
    Next,
}

fn move_audition(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    direction: AuditionMove,
) {
    if !library_is_ready(state) {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy || state.workspace_mode != WorkspaceMode::Audition {
        return;
    }
    let Some(current_id) = state.library.selected_track_id.clone() else {
        state.status = match direction {
            AuditionMove::Previous => {
                String::from("Already at the beginning of the audition queue.")
            }
            AuditionMove::Next => String::from("Already at the end of the audition queue."),
        };
        context.request_repaint();
        return;
    };
    let Some(current_index) = state
        .audition_queue
        .iter()
        .position(|track_id| track_id == &current_id)
    else {
        state.status = match direction {
            AuditionMove::Previous => {
                String::from("Already at the beginning of the audition queue.")
            }
            AuditionMove::Next => String::from("Already at the end of the audition queue."),
        };
        context.request_repaint();
        return;
    };
    let destination_index = match direction {
        AuditionMove::Previous => current_index.checked_sub(1),
        AuditionMove::Next => current_index
            .checked_add(1)
            .filter(|index| *index < state.audition_queue.len()),
    };
    let Some(destination_index) = destination_index else {
        state.status = match direction {
            AuditionMove::Previous => {
                String::from("Already at the beginning of the audition queue.")
            }
            AuditionMove::Next => String::from("Already at the end of the audition queue."),
        };
        context.request_repaint();
        return;
    };
    let Some(destination_id) = state.audition_queue.get(destination_index).cloned() else {
        return;
    };

    if matches!(direction, AuditionMove::Next)
        && !state
            .audition_heard
            .iter()
            .any(|heard_id| heard_id == &current_id)
    {
        state.audition_heard.push(current_id);
    }
    state
        .audition_heard
        .retain(|heard_id| heard_id != &destination_id);
    let title = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == destination_id)
        .map_or_else(|| destination_id.clone(), |track| track.title.clone());
    select_track_internal(state, context, destination_id, true);
    state.status = match direction {
        AuditionMove::Previous => format!("Loading previous audition track: {title}…"),
        AuditionMove::Next => format!("Loading next audition track: {title}…"),
    };
    context.request_repaint();
}

fn admit_pause_for_active_transports(state: &mut AppState) -> Result<bool, String> {
    let main_active =
        !state.reference_only_playback && source_transport_is_active(state, AuditionSource::Main);
    let reference_active = source_transport_is_active(state, AuditionSource::Reference);
    if !main_active && !reference_active {
        return Ok(false);
    }

    let paired = paired_playback_intended(state)
        || (!state.reference_only_playback && main_active && reference_active);
    if main_active && !state.transport.has_command_capacity(1) {
        return Err(String::from(transport::CONTROLS_BUSY_ERROR));
    }
    if reference_active {
        let Some(reference_transport) = state.reference_transport.as_ref() else {
            return Err(String::from(transport::CONTROLS_BUSY_ERROR));
        };
        if reference_transport.has_pending_load() || !reference_transport.has_command_capacity(1) {
            return Err(String::from(transport::CONTROLS_BUSY_ERROR));
        }
    }
    if paired && !paired_playback_intended(state) {
        arm_paired_playback_guard(state);
    }

    let main_token = if main_active {
        match state.transport.pause(state.transport_generation) {
            Ok(token) => Some(token),
            Err(error) if paired => {
                return Err(cleanup_transport_failure(state, error, None));
            }
            Err(error) => return Err(error),
        }
    } else {
        None
    };

    let reference_token = if reference_active {
        let Some(reference_transport) = state.reference_transport.as_ref() else {
            return Err(if paired {
                cleanup_transport_failure(
                    state,
                    String::from(transport::CONTROLS_BUSY_ERROR),
                    main_token,
                )
            } else {
                String::from(transport::CONTROLS_BUSY_ERROR)
            });
        };
        match reference_transport.pause(state.reference_transport_generation) {
            Ok(token) => Some(token),
            Err(error) if paired => {
                return Err(cleanup_transport_failure(state, error, main_token));
            }
            Err(error) => {
                return Err(cleanup_reference_transport_failure(state, error));
            }
        }
    } else {
        None
    };

    if let Some(token) = main_token {
        begin_transport_polling(state, token);
    }
    if let Some(token) = reference_token {
        state.reference_transport_waiting_token = Some(token);
        state.reference_transport_polling = true;
    }
    state.reference_only_playback = false;
    Ok(true)
}

fn stop_playback(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    state.audition_auto_advance = false;
    state.audition_play_token = None;
    state.audition_pending_play_track_id = None;
    cancel_pending_comment_playback(state);
    match admit_pause_for_active_transports(state) {
        Ok(true) => state.status = String::from("Stopping playback…"),
        Ok(false) => {
            clear_paired_playback_guard(state);
            return;
        }
        Err(error) => state.status = error,
    }
    context.request_repaint();
}

fn toggle_playback(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) {
        return;
    }
    if reject_main_source_mismatch(state, context) {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    let reference_playback_available = !reference_source_is_mismatched(state);
    if state.busy
        || state.waveform_busy
        || (state.reference_waveform_busy && reference_playback_available)
    {
        if state.waveform_busy || (state.reference_waveform_busy && reference_playback_available) {
            state.status = String::from("Audio analysis is still building.");
            context.request_repaint();
        }
        return;
    }
    if state.transport_polling
        || (state.reference_transport_polling && reference_playback_available)
    {
        return;
    }
    let Some(waveform) = state
        .waveform
        .as_ref()
        .filter(|_| selected_track(state).is_some())
    else {
        state.status = String::from("Audio analysis is still pending.");
        context.request_repaint();
        return;
    };

    let reference_details = selected_reference_details(state);
    let reference_ticket = reference_details
        .as_ref()
        .and_then(|(path, _)| reference_source_ticket_for_path(state, path));
    if reference_details.is_some() && reference_ticket.is_none() {
        state.status = String::from("Reference source verification is still pending.");
        context.request_repaint();
        return;
    }
    if reference_playback_available
        && let Some(reference_transport) = state.reference_transport.as_ref()
        && !state.reference_transport_loaded
        && reference_transport.has_pending_load()
    {
        state.status = String::from(transport::CONTROLS_BUSY_ERROR);
        context.request_repaint();
        return;
    }
    let reference_pending = selected_track(state)
        .and_then(|track| track.reference_path.as_ref())
        .is_some()
        && reference_playback_available
        && state.reference_waveform_busy;
    if !state.transport_playing
        && !(state.reference_transport_playing && reference_playback_available)
        && reference_pending
    {
        state.status = String::from("Reference analysis is still pending.");
        context.request_repaint();
        return;
    }

    if state.transport_playing
        || (state.reference_transport_playing && reference_playback_available)
    {
        if state.workspace_mode == WorkspaceMode::Audition {
            state.audition_auto_advance = false;
            state.audition_play_token = None;
        }
        match admit_pause_for_active_transports(state) {
            Ok(true) => state.status = String::from("Pausing playback…"),
            Ok(false) => {
                clear_paired_playback_guard(state);
                return;
            }
            Err(error) => state.status = error,
        }
    } else {
        let duration_millis = waveform.duration_millis;
        let main_loop_bounds = loop_bounds_for_source(state, AuditionSource::Main);
        let reference_loop_bounds = loop_bounds_for_source(state, AuditionSource::Reference);
        let pending_main_intent_millis = pending_seek_intent(state, AuditionSource::Main);
        let pending_reference_intent_millis = pending_seek_intent(state, AuditionSource::Reference);
        let main_position_millis = playback_start_position(
            state,
            AuditionSource::Main,
            duration_millis,
            main_loop_bounds,
        );
        let reference_position_millis = reference_details
            .as_ref()
            .map(|(_, duration_millis)| {
                playback_start_position(
                    state,
                    AuditionSource::Reference,
                    *duration_millis,
                    reference_loop_bounds,
                )
            })
            .unwrap_or(state.reference_transport_position_millis);
        if !state.transport.has_command_capacity(1) {
            state.status = String::from(transport::CONTROLS_BUSY_ERROR);
            context.request_repaint();
            return;
        }
        if reference_details.is_some() {
            let reference_uses_resume_seek = pending_reference_intent_millis.is_some();
            let reference_transport = state
                .reference_transport
                .get_or_insert_with(transport::AudioTransport::spawn);
            if reference_transport.has_pending_load() {
                state.status = String::from(transport::CONTROLS_BUSY_ERROR);
                context.request_repaint();
                return;
            }
            let required_reference_slots = if state.reference_transport_loaded {
                if reference_uses_resume_seek { 1 } else { 2 }
            } else {
                if reference_uses_resume_seek { 2 } else { 3 }
            };
            if !reference_transport.has_command_capacity(required_reference_slots) {
                state.status = String::from(transport::CONTROLS_BUSY_ERROR);
                context.request_repaint();
                return;
            }
            arm_paired_playback_guard(state);
        }
        state.reference_only_playback = false;

        let main_starts_new_segment = matches!(
            resume_transport_command(
                state,
                AuditionSource::Main,
                main_position_millis,
                main_loop_bounds,
            ),
            ResumeTransportCommand::Seek
        );
        let reference_starts_new_segment = !state.reference_transport_loaded
            || matches!(
                resume_transport_command(
                    state,
                    AuditionSource::Reference,
                    reference_position_millis,
                    reference_loop_bounds,
                ),
                ResumeTransportCommand::Seek
            );
        let main_result = if main_starts_new_segment {
            state.transport.seek(
                state.transport_generation,
                main_position_millis,
                duration_millis,
                true,
            )
        } else {
            state.transport.play(state.transport_generation)
        };
        let main_token = match main_result {
            Ok(token) => token,
            Err(error) => {
                if state.workspace_mode == WorkspaceMode::Audition {
                    state.audition_auto_advance = false;
                    state.audition_play_token = None;
                }
                state.status = if reference_details.is_some() {
                    cleanup_reference_transport_failure(state, error)
                } else {
                    clear_uncommitted_paired_playback_guard(state);
                    error
                };
                context.request_repaint();
                return;
            }
        };
        if main_starts_new_segment && let Some(intent_millis) = pending_main_intent_millis {
            clear_pending_seek_intent_if_admitted(state, AuditionSource::Main, intent_millis);
        }
        set_source_position(state, AuditionSource::Main, main_position_millis);
        if state.workspace_mode == WorkspaceMode::Audition {
            state.audition_auto_advance = true;
            state.audition_play_token = Some(main_token);
        }
        begin_transport_polling(state, main_token);

        if let Some((_path, reference_duration_millis)) = reference_details {
            let reference_uses_resume_seek = pending_reference_intent_millis.is_some();
            let reference_gain = reference_output_gain(state);
            if !state.reference_transport_loaded {
                clear_live_spectrogram(state, AuditionSource::Reference);
            }
            let reference_transport = state
                .reference_transport
                .get_or_insert_with(transport::AudioTransport::spawn);
            reference_transport.set_output_gain(reference_gain);
            if !state.reference_transport_loaded {
                if let Err(error) = reference_transport.load(
                    state.reference_transport_generation,
                    reference_ticket
                        .clone()
                        .expect("reference details require a verified source ticket"),
                    reference_duration_millis,
                ) {
                    cleanup_reference_transport_failure(state, error);
                    context.request_repaint();
                    return;
                }
                if reference_transport.has_pending_load() {
                    cleanup_reference_transport_failure(
                        state,
                        String::from(transport::CONTROLS_BUSY_ERROR),
                    );
                    context.request_repaint();
                    return;
                }
                state.reference_transport_loaded = true;
            }
            let reference_seek_token = if reference_starts_new_segment {
                let seek_token = match reference_transport.seek(
                    state.reference_transport_generation,
                    reference_position_millis,
                    reference_duration_millis,
                    reference_uses_resume_seek,
                ) {
                    Ok(token) => token,
                    Err(error) => {
                        cleanup_reference_transport_failure(state, error);
                        context.request_repaint();
                        return;
                    }
                };
                if let Some(intent_millis) = pending_reference_intent_millis {
                    clear_pending_seek_intent_if_admitted(
                        state,
                        AuditionSource::Reference,
                        intent_millis,
                    );
                }
                Some((seek_token, reference_uses_resume_seek))
            } else {
                None
            };
            let reference_token = if reference_seek_token.is_some_and(|(_, resume)| resume) {
                reference_seek_token
                    .expect("a resumed reference seek should have a token")
                    .0
            } else {
                match state
                    .reference_transport
                    .as_ref()
                    .expect("reference transport remains loaded")
                    .play(state.reference_transport_generation)
                {
                    Ok(token) => token,
                    Err(error) => {
                        cleanup_reference_transport_failure(state, error);
                        context.request_repaint();
                        return;
                    }
                }
            };
            set_source_position(state, AuditionSource::Reference, reference_position_millis);
            state.reference_transport_waiting_token = Some(reference_token);
            state.reference_transport_polling = true;
            paired_playback_commands_admitted(state);
            state.status = if state.audition_source == AuditionSource::Reference {
                String::from("Playing reference and imported track…")
            } else {
                String::from("Playing imported and reference tracks…")
            };
        } else {
            state.status = String::from("Playing imported track…");
        }
    }
    context.request_repaint();
}

fn start_note_at_current_time(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) || state.busy || state.waveform_busy {
        return;
    }
    if reject_main_source_mismatch(state, context) {
        return;
    }
    if reject_unknown_main_source(state, context) {
        return;
    }
    let Some(track_id) = state.library.selected_track_id.as_deref() else {
        state.status = String::from("Select a track before adding a comment.");
        context.request_repaint();
        return;
    };
    let Some(duration_millis) = state
        .waveform
        .as_ref()
        .filter(|_| state.waveform_track_id.as_deref() == Some(track_id))
        .map(|waveform| waveform.duration_millis)
    else {
        state.status = String::from("Audio analysis is still pending.");
        context.request_repaint();
        return;
    };
    let time_millis = state.review_cursor_millis.min(duration_millis);
    start_main_note_draft(state, context, time_millis);
}

fn start_main_note_draft(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    time_millis: u64,
) {
    if reject_main_source_mismatch(state, context) {
        return;
    }
    if reject_unknown_main_source(state, context) {
        return;
    }
    rollback_persisted_note_drag(state);
    state.comment_source = CommentSource::Main;
    state.comment_source_explicit = true;
    set_audition_source(state, AuditionSource::Main);
    state.review_cursor_millis = time_millis;
    set_pending_seek_intent(state, AuditionSource::Main, time_millis);
    let Some(track_id) = state.library.selected_track_id.clone() else {
        return;
    };
    let nonce = allocate_note_draft_nonce(state);
    state.draft_note = Some(NoteDraft {
        owner: NoteOwner::MainTrack(track_id),
        note_id: None,
        nonce,
        time_millis,
        body: String::new(),
    });
    state.selected_note_id = None;
    state.status = format!(
        "Comment at {} — type a note below.",
        format_timestamp(time_millis)
    );
    context.focus(MAIN_COMMENT_EDITOR_ID);
    context.request_repaint();
}

fn save_draft_note(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    identity: &NoteDraftIdentity,
) {
    if !active_draft_matches(state.draft_note.as_ref(), identity) {
        return;
    }
    if !library_is_ready(state) {
        state.status = library_unavailable_status(state).to_string();
        context.request_repaint();
        return;
    }
    if reject_main_source_mismatch(state, context) {
        return;
    }
    if reject_unknown_main_source(state, context) {
        return;
    }
    if state.busy {
        state.status = String::from("Finish importing before saving a comment.");
        context.request_repaint();
        return;
    }
    let Some(draft) = state.draft_note.clone() else {
        return;
    };
    if !is_current_main_owner(state, &draft.owner) {
        return;
    }
    let body = draft.body.trim().to_string();
    if body.is_empty() {
        state.status = String::from("Write a comment before saving.");
        context.request_repaint();
        return;
    }
    let Some(track) = selected_track_mut(state) else {
        state.status = String::from("Select a track before saving a comment.");
        context.request_repaint();
        return;
    };
    if let Some(note_id) = draft.note_id {
        if let Some(note) = track.notes.iter_mut().find(|note| note.id == note_id) {
            note.body = body;
        } else {
            state.status = String::from("That comment no longer exists.");
            context.request_repaint();
            return;
        }
    } else {
        let note_id = storage::allocate_note_id(&track.notes);
        track.notes.push(storage::Note {
            id: note_id,
            time_millis: draft.time_millis,
            body,
            done: false,
        });
        track.notes.sort_by_key(|note| note.time_millis);
    }
    state.draft_note = None;
    state.status = String::from("Comment saved locally.");
    schedule_library_save(state, context);
    context.request_repaint();
}

fn start_reference_comment_draft(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    ratio: f32,
) {
    if !library_is_ready(state) || state.busy || state.reference_waveform_busy {
        return;
    }
    if reject_main_source_mismatch(state, context)
        || reject_reference_source_mismatch(state, context)
    {
        return;
    }
    if reject_unknown_reference_source(state, context) {
        return;
    }
    let Some(waveform) = state
        .reference_waveform
        .as_ref()
        .filter(|_| !state.reference_waveform_busy)
    else {
        return;
    };
    if selected_track(state)
        .and_then(|track| track.reference_path.as_ref())
        .is_none()
    {
        return;
    }
    let time_millis = waveform::millis_for_ratio(ratio, waveform.duration_millis);
    set_pending_seek_intent(state, AuditionSource::Reference, time_millis);
    let Some(owner) = selected_reference_owner(state) else {
        return;
    };
    let nonce = allocate_note_draft_nonce(state);
    state.reference_draft_note = Some(NoteDraft {
        owner,
        note_id: None,
        nonce,
        time_millis,
        body: String::new(),
    });
    state.selected_reference_note_id = None;
    state.hovered_reference_note_id = None;
    state.status = format!(
        "Reference comment at {} — type a note below.",
        format_timestamp(time_millis)
    );
    context.focus(REFERENCE_COMMENT_EDITOR_ID);
    context.request_repaint();
}

fn save_reference_draft_note(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    identity: &NoteDraftIdentity,
) {
    if !active_draft_matches(state.reference_draft_note.as_ref(), identity) {
        return;
    }
    if !library_is_ready(state) {
        state.status = library_unavailable_status(state).to_string();
        context.request_repaint();
        return;
    }
    if reject_main_source_mismatch(state, context)
        || reject_reference_source_mismatch(state, context)
    {
        return;
    }
    if reject_unknown_reference_source(state, context) {
        return;
    }
    if state.busy {
        state.status = String::from("Finish importing before saving a reference comment.");
        context.request_repaint();
        return;
    }
    let Some(draft) = state.reference_draft_note.clone() else {
        return;
    };
    if !is_current_reference_owner(state, &draft.owner) {
        return;
    }
    let body = draft.body.trim().to_owned();
    if body.is_empty() {
        state.status = String::from("Write a reference comment before saving.");
        context.request_repaint();
        return;
    }
    let Some(reference) = selected_reference_track_mut(state) else {
        state.status = String::from("Select a reference track before saving a comment.");
        context.request_repaint();
        return;
    };
    if let Some(note_id) = draft.note_id {
        if let Some(note) = reference.notes.iter_mut().find(|note| note.id == note_id) {
            note.body = body;
        } else {
            state.status = String::from("That reference comment no longer exists.");
            context.request_repaint();
            return;
        }
    } else {
        let note_id = storage::allocate_note_id(&reference.notes);
        reference.notes.push(storage::Note {
            id: note_id,
            time_millis: draft.time_millis,
            body,
            done: false,
        });
        reference.notes.sort_by_key(|note| note.time_millis);
    }
    state.reference_draft_note = None;
    state.status = String::from("Reference comment saved locally.");
    schedule_library_save(state, context);
    context.request_repaint();
}

fn move_draft_note(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>, ratio: f32) {
    if !main_annotations_available(state) {
        return;
    }
    let Some(duration_millis) = state
        .waveform
        .as_ref()
        .map(|waveform| waveform.duration_millis)
    else {
        return;
    };
    let Some(draft) = state
        .draft_note
        .as_mut()
        .filter(|draft| draft.note_id.is_none())
    else {
        return;
    };
    let time_millis = waveform::millis_for_ratio(ratio, duration_millis);
    draft.time_millis = time_millis;
    state.review_cursor_millis = time_millis;
    set_pending_seek_intent(state, AuditionSource::Main, time_millis);
    state.status = format!("Comment at {}.", format_timestamp(time_millis));
    context.request_repaint();
}

fn start_persisted_note_drag(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    address: NoteAddress,
) {
    if !library_is_ready(state) {
        return;
    }
    if !main_annotations_available(state) {
        return;
    }
    rollback_persisted_note_drag(state);
    if state.busy {
        return;
    }
    if !is_current_main_note_address(state, &address) {
        return;
    }
    let Some(track_id) = state.library.selected_track_id.clone() else {
        return;
    };
    let waveform_is_current =
        state.waveform.is_some() && state.waveform_track_id.as_deref() == Some(track_id.as_str());
    let Some((_, time_millis)) = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == track_id)
        .filter(|_| waveform_is_current)
        .and_then(|track| track.notes.iter().find(|note| note.id == address.note_id))
        .map(|note| (note.id.clone(), note.time_millis))
    else {
        state.status = String::from("That comment no longer exists.");
        context.request_repaint();
        return;
    };

    if state
        .draft_note
        .as_ref()
        .is_some_and(|draft| draft.address().as_ref() == Some(&address))
    {
        if let Some(draft) = state.draft_note.as_mut() {
            draft.time_millis = time_millis;
        }
    } else {
        // Picking up a saved marker supersedes an empty draft or an editor for
        // another note; it must never create a second draft for this marker.
        state.draft_note = None;
    }
    state.persisted_note_drag = Some(PersistedNoteDrag {
        address: address.clone(),
        original_time_millis: time_millis,
    });
    state.selected_note_id = Some(address);
    state.hovered_note_id = None;
    state.review_cursor_millis = time_millis;
    state.transport_position_millis = time_millis;
    set_pending_seek_intent(state, AuditionSource::Main, time_millis);
    state.status = format!("Dragging comment at {}…", format_timestamp(time_millis));
    context.request_repaint();
}

fn finish_persisted_note_drag(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    ratio: f32,
) {
    if !library_is_ready(state) {
        return;
    }
    if !main_annotations_available(state) {
        return;
    }
    let Some(drag) = state.persisted_note_drag.take() else {
        return;
    };
    if !is_current_main_note_address(state, &drag.address) {
        return;
    }
    let NoteOwner::MainTrack(track_id) = &drag.address.owner else {
        return;
    };
    let Some(duration_millis) = state
        .waveform
        .as_ref()
        .filter(|_| state.waveform_track_id.as_deref() == Some(track_id.as_str()))
        .map(|waveform| waveform.duration_millis)
    else {
        return;
    };
    let time_millis = waveform::millis_for_ratio(ratio, duration_millis);
    let Some(track) = state
        .library
        .tracks
        .iter_mut()
        .find(|track| track.id == *track_id)
    else {
        state.status = String::from("That track is no longer in the library.");
        context.request_repaint();
        return;
    };
    let Some(note) = track
        .notes
        .iter_mut()
        .find(|note| note.id == drag.address.note_id)
    else {
        state.status = String::from("That comment no longer exists.");
        context.request_repaint();
        return;
    };
    if time_millis != drag.original_time_millis {
        note.time_millis = time_millis;
    }
    let final_time_millis = note.time_millis;
    let changed = final_time_millis != drag.original_time_millis;
    track.notes.sort_by_key(|note| note.time_millis);
    if let Some(draft) = state
        .draft_note
        .as_mut()
        .filter(|draft| draft.address().as_ref() == Some(&drag.address))
    {
        draft.time_millis = final_time_millis;
    }
    state.review_cursor_millis = final_time_millis;
    state.transport_position_millis = final_time_millis;
    set_pending_seek_intent(state, AuditionSource::Main, final_time_millis);
    state.status = if changed {
        format!(
            "Comment moved to {} and saved locally.",
            format_timestamp(final_time_millis)
        )
    } else {
        format!(
            "Selected comment at {}.",
            format_timestamp(final_time_millis)
        )
    };
    if changed {
        schedule_library_save(state, context);
    }
    context.request_repaint();
}

