fn audio_file_dialog(title: &str) -> FileDialogRequest {
    FileDialogRequest::new().title(title).filter(
        "Audio",
        vec![
            String::from("wav"),
            String::from("aiff"),
            String::from("flac"),
            String::from("m4a"),
            String::from("mp3"),
            String::from("ogg"),
            String::from("opus"),
            String::from("aac"),
        ],
    )
}

fn pick_reference_tracks() -> Vec<PathBuf> {
    // Radiant's pinned platform picker intentionally returns one path. Keep
    // the multi-selection interaction local to Cadence until that API grows a
    // native multi-path response.
    rfd::FileDialog::new()
        .set_title("Import reference tracks")
        .add_filter(
            "Audio",
            &["wav", "aiff", "flac", "m4a", "mp3", "ogg", "opus", "aac"],
        )
        .pick_files()
        .unwrap_or_default()
}

fn record_import_attempt(state: &mut AppState, failed: bool) {
    if !library_is_ready(state) {
        return;
    }
    if let Some(batch) = state.import_batch.as_mut() {
        batch.completed = batch.completed.saturating_add(1).min(batch.total);
        if failed {
            batch.failed = batch.failed.saturating_add(1).min(batch.completed);
        }
    }
}

fn finish_import_batch(state: &mut AppState) {
    if !library_is_ready(state) {
        return;
    }
    let should_finish = match state.import_batch.as_ref() {
        Some(batch) => {
            batch.completed >= batch.total
                && state.pending_import_paths.is_empty()
                && state.pending_reference_paths.is_empty()
        }
        None => false,
    };
    if !should_finish {
        return;
    }

    let Some(batch) = state.import_batch.take() else {
        return;
    };
    if batch.total > 1 {
        state.status = format!(
            "Imported {} of {} files; {} failed.",
            batch.total - batch.failed,
            batch.total,
            batch.failed
        );
    }
}

fn start_audio_import_preflight(
    context: &mut ui::UiUpdateContext<Message>,
    request: AudioImportRequest,
) {
    let completion_request = request.clone();
    let path = request.path.clone();
    let replacement_preflight = matches!(request.target, AudioImportTarget::Replacement { .. });
    context
        .business()
        .background("cadence-import-preflight")
        .cancellable()
        .run(
            move |work| {
                let decoded =
                    audio::decode_audio_file_with_cancellation(&path, || work.is_cancelled())
                        .map_err(|error| {
                            if replacement_preflight {
                                format!("Could not decode replacement {}: {error}", path.display())
                            } else {
                                error
                            }
                        })?;
                work.check_cancelled()?;
                let cache_path = storage::waveform_cache_path(&path, decoded.source_proof());
                let _ = audio::write_waveform_cache_if_unchanged(
                    decoded.path(),
                    &cache_path,
                    &decoded.source_ticket(),
                    decoded.waveform(),
                );
                work.check_cancelled()?;
                Ok(decoded)
            },
            move |result| Message::AudioImportPreflightCompleted {
                request: completion_request,
                result,
            },
        );
}

