fn reference_selection_catalog_matches(
    state: &AppState,
    path: &Path,
    expected_proof: Option<&crate::source::AudioSourceProof>,
) -> bool {
    state
        .library
        .reference_tracks
        .iter()
        .find(|reference| reference.path == path)
        .is_some_and(|reference| reference.source_provenance().verified_proof() == expected_proof)
}

fn complete_reference_selection_preflight(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    request_id: u64,
    track_id: String,
    path: PathBuf,
    expected_proof: Option<crate::source::AudioSourceProof>,
    result: Result<audio::DecodedAudioFile, String>,
) {
    let error = match result {
        Ok(decoded) => {
            if !reference_selection_catalog_matches(state, &path, expected_proof.as_ref()) {
                format!(
                    "Reference catalog changed while verifying {}; selection was not applied.",
                    path.display()
                )
            } else if expected_proof
                .as_ref()
                .is_some_and(|expected| expected != decoded.source_proof())
            {
                format!(
                    "Reference source changed for {}. Please remove it from the reference catalog and re-import it.",
                    path.display()
                )
            } else {
                start_reference_selection_commit(
                    state, context, request_id, track_id, path, decoded,
                );
                return;
            }
        }
        Err(error) => error,
    };
    state.pending_import_commit = Some(PendingImportCommit::ReferenceSelection { request_id });
    update(
        state,
        Message::ReferenceSelectionCompleted {
            request_id,
            track_id,
            path,
            result: Err(error),
        },
        context,
    );
}

fn complete_reference_selection_commit(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    request_id: u64,
    track_id: String,
    path: PathBuf,
    result: Result<storage::Library, String>,
) {
    if state.pending_import_commit.as_ref()
        != Some(&PendingImportCommit::ReferenceSelection { request_id })
    {
        return;
    }
    state.pending_import_commit = None;
    state.busy = false;
    if !library_is_ready(state) {
        state.status = library_unavailable_status(state).to_string();
        schedule_next_pending_library_operation(state, context);
        context.request_repaint();
        return;
    }

    let previous_path = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == track_id)
        .and_then(|track| track.reference_path.clone());
    let selected = state.library.selected_track_id.as_deref() == Some(track_id.as_str());
    let selected_path_changed = selected && previous_path.as_ref() != Some(&path);

    match result {
        Ok(library) => {
            state.library = library;
            reset_comments_windows(state);
            refresh_selected_track_index(state);
            mark_library_snapshot_persisted(state);
            close_reference_menu(state);
            if selected_path_changed {
                state.reference_draft_note = None;
                state.selected_reference_note_id = None;
                state.hovered_reference_note_id = None;
                reset_reference_transport(state);
                state.reference_match_enabled = false;
                schedule_selected_reference_decode(state, context);
            }
            state.status = format!("Reference set to {}.", reference_track_name(&path));
        }
        Err(error) => {
            close_reference_menu(state);
            state.status = error;
        }
    }
    schedule_next_pending_library_operation(state, context);
    context.request_repaint();
}

fn complete_audio_import_preflight(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    request: AudioImportRequest,
    result: Result<audio::DecodedAudioFile, String>,
) {
    let is_current = state
        .audio_import_in_flight
        .as_ref()
        .is_some_and(|current| current == &request);
    if !is_current {
        return;
    }
    state.audio_import_in_flight = None;
    let AudioImportRequest { target, path } = request;
    let result = if library_is_ready(state) {
        result
    } else {
        Err(library_unavailable_status(state).to_string())
    };
    match (target, result) {
        (AudioImportTarget::Main, Ok(decoded)) => start_import_commit(state, context, decoded),
        (AudioImportTarget::AssignedReference { track_id }, Ok(decoded)) => {
            start_reference_commit(state, context, track_id, path, decoded);
        }
        (AudioImportTarget::Catalog, Ok(decoded)) => {
            start_reference_catalog_commit(state, context, path, decoded);
        }
        (
            AudioImportTarget::ReferenceSelection {
                request_id,
                track_id,
                expected_proof,
            },
            result,
        ) => {
            complete_reference_selection_preflight(
                state,
                context,
                request_id,
                track_id,
                path,
                expected_proof,
                result,
            );
        }
        (AudioImportTarget::Replacement { track_id }, Ok(decoded)) => {
            start_replace_commit(state, context, track_id, decoded);
        }
        (AudioImportTarget::Main, Err(error)) => {
            state.pending_import_commit = Some(PendingImportCommit::Main);
            update(state, Message::ImportCompleted(Err(error)), context);
        }
        (AudioImportTarget::AssignedReference { track_id }, Err(error)) => {
            state.pending_import_commit = Some(PendingImportCommit::AssignedReference {
                track_id: track_id.clone(),
                path: path.clone(),
            });
            update(
                state,
                Message::ReferenceImportCompleted {
                    track_id,
                    path,
                    result: Err(error),
                },
                context,
            );
        }
        (AudioImportTarget::Replacement { track_id }, Err(error)) => {
            state.pending_import_commit = Some(PendingImportCommit::Replacement {
                track_id: track_id.clone(),
            });
            update(
                state,
                Message::ReplaceCompleted {
                    track_id,
                    result: Err(error),
                },
                context,
            );
        }
        (AudioImportTarget::Catalog, Err(error)) => {
            state.pending_import_commit = Some(PendingImportCommit::Catalog { path: path.clone() });
            update(
                state,
                Message::ReferenceCatalogImportCompleted {
                    path,
                    result: Err(error),
                },
                context,
            );
        }
    }
}

fn start_historical_binding(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    candidate: HistoricalBindingCandidate,
) {
    if state.busy || !library_is_ready(state) {
        return;
    }
    if state.historical_binding_confirmation.as_ref() != Some(&candidate) {
        return;
    }
    let candidate = state
        .historical_binding_confirmation
        .take()
        .expect("the matching historical binding candidate should be present");
    if historical_binding_candidate(state, candidate.owner.clone()).as_ref() != Some(&candidate) {
        state.status = String::from(
            "The displayed source changed before binding; retained historical comments were not changed.",
        );
        context.request_repaint();
        return;
    }
    state.next_historical_binding_request_id = state
        .next_historical_binding_request_id
        .checked_add(1)
        .expect("historical binding request id overflow");
    let request = HistoricalBindingRequest {
        id: state.next_historical_binding_request_id,
        candidate,
    };
    let path = request.candidate.path.clone();
    let completion_request = request.clone();
    let cancellation = ui::CancellationToken::new();
    let worker_cancellation = cancellation.clone();
    state.historical_binding_in_flight = Some(request);
    state.historical_binding_cancellation = Some(cancellation);
    state.busy = true;
    state.status = format!(
        "Verifying the current source before binding {} comments…",
        completion_request.candidate.note_count
    );
    context
        .business()
        .background("cadence-bind-historical-comments")
        .cancellable()
        .run(
            move |work| {
                source::hash_file(&path, || {
                    work.is_cancelled() || worker_cancellation.is_cancelled()
                })
                .map_err(|error| error.to_string())
            },
            move |result| Message::HistoricalBindingCompleted {
                request: completion_request,
                result,
            },
        );
    context.request_repaint();
}

fn complete_historical_binding(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    request: HistoricalBindingRequest,
    result: Result<crate::source::AudioSourceProof, String>,
) {
    if state.historical_binding_in_flight.as_ref() != Some(&request) {
        return;
    }
    state.historical_binding_in_flight = None;
    state.historical_binding_cancellation = None;
    state.busy = false;

    let candidate = request.candidate;
    let Ok(fresh_proof) = result else {
        state.status =
            historical_source_warning(&candidate.owner, &candidate.path, candidate.note_count);
        context.request_repaint();
        return;
    };
    let Some(ticket) = current_historical_binding_ticket(state, &candidate) else {
        state.status = String::from(
            "The displayed source changed before binding; retained historical comments were not changed.",
        );
        context.request_repaint();
        return;
    };
    let current_note_count = match &candidate.owner {
        HistoricalBindingOwner::Main { track_id } => state
            .library
            .tracks
            .iter()
            .find(|track| track.id == *track_id && track.path == candidate.path)
            .map_or(0, |track| track.notes.len()),
        HistoricalBindingOwner::Reference { path } => state
            .library
            .reference_tracks
            .iter()
            .find(|reference| &reference.path == path)
            .map_or(0, |reference| reference.notes.len()),
    };
    let still_current = ticket.path() == candidate.path
        && ticket.proof() == &candidate.displayed_proof
        && fresh_proof == candidate.displayed_proof
        && binding_owner_is_still_unknown(state, &candidate)
        && current_note_count == candidate.note_count;
    if !still_current {
        state.status = if fresh_proof != candidate.displayed_proof {
            match candidate.owner {
                HistoricalBindingOwner::Main { .. } => {
                    state.main_source_mismatch = Some(candidate.path.clone());
                    reset_transport(state);
                    String::from(MAIN_SOURCE_MISMATCH_STATUS)
                }
                HistoricalBindingOwner::Reference { .. } => {
                    state.reference_source_mismatch = Some(candidate.path.clone());
                    reset_reference_transport(state);
                    String::from(REFERENCE_SOURCE_MISMATCH_STATUS)
                }
            }
        } else {
            String::from(
                "The displayed source changed before binding; retained historical comments were not changed.",
            )
        };
        context.request_repaint();
        return;
    }

    let bind_result = match &candidate.owner {
        HistoricalBindingOwner::Main { track_id } => storage::bind_main_source_proof(
            &mut state.library,
            track_id,
            &candidate.path,
            fresh_proof,
        ),
        HistoricalBindingOwner::Reference { .. } => {
            storage::bind_reference_source_proof(&mut state.library, &candidate.path, fresh_proof)
        }
    };
    match bind_result {
        Ok(()) => {
            state.status = format!(
                "Bound {} historical comment{} to {}. Notes were preserved.",
                candidate.note_count,
                plural(candidate.note_count),
                candidate.path.display()
            );
            schedule_library_save(state, context);
        }
        Err(error) => state.status = error,
    }
    context.request_repaint();
}

fn start_import(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>, path: PathBuf) {
    if !library_is_ready(state) {
        return;
    }
    state.busy = true;
    state.status = format!("Importing {}…", path.display());
    let request = AudioImportRequest {
        target: AudioImportTarget::Main,
        path,
    };
    state.audio_import_in_flight = Some(request.clone());
    start_audio_import_preflight(context, request);
    context.request_repaint();
}

fn schedule_import(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    path: PathBuf,
) {
    if state.library_load_state == LibraryLoadState::RecoveryRequired {
        state.status = library_unavailable_status(state).to_string();
        context.request_repaint();
        return;
    }
    let batch = state.import_batch.get_or_insert_with(Default::default);
    batch.total = batch.total.saturating_add(1);
    if state.library_load_state == LibraryLoadState::Loading
        || state.busy
        || library_persistence_pending(state)
    {
        let display_name = path.display().to_string();
        state.pending_import_paths.push_back(path);
        state.status = if state.library_load_state == LibraryLoadState::Loading {
            format!(
                "Queued {} for import while the library loads · {} file{} waiting.",
                display_name,
                state.pending_import_paths.len(),
                plural(state.pending_import_paths.len())
            )
        } else if state.busy {
            format!(
                "Queued {} for import · {} file{} waiting.",
                display_name,
                state.pending_import_paths.len(),
                plural(state.pending_import_paths.len())
            )
        } else {
            String::from("Saving the library — the dropped file is queued for import.")
        };
        context.request_repaint();
        return;
    }
    start_import(state, context, path);
}

fn schedule_next_pending_library_operation(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if !library_is_ready(state) || state.busy || library_persistence_pending(state) {
        return;
    }
    if let Some(path) = state.pending_import_paths.pop_front() {
        start_import(state, context, path);
        return;
    }
    if let Some(track_id) = state.pending_reference_track_id.clone()
        && let Some(path) = state.pending_reference_paths.pop_front()
    {
        schedule_reference(state, context, track_id, path);
        return;
    }
    if let Some(path) = state.pending_reference_catalog_paths.pop_front() {
        start_reference_catalog_import(state, context, path);
    }
}

fn schedule_reference_import(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    track_id: String,
    paths: Vec<PathBuf>,
) {
    if !library_is_ready(state) {
        state.status = library_unavailable_status(state).to_string();
        context.request_repaint();
        return;
    }
    if paths.is_empty() {
        state.status = String::from("Reference import canceled.");
        context.request_repaint();
        return;
    }
    if !state
        .library
        .tracks
        .iter()
        .any(|track| track.id == track_id)
    {
        state.status = String::from("That track is no longer in the library.");
        context.request_repaint();
        return;
    }
    state.pending_reference_paths = paths.into();
    state.pending_reference_track_id = Some(track_id);
    state.reference_import_selected_path = None;
    state.reference_draft_note = None;
    state.selected_reference_note_id = None;
    state.hovered_reference_note_id = None;
    let batch = state.import_batch.get_or_insert_with(Default::default);
    batch.total = batch
        .total
        .saturating_add(state.pending_reference_paths.len());
    schedule_next_pending_reference_import(state, context);
}

fn schedule_next_pending_reference_import(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if !library_is_ready(state) || state.busy || library_persistence_pending(state) {
        return;
    }
    let Some(track_id) = state.pending_reference_track_id.clone() else {
        return;
    };
    let Some(path) = state.pending_reference_paths.pop_front() else {
        return;
    };
    schedule_reference(state, context, track_id, path);
}

fn schedule_reference_catalog_import(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    paths: Vec<PathBuf>,
) {
    if !library_is_ready(state) {
        state.status = library_unavailable_status(state).to_string();
        context.request_repaint();
        return;
    }
    state.pending_reference_catalog_paths = paths.into();
    state.reference_catalog_import_total = state.pending_reference_catalog_paths.len();
    state.reference_catalog_import_completed = 0;
    state.reference_catalog_import_failed = 0;
    schedule_next_reference_catalog_import(state, context);
}

fn schedule_next_reference_catalog_import(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if !library_is_ready(state) || state.busy || library_persistence_pending(state) {
        return;
    }
    let Some(path) = state.pending_reference_catalog_paths.pop_front() else {
        return;
    };
    start_reference_catalog_import(state, context, path);
}

fn start_reference_catalog_import(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    path: PathBuf,
) {
    if !library_is_ready(state) {
        return;
    }
    state.busy = true;
    state.status = format!(
        "Adding {} to the reference catalog…",
        reference_track_name(&path)
    );
    let request = AudioImportRequest {
        target: AudioImportTarget::Catalog,
        path,
    };
    state.audio_import_in_flight = Some(request.clone());
    start_audio_import_preflight(context, request);
    context.request_repaint();
}

fn schedule_replace(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    track_id: String,
    path: PathBuf,
) {
    if !library_is_ready(state) || state.busy {
        if !library_is_ready(state) {
            state.status = library_unavailable_status(state).to_string();
            context.request_repaint();
        }
        return;
    }
    if library_persistence_pending(state) {
        state.status = String::from("Saving the library — try replacing again in a moment.");
        context.request_repaint();
        return;
    }
    if !state
        .library
        .tracks
        .iter()
        .any(|track| track.id == track_id)
    {
        state.status = String::from("That track is no longer in the library.");
        context.request_repaint();
        return;
    }
    state.busy = true;
    state.status = format!("Replacing with {}…", path.display());
    let request = AudioImportRequest {
        target: AudioImportTarget::Replacement { track_id },
        path,
    };
    state.audio_import_in_flight = Some(request.clone());
    start_audio_import_preflight(context, request);
    context.request_repaint();
}

fn schedule_reference(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    track_id: String,
    path: PathBuf,
) {
    if !library_is_ready(state) || state.busy {
        if !library_is_ready(state) {
            state.status = library_unavailable_status(state).to_string();
            context.request_repaint();
        }
        return;
    }
    if library_persistence_pending(state) {
        state.status =
            String::from("Saving the library — try importing a reference again in a moment.");
        context.request_repaint();
        return;
    }
    if !state
        .library
        .tracks
        .iter()
        .any(|track| track.id == track_id)
    {
        state.status = String::from("That track is no longer in the library.");
        context.request_repaint();
        return;
    }
    state.busy = true;
    state.status = format!("Importing reference {}…", path.display());
    let request = AudioImportRequest {
        target: AudioImportTarget::AssignedReference { track_id },
        path,
    };
    state.audio_import_in_flight = Some(request.clone());
    start_audio_import_preflight(context, request);
    context.request_repaint();
}

fn library_dirty(state: &AppState) -> bool {
    state.library_revision != state.persisted_library_revision
}

fn library_persistence_pending(state: &AppState) -> bool {
    library_dirty(state) || state.save_in_flight.is_some()
}

/// Queue one save admission for the current UI turn's dirty revisions.
///
/// The admission is intentionally deferred so several mutations can share one
/// snapshot boundary. The invariant is that this flag is only an admission
/// request: the eventual handler always reads the current library and
/// `library_revision`, while `persisted_library_revision` advances only after
/// the matching durable worker completion. A dirty revision is therefore
/// never dropped by coalescing.
fn request_library_save_admission(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if !library_is_ready(state)
        || !library_dirty(state)
        || state.save_in_flight.is_some()
        || state.save_admission_pending
    {
        return;
    }
    state.save_admission_pending = true;
    context.after(Duration::ZERO, Message::AdmitLibrarySave);
}

fn dispatch_library_save(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) || !library_dirty(state) || state.save_in_flight.is_some() {
        return;
    }
    state.save_admission_pending = false;
    let revision = state.library_revision;
    let id = state
        .last_save_attempt_id
        .checked_add(1)
        .expect("library save attempt id overflow");
    state.last_save_attempt_id = id;
    let attempt = LibrarySaveAttempt { id, revision };
    let library = state.library.clone();
    state.save_in_flight = Some(attempt);
    context.business().blocking_io("cadence-save-library").run(
        move |_| storage::persist_library(&library),
        move |result| Message::LibrarySaved { attempt, result },
    );
}

fn schedule_library_save(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) {
        return;
    }
    state.library_revision = state.library_revision.wrapping_add(1);
    request_library_save_admission(state, context);
}

fn retry_library_save(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) || state.busy || state.save_in_flight.is_some() {
        return;
    }
    dispatch_library_save(state, context);
}

fn mark_library_snapshot_persisted(state: &mut AppState) {
    state.library_revision = state.library_revision.wrapping_add(1);
    state.persisted_library_revision = state.library_revision;
    state.save_in_flight = None;
    state.save_admission_pending = false;
}

fn reset_transport(state: &mut AppState) {
    clear_pending_seek_intent(state, AuditionSource::Main);
    match &mut state.paired_playback_guard {
        PairedPlaybackGuard::StoppingMain {
            pending_reset_main, ..
        }
        | PairedPlaybackGuard::StoppingReference {
            pending_reset_main, ..
        } => {
            *pending_reset_main = true;
            return;
        }
        _ => {}
    }
    clear_paired_playback_guard(state);
    clear_live_spectrogram(state, AuditionSource::Main);
    state.transport_generation = state.transport_generation.wrapping_add(1);
    state.audition_play_token = None;
    state.transport_position_millis = 0;
    state.review_cursor_millis = 0;
    state.loop_selections.clear(AuditionSource::Main);
    state.playhead_drag_active = false;
    state.transport_playing = false;
    state.transport_polling = false;
    state.transport_waiting_token = None;
    let _ = state.transport.unload(state.transport_generation);
}

fn reset_reference_transport(state: &mut AppState) {
    clear_pending_seek_intent(state, AuditionSource::Reference);
    match &mut state.paired_playback_guard {
        PairedPlaybackGuard::StoppingMain {
            pending_reset_reference,
            ..
        }
        | PairedPlaybackGuard::StoppingReference {
            pending_reset_reference,
            ..
        } => {
            *pending_reset_reference = true;
            return;
        }
        _ => {}
    }
    clear_paired_playback_guard(state);
    clear_live_spectrogram(state, AuditionSource::Reference);
    state.reference_transport_generation = state.reference_transport_generation.wrapping_add(1);
    state.reference_playhead_drag_active = false;
    rollback_reference_persisted_note_drag(state);
    state.reference_transport_position_millis = 0;
    state.loop_selections.clear(AuditionSource::Reference);
    state.audition_source = AuditionSource::Main;
    state.reference_transport_playing = false;
    state.reference_transport_polling = false;
    state.reference_transport_waiting_token = None;
    state.reference_transport_loaded = false;
    state.reference_only_playback = false;
    if let Some(reference_transport) = state.reference_transport.as_ref() {
        let _ = reference_transport.unload(state.reference_transport_generation);
    }
    sync_audition_output_gains(state);
}

fn begin_transport_polling(state: &mut AppState, token: u64) {
    state.transport_waiting_token = Some(token);
    state.transport_polling = true;
}

fn apply_transport_snapshot(state: &mut AppState, snapshot: transport::Snapshot) {
    if snapshot.ready {
        if !state.playhead_drag_active {
            state.transport_position_millis = snapshot.position_millis;
            state.review_cursor_millis = snapshot.position_millis;
        }
        state.transport_playing = snapshot.playing;
        state.transport_polling = false;
    } else {
        state.transport_playing = false;
        state.transport_polling = false;
    }
}

fn update_reference_transport(state: &mut AppState) {
    let Some(snapshot) = state
        .reference_transport
        .as_ref()
        .map(transport::AudioTransport::snapshot)
    else {
        return;
    };
    if snapshot.generation != state.reference_transport_generation {
        return;
    }
    if let Some(warning) = state
        .reference_transport
        .as_ref()
        .and_then(|reference_transport| {
            reference_transport.take_analysis_warning(state.reference_transport_generation)
        })
    {
        state.status = format!("Live spectrogram unavailable: {warning}");
    }
    if let Some(error) = state
        .reference_transport
        .as_ref()
        .and_then(|reference_transport| {
            reference_transport.take_error(state.reference_transport_generation)
        })
    {
        if source_error_is_mismatch(&error) {
            handle_reference_transport_source_mismatch(state);
        } else {
            cleanup_reference_transport_failure(state, error);
        }
        return;
    }
    if !paired_playback_cleanup_active(state)
        && state
            .reference_transport_waiting_token
            .is_none_or(|token| transport_command_is_confirmed(snapshot, token))
    {
        state.reference_transport_waiting_token = None;
        apply_reference_transport_snapshot(state, snapshot);
    }
}

fn apply_reference_transport_snapshot(state: &mut AppState, snapshot: transport::Snapshot) {
    if snapshot.ready {
        if !state.reference_playhead_drag_active {
            state.reference_transport_position_millis = snapshot.position_millis;
        }
        state.reference_transport_playing = snapshot.playing;
        state.reference_transport_polling = false;
    } else {
        state.reference_transport_playing = false;
        state.reference_transport_polling = false;
    }
}

fn clear_live_spectrogram(state: &mut AppState, source: AuditionSource) {
    match source {
        AuditionSource::Main => {
            state.live_spectrogram = None;
            state.live_spectrogram_revision = 0;
            state.transport.clear_live_frame();
        }
        AuditionSource::Reference => {
            state.reference_live_spectrogram = None;
            state.reference_live_spectrogram_revision = 0;
            if let Some(reference_transport) = state.reference_transport.as_ref() {
                reference_transport.clear_live_frame();
            }
        }
    }
}

fn reset_live_spectrogram_segment(state: &mut AppState, source: AuditionSource) {
    match source {
        AuditionSource::Main => {
            state.live_spectrogram = None;
            state.live_spectrogram_revision = 0;
            state.transport.reset_live_segment();
        }
        AuditionSource::Reference => {
            state.reference_live_spectrogram = None;
            state.reference_live_spectrogram_revision = 0;
            if let Some(reference_transport) = state.reference_transport.as_ref() {
                reference_transport.reset_live_segment();
            }
        }
    }
}

fn refresh_live_spectrograms(state: &mut AppState) {
    let (main_state, main_frame) = state.transport.live_frame_snapshot();
    refresh_live_spectrogram(
        &mut state.live_spectrogram,
        &mut state.live_spectrogram_revision,
        state.transport_generation,
        main_state,
        main_frame,
    );

    let Some(reference_transport) = state.reference_transport.as_ref() else {
        state.reference_live_spectrogram = None;
        state.reference_live_spectrogram_revision = 0;
        return;
    };
    let (reference_state, reference_frame) = reference_transport.live_frame_snapshot();
    refresh_live_spectrogram(
        &mut state.reference_live_spectrogram,
        &mut state.reference_live_spectrogram_revision,
        state.reference_transport_generation,
        reference_state,
        reference_frame,
    );
}

fn live_frame_matches_current_session(
    frame: &transport::LiveSpectrogramFrame,
    generation: u64,
    live_state: transport::LiveFrameState,
) -> bool {
    live_state.generation == generation
        && live_state.revision > 0
        && frame.generation == generation
        && frame.epoch == live_state.epoch
        && frame.revision > 0
        && frame.revision <= live_state.revision
        && frame.is_valid()
}

fn refresh_live_spectrogram(
    visible: &mut Option<Arc<transport::LiveSpectrogramFrame>>,
    visible_revision: &mut u64,
    generation: u64,
    live_state: transport::LiveFrameState,
    latest: Option<Arc<transport::LiveSpectrogramFrame>>,
) {
    // The UI reads the state and payload from one coherent shared snapshot, so
    // a transient publication boundary cannot clear a still-valid frame.
    let visible_is_current = visible.as_ref().is_some_and(|frame| {
        live_frame_matches_current_session(frame, generation, live_state)
            && frame.revision == *visible_revision
    });
    if !visible_is_current {
        *visible = None;
        *visible_revision = 0;
    }

    if let Some(frame) =
        latest.filter(|frame| live_frame_matches_current_session(frame, generation, live_state))
    {
        let is_newer = visible
            .as_ref()
            .is_none_or(|current| frame.revision >= current.revision);
        if is_newer {
            *visible_revision = frame.revision;
            *visible = Some(frame);
        }
    }
}

fn enforce_loop(state: &mut AppState, was_main_playing: bool, was_reference_playing: bool) {
    enforce_loop_for_source(state, AuditionSource::Main, was_main_playing);
    enforce_loop_for_source(state, AuditionSource::Reference, was_reference_playing);
}

fn enforce_loop_for_source(state: &mut AppState, source: AuditionSource, was_playing: bool) {
    if source == AuditionSource::Main && state.reference_only_playback {
        return;
    }
    let Some(bounds) = loop_bounds_for_source(state, source) else {
        return;
    };
    let source_is_playing = match source {
        AuditionSource::Main => state.transport_playing,
        AuditionSource::Reference => state.reference_transport_playing,
    };
    let source_is_polling = match source {
        AuditionSource::Main => state.transport_polling || state.transport_waiting_token.is_some(),
        AuditionSource::Reference => {
            state.reference_transport_polling || state.reference_transport_waiting_token.is_some()
        }
    };
    if source_is_polling || !(was_playing || source_is_playing) {
        return;
    }
    if source == AuditionSource::Reference && !state.reference_transport_loaded {
        return;
    }
    if source_position(state, source) < bounds.end_millis {
        return;
    }
    match seek_loop_owner(state, source, bounds) {
        Ok(()) => state.status = String::from("Looping the selected section…"),
        Err(error) => state.status = error,
    }
}

fn seek_review_position(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    ratio: f32,
    resume: bool,
) {
    if !library_is_ready(state) {
        return;
    }
    if reject_main_source_mismatch(state, context) {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.waveform_busy
        || (state.reference_waveform_busy && !reference_source_is_mismatched(state))
    {
        return;
    }
    let Some(duration_millis) = state
        .waveform
        .as_ref()
        .map(|waveform| waveform.duration_millis)
    else {
        return;
    };
    disarm_audition_auto_advance(state);
    let time_millis = waveform::millis_for_ratio(ratio, duration_millis);
    set_pending_seek_intent(state, AuditionSource::Main, time_millis);
    state.reference_only_playback = false;
    if resume {
        match resume_main_at_position_with_reference(state, time_millis) {
            Ok(()) => {
                state.status = format!("Playing from {}.", format_timestamp(time_millis));
            }
            Err(error) => state.status = error,
        }
    } else {
        state.review_cursor_millis = time_millis;
        state.transport_position_millis = time_millis;
        state.status = format!("Scrubbing at {}.", format_timestamp(time_millis));
    }
    context.request_repaint();
}

fn comment_time_for_address(state: &AppState, address: &NoteAddress) -> Option<u64> {
    match &address.owner {
        NoteOwner::MainTrack(track_id) => state
            .library
            .tracks
            .iter()
            .find(|track| {
                track.id == *track_id && track.source_provenance().verified_proof().is_some()
            })?
            .notes
            .iter()
            .find(|note| note.id == address.note_id)
            .map(|note| note.time_millis),
        NoteOwner::ReferenceTrack(path) => state
            .library
            .reference_tracks
            .iter()
            .find(|reference| {
                reference.path == *path && reference.source_provenance().verified_proof().is_some()
            })?
            .notes
            .iter()
            .find(|note| note.id == address.note_id)
            .map(|note| note.time_millis),
    }
}

fn play_comment(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    address: NoteAddress,
) {
    if !library_is_ready(state) || state.busy {
        return;
    }
    let source = address.source();
    let blocked = match source {
        CommentSource::Main => {
            reject_main_source_mismatch(state, context)
                || reject_unknown_main_source(state, context)
        }
        CommentSource::Reference => {
            reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
                || reject_unknown_reference_source(state, context)
        }
    };
    if blocked {
        return;
    }
    if let NoteOwner::MainTrack(track_id) = &address.owner
        && state.library.selected_track_id.as_deref() != Some(track_id.as_str())
    {
        if comment_time_for_address(state, &address).is_none() {
            state.status = String::from("That comment no longer exists.");
            context.request_repaint();
            return;
        }
        let title = state
            .library
            .tracks
            .iter()
            .find(|track| track.id == *track_id)
            .map_or_else(|| String::from("track"), |track| track.title.clone());
        select_track_internal(state, context, track_id.clone(), false);
        state.pending_comment_playback = Some(PendingCommentPlayback { address });
        state.status = format!("Loading comment on {title}…");
        context.request_repaint();
        return;
    }
    let address_is_current = match source {
        CommentSource::Main => is_current_main_note_address(state, &address),
        CommentSource::Reference => is_current_reference_note_address(state, &address),
    };
    if !address_is_current || comment_time_for_address(state, &address).is_none() {
        state.status = String::from("That comment no longer exists.");
        context.request_repaint();
        return;
    }

    state.pending_comment_playback = Some(PendingCommentPlayback { address });
    maybe_start_pending_comment_playback(state, context);
}

fn maybe_start_pending_comment_playback(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if !library_is_ready(state) {
        return;
    }
    let Some(pending) = state.pending_comment_playback.clone() else {
        return;
    };
    let source = pending.address.source();
    let address_is_current = match source {
        CommentSource::Main => is_current_main_note_address(state, &pending.address),
        CommentSource::Reference => is_current_reference_note_address(state, &pending.address),
    };
    if !address_is_current {
        cancel_pending_comment_playback(state);
        return;
    }
    let blocked = match source {
        CommentSource::Main => {
            reject_main_source_mismatch(state, context)
                || reject_unknown_main_source(state, context)
        }
        CommentSource::Reference => {
            reject_main_source_mismatch(state, context)
                || reject_reference_source_mismatch(state, context)
                || reject_unknown_reference_source(state, context)
        }
    };
    if blocked {
        cancel_pending_comment_playback(state);
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy {
        return;
    }
    let Some(time_millis) = comment_time_for_address(state, &pending.address) else {
        cancel_pending_comment_playback(state);
        state.status = String::from("That comment no longer exists.");
        context.request_repaint();
        return;
    };
    if state.waveform_busy || state.waveform.is_none() {
        return;
    }
    let Some(selected_track_id) = state.library.selected_track_id.as_deref() else {
        return;
    };
    if state.waveform_track_id.as_deref() != Some(selected_track_id) {
        return;
    }
    let has_reference = !reference_source_is_mismatched(state)
        && selected_track(state)
            .and_then(|track| track.reference_path.as_ref())
            .is_some();
    if has_reference
        && (state.reference_waveform_busy
            || state.reference_waveform_track_id.as_deref() != Some(selected_track_id)
            || state.reference_waveform.is_none())
    {
        return;
    }
    let reference_playback_available = !reference_source_is_mismatched(state);
    if state.transport_polling
        || state.transport_waiting_token.is_some()
        || state.transport.has_pending_load()
        || (reference_playback_available
            && (state.reference_transport_polling
                || state.reference_transport_waiting_token.is_some()
                || state
                    .reference_transport
                    .as_ref()
                    .is_some_and(transport::AudioTransport::has_pending_load)))
    {
        return;
    }

    let Some(main_duration_millis) = selected_main_duration(state) else {
        return;
    };
    let reference_duration_millis =
        selected_reference_details(state).map(|(_, duration_millis)| duration_millis);
    let main_position_millis = normalize_position_for_duration(
        match source {
            CommentSource::Main => time_millis,
            CommentSource::Reference => state.transport_position_millis,
        },
        main_duration_millis,
    );
    let reference_position_millis = reference_duration_millis.map_or(
        state.reference_transport_position_millis,
        |duration_millis| {
            normalize_position_for_duration(
                match source {
                    CommentSource::Main => state.reference_transport_position_millis,
                    CommentSource::Reference => time_millis,
                },
                duration_millis,
            )
        },
    );

    match source {
        CommentSource::Main => {
            state.comment_source = CommentSource::Main;
            state.comment_source_explicit = true;
            state.selected_note_id = Some(pending.address.clone());
            state.draft_note = None;
            set_audition_source(state, AuditionSource::Main);
        }
        CommentSource::Reference => {
            state.comment_source = CommentSource::Reference;
            state.comment_source_explicit = true;
            state.selected_reference_note_id = Some(pending.address.clone());
            state.reference_draft_note = None;
            set_audition_source(state, AuditionSource::Reference);
        }
    }

    state.review_cursor_millis = main_position_millis;
    state.transport_position_millis = main_position_millis;
    state.reference_transport_position_millis = reference_position_millis;
    let start_position_millis = match source {
        CommentSource::Main => main_position_millis,
        CommentSource::Reference => reference_position_millis,
    };
    match seek_synchronized_positions(state, main_position_millis, reference_position_millis, true)
    {
        Ok(()) => {
            cancel_pending_comment_playback(state);
            let source_label = match source {
                CommentSource::Main => "comment",
                CommentSource::Reference => "reference comment",
            };
            state.status = format!(
                "Playing {source_label} from {}.",
                format_timestamp(start_position_millis)
            );
        }
        Err(error) if comment_playback_should_wait(&error) => {
            state.status = String::from("Preparing comment playback…");
        }
        Err(error) => {
            cancel_pending_comment_playback(state);
            state.status = error;
        }
    }
    context.request_repaint();
}

fn comment_playback_should_wait(error: &str) -> bool {
    error == transport::CONTROLS_BUSY_ERROR
        || error == "Audio analysis is still building."
        || error == "Audio analysis is still pending."
}

fn cancel_pending_comment_playback(state: &mut AppState) {
    state.pending_comment_playback = None;
}

fn close_stage_menu(state: &mut AppState) {
    state.stage_menu_track_id = None;
    state.stage_menu_anchor = None;
}

fn close_reference_menu(state: &mut AppState) {
    state.reference_menu_track_id = None;
    state.reference_menu_anchor = None;
}

fn close_settings(state: &mut AppState) {
    state.settings_open = false;
}

fn toggle_settings(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if state.settings_open {
        close_settings(state);
    } else {
        close_stage_menu(state);
        close_status_menu(state);
        close_reference_menu(state);
        state.review_filter_menu_open = false;
        state.settings_open = true;
    }
    context.request_repaint();
}

fn library_track_card_height() -> f32 {
    26.0 + (ui::dropdown_trigger_height() * 2.0)
        + (TRACK_CARD_CONTENT_SPACING * 4.0)
        + 18.0
        + REMOVAL_CONFIRMATION_ROW_HEIGHT
        + (TRACK_CARD_CONTENT_INSET * 2.0)
}

const VIRTUAL_LIST_VIEWPORT_ROWS: usize = 8;
const VIRTUAL_LIST_OVERSCAN_ROWS: usize = 4;

fn audition_queue_row_height() -> f32 {
    28.0 + 18.0
        + REMOVAL_CONFIRMATION_ROW_HEIGHT
        + ui::dropdown_trigger_height()
        + (TRACK_CARD_CONTENT_SPACING * 3.0)
        + (TRACK_CARD_CONTENT_INSET * 2.0)
}

fn planner_card_height() -> f32 {
    28.0 + 20.0
        + REMOVAL_CONFIRMATION_ROW_HEIGHT
        + 22.0
        + (ui::dropdown_trigger_height() * 2.0)
        + (TRACK_CARD_CONTENT_SPACING * 5.0)
        + (TRACK_CARD_CONTENT_INSET * 2.0)
}

fn resolved_virtual_list_window(
    current: ui::VirtualListWindow,
    total_items: usize,
    focused_index: Option<usize>,
    follow_focus_in_existing_window: bool,
) -> ui::VirtualListWindow {
    if total_items == 0 {
        return ui::VirtualListWindow::default();
    }
    let has_usable_current_window = current.total_items == total_items
        && current.viewport_len() > 0
        && current.window_len() > 0;
    ui::resolve_virtual_list_window(ui::VirtualListWindowRequest {
        total_items,
        viewport_len: if has_usable_current_window {
            current.viewport_len()
        } else {
            VIRTUAL_LIST_VIEWPORT_ROWS.min(total_items)
        },
        requested_start: if has_usable_current_window {
            current.viewport_start
        } else {
            0
        },
        overscan: if has_usable_current_window {
            current.overscan()
        } else {
            VIRTUAL_LIST_OVERSCAN_ROWS
        },
        focused_index: if follow_focus_in_existing_window || !has_usable_current_window {
            focused_index
        } else {
            None
        },
        previous_start: has_usable_current_window.then_some(current.viewport_start),
        guard_band: 1,
    })
}

fn reset_comments_windows(state: &mut AppState) {
    state.main_comments_window = ui::VirtualListWindow::default();
    state.reference_comments_window = ui::VirtualListWindow::default();
}

fn comments_window(state: &AppState, source: CommentSource) -> ui::VirtualListWindow {
    match source {
        CommentSource::Main => state.main_comments_window,
        CommentSource::Reference => state.reference_comments_window,
    }
}

const fn comments_scroll_viewport_id(source: CommentSource) -> u64 {
    match source {
        CommentSource::Main => MAIN_COMMENTS_SCROLL_VIEWPORT_ID,
        CommentSource::Reference => REFERENCE_COMMENTS_SCROLL_VIEWPORT_ID,
    }
}

fn virtual_row_with_spacing(row: ui::View<Message>, row_height: f32) -> ui::View<Message> {
    ui::column([
        row.height((row_height - TRACK_CARD_LIST_SPACING).max(0.0)),
        ui::spacer().height(TRACK_CARD_LIST_SPACING),
    ])
    .fill_width()
    .height(row_height)
}

fn select_track_internal(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    id: String,
    pending_play: bool,
) {
    if !library_is_ready(state)
        || state.busy
        || !state.library.tracks.iter().any(|track| track.id == id)
    {
        return;
    }
    let in_audition = state.workspace_mode == WorkspaceMode::Audition;
    let entering_review_from_planner = state.workspace_mode == WorkspaceMode::Planner;
    let reveal_id = id.clone();
    let previous_selected_id = state.library.selected_track_id.clone();
    if !in_audition {
        state.workspace_mode = WorkspaceMode::Review;
    }
    if entering_review_from_planner
        && state.review_status_filter.is_some_and(|status| {
            state
                .library
                .tracks
                .iter()
                .any(|track| track.id == id && track.status != status)
        })
    {
        state.review_status_filter = None;
    }
    if in_audition
        && let Some(previous_id) = previous_selected_id.as_deref()
        && previous_id != id
    {
        remove_audition_queue_entry_if_outside_filter(state, previous_id);
    }
    state.library.selected_track_id = Some(id.clone());
    refresh_selected_track_index(state);
    reset_comments_windows(state);
    cancel_pending_comment_playback(state);
    state.loop_selections.clear_all();
    if in_audition {
        if let Some(index) = state
            .audition_queue
            .iter()
            .position(|track_id| track_id == &id)
        {
            state.audition_queue_index = index;
        }
        state.audition_auto_advance = pending_play;
        state.audition_play_token = None;
        state.audition_pending_play_track_id = pending_play.then_some(id);
    } else {
        state.audition_auto_advance = false;
        state.audition_play_token = None;
        state.audition_pending_play_track_id = None;
    }
    close_stage_menu(state);
    close_status_menu(state);
    close_reference_menu(state);
    state.remove_confirmation_track_id = None;
    clear_planner_drag(state);
    if let Some(cancellation) = state.waveform_cancellation.as_ref() {
        cancellation.cancel();
    }
    if let Some(cancellation) = state.reference_waveform_cancellation.as_ref() {
        cancellation.cancel();
    }
    state.waveform = None;
    state.waveform_source_ticket = None;
    state.main_source_mismatch = None;
    state.waveform_track_id = None;
    state.waveform_progress = None;
    state.reference_waveform = None;
    state.reference_waveform_source_ticket = None;
    state.reference_source_mismatch = None;
    state.reference_waveform_track_id = None;
    state.reference_waveform_progress = None;
    state.review_cursor_millis = 0;
    state.draft_note = None;
    state.reference_draft_note = None;
    rollback_persisted_note_drag(state);
    rollback_reference_persisted_note_drag(state);
    state.playhead_drag_active = false;
    state.reference_playhead_drag_active = false;
    state.selected_note_id = None;
    state.hovered_note_id = None;
    state.selected_reference_note_id = None;
    state.hovered_reference_note_id = None;
    state.comment_source = CommentSource::Main;
    state.comment_source_explicit = false;
    reset_transport(state);
    reset_reference_transport(state);
    state.reference_match_enabled = false;
    schedule_library_save(state, context);
    schedule_selected_waveform_decode(state, context);
    schedule_selected_reference_decode(state, context);
    if entering_review_from_planner {
        let tracks = tracks_with_status(&state.library.tracks, state.review_status_filter);
        if let Some(index) = tracks.iter().position(|track| track.id == reveal_id) {
            state.review_library_window = resolved_virtual_list_window(
                state.review_library_window,
                tracks.len(),
                Some(index),
                true,
            );
            let card_height = library_track_card_height();
            context.scroll_into_view(
                LIBRARY_SCROLL_VIEWPORT_ID,
                index as f32 * (card_height + TRACK_CARD_LIST_SPACING),
                card_height,
                LIBRARY_REVEAL_MARGIN,
                LIBRARY_REVEAL_MARGIN,
            );
            context.focus(library_track_title_id(&reveal_id));
        }
    }
}

fn set_workspace_mode(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    mode: WorkspaceMode,
) {
    if !library_is_ready(state) {
        return;
    }
    if state.workspace_mode == mode {
        return;
    }
    state.audition_auto_advance = false;
    state.audition_play_token = None;
    state.audition_pending_play_track_id = None;
    state.workspace_mode = mode;
    if mode == WorkspaceMode::Audition {
        rebuild_audition_queue(state);
        if let Some(track_id) = state.audition_queue.first().cloned() {
            select_track_internal(state, context, track_id, false);
        } else {
            reset_transport(state);
            reset_reference_transport(state);
        }
    }
    close_stage_menu(state);
    close_status_menu(state);
    close_reference_menu(state);
    state.remove_confirmation_track_id = None;
    clear_planner_drag(state);
    context.request_repaint();
}

fn disarm_audition_auto_advance(state: &mut AppState) {
    if state.workspace_mode == WorkspaceMode::Audition {
        state.audition_auto_advance = false;
        state.audition_play_token = None;
        state.audition_pending_play_track_id = None;
    }
}

fn rebuild_audition_queue(state: &mut AppState) {
    let mut queue = state
        .library
        .tracks
        .iter()
        .filter(|track| track.status == state.audition_status_filter)
        .map(|track| track.id.clone())
        .collect::<Vec<_>>();
    let seed = audition_shuffle_seed(
        state.audition_status_filter,
        &queue,
        state.audition_shuffle_round,
    );
    deterministic_shuffle(&mut queue, seed);
    let selected_id = state.library.selected_track_id.as_deref();
    state.audition_queue_index = selected_id
        .and_then(|selected_id| queue.iter().position(|id| id == selected_id))
        .unwrap_or(0)
        .min(queue.len());
    state.audition_queue = queue;
    state.audition_heard.clear();
}

fn shuffle_audition(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    if state.busy || state.workspace_mode != WorkspaceMode::Audition {
        return;
    }
    let previous_queue = state.audition_queue.clone();
    let previous_selected = state.library.selected_track_id.clone();
    state.audition_shuffle_round = state.audition_shuffle_round.wrapping_add(1);
    rebuild_audition_queue(state);
    ensure_audition_shuffle_change(
        &mut state.audition_queue,
        &previous_queue,
        previous_selected.as_deref(),
    );
    state.audition_heard.clear();

    if let Some(track_id) = state.audition_queue.first().cloned() {
        select_track_internal(state, context, track_id, true);
        state.status = format!(
            "New {} audition order ready — loading first track…",
            state.audition_status_filter.label()
        );
    } else {
        state.audition_auto_advance = false;
        state.audition_play_token = None;
        state.audition_pending_play_track_id = None;
        reset_transport(state);
        reset_reference_transport(state);
        state.status = format!("No tracks in {}.", state.audition_status_filter.label());
    }
    context.request_repaint();
}

fn ensure_audition_shuffle_change(
    queue: &mut Vec<String>,
    previous_queue: &[String],
    previous_selected: Option<&str>,
) {
    if queue.len() < 2 {
        return;
    }
    let shuffled = queue.clone();
    let order_changed = |candidate: &[String]| candidate != previous_queue;
    let first_is_new = |candidate: &[String]| {
        previous_selected.is_none_or(|selected| candidate.first().is_none_or(|id| id != selected))
    };

    for rotation in 0..queue.len() {
        let mut candidate = shuffled.clone();
        candidate.rotate_left(rotation);
        if order_changed(&candidate) && first_is_new(&candidate) {
            *queue = candidate;
            return;
        }
    }
    for rotation in 0..queue.len() {
        let mut candidate = shuffled.clone();
        candidate.rotate_left(rotation);
        if order_changed(&candidate) {
            *queue = candidate;
            return;
        }
    }
}

fn reconcile_audition_queue(state: &mut AppState) {
    let old_queue = std::mem::take(&mut state.audition_queue);
    let old_index = state.audition_queue_index;
    let current_id = old_queue.get(old_index).cloned();
    let active_anchor_id = audition_navigation_anchor(state);
    let mut queue = old_queue
        .into_iter()
        .filter(|track_id| {
            state
                .library
                .tracks
                .iter()
                .find(|track| &track.id == track_id)
                .is_some_and(|track| {
                    track.status == state.audition_status_filter
                        || active_anchor_id == Some(track_id.as_str())
                })
        })
        .collect::<Vec<_>>();
    for track in state
        .library
        .tracks
        .iter()
        .filter(|track| track.status == state.audition_status_filter)
    {
        if !queue.iter().any(|track_id| track_id == &track.id) {
            queue.push(track.id.clone());
        }
    }
    state.audition_queue_index = current_id
        .and_then(|current_id| queue.iter().position(|id| id == &current_id))
        .unwrap_or(old_index.min(queue.len()));
    state.audition_queue = queue;
    state.audition_heard.retain(|heard_id| {
        state
            .library
            .tracks
            .iter()
            .any(|track| &track.id == heard_id)
    });
}

fn audition_navigation_anchor(state: &AppState) -> Option<&str> {
    if state.workspace_mode != WorkspaceMode::Audition
        || state.audition_pending_play_track_id.is_some()
        || !(state.transport_playing
            || state.transport_polling
            || state.transport_waiting_token.is_some()
            || state.reference_transport_playing
            || state.reference_transport_polling
            || state.reference_transport_waiting_token.is_some())
    {
        return None;
    }
    state.library.selected_track_id.as_deref()
}

fn remove_audition_queue_entry_if_outside_filter(state: &mut AppState, track_id: &str) {
    let matches_filter = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == track_id)
        .is_some_and(|track| track.status == state.audition_status_filter);
    if matches_filter {
        return;
    }
    let Some(position) = state.audition_queue.iter().position(|id| id == track_id) else {
        return;
    };
    state.audition_queue.remove(position);
    if position < state.audition_queue_index {
        state.audition_queue_index = state.audition_queue_index.saturating_sub(1);
    }
    if state.audition_queue.is_empty() {
        state.audition_queue_index = 0;
    } else {
        state.audition_queue_index = state.audition_queue_index.min(state.audition_queue.len());
    }
}

fn sync_audition_queue_after_status_change(state: &mut AppState, track_id: &str) {
    let matches_filter = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == track_id)
        .is_some_and(|track| track.status == state.audition_status_filter);
    let is_navigation_anchor = audition_navigation_anchor(state) == Some(track_id);
    let Some(_) = state.audition_queue.iter().position(|id| id == track_id) else {
        if matches_filter {
            state.audition_queue.push(track_id.to_owned());
        }
        return;
    };
    if !matches_filter && !is_navigation_anchor {
        remove_audition_queue_entry_if_outside_filter(state, track_id);
    }
}

fn audition_shuffle_seed(status: storage::TrackStatus, track_ids: &[String], round: u64) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64 ^ round;
    for byte in status.label().bytes().chain([0]) {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    for id in track_ids {
        for byte in id.bytes().chain([0]) {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    hash
}

fn deterministic_shuffle(items: &mut [String], mut seed: u64) {
    for index in (1..items.len()).rev() {
        seed ^= seed >> 12;
        seed ^= seed << 25;
        seed ^= seed >> 27;
        seed = seed.wrapping_mul(0x2545f4914f6cdd1d);
        items.swap(index, (seed as usize) % (index + 1));
    }
}

fn next_audition_track_index(state: &AppState) -> Option<usize> {
    let selected_id = state.library.selected_track_id.as_deref();
    let mut index = state.audition_queue_index;
    if state.audition_queue.get(index).map(String::as_str) == selected_id {
        index += 1;
    }
    while let Some(track_id) = state.audition_queue.get(index) {
        if !state
            .audition_heard
            .iter()
            .any(|heard_id| heard_id == track_id)
            && state
                .library
                .tracks
                .iter()
                .find(|track| track.id == *track_id)
                .is_some_and(|track| track.status == state.audition_status_filter)
        {
            return Some(index);
        }
        index += 1;
    }
    None
}

fn advance_audition(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if let Some(current_id) = state.library.selected_track_id.as_ref()
        && !state
            .audition_heard
            .iter()
            .any(|heard_id| heard_id == current_id)
    {
        state.audition_heard.push(current_id.clone());
    }
    let Some(next_index) = next_audition_track_index(state) else {
        state.audition_auto_advance = false;
        state.audition_play_token = None;
        state.audition_pending_play_track_id = None;
        state.status = String::from("Audition complete.");
        return;
    };
    let Some(track_id) = state.audition_queue.get(next_index).cloned() else {
        return;
    };
    let title = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == track_id)
        .map_or_else(|| track_id.clone(), |track| track.title.clone());
    select_track_internal(state, context, track_id, true);
    state.status = format!("Loading next audition track: {title}…");
}

fn maybe_start_pending_audition(state: &mut AppState, context: &mut ui::UiUpdateContext<Message>) {
    if !library_is_ready(state) {
        return;
    }
    if let Some(error) = paired_playback_cleanup_error(state) {
        state.status = error.to_owned();
        context.request_repaint();
        return;
    }
    let Some(track_id) = state.audition_pending_play_track_id.clone() else {
        return;
    };
    if state.workspace_mode != WorkspaceMode::Audition
        || state.busy
        || state.waveform_busy
        || state.transport_polling
        || state.transport_waiting_token.is_some()
        || state.transport.has_pending_load()
        || (state.reference_waveform_busy && !reference_source_is_mismatched(state))
        || state.library.selected_track_id.as_deref() != Some(track_id.as_str())
        || state.waveform_track_id.as_deref() != Some(track_id.as_str())
        || state.waveform.is_none()
    {
        return;
    }
    if !state.transport.has_command_capacity(1) {
        return;
    }
    if selected_reference_details(state).is_some() {
        let reference_transport = state
            .reference_transport
            .get_or_insert_with(transport::AudioTransport::spawn);
        let required_slots = if state.reference_transport_loaded {
            2
        } else {
            3
        };
        if reference_transport.has_pending_load()
            || !reference_transport.has_command_capacity(required_slots)
        {
            return;
        }
    }
    state.audition_pending_play_track_id = None;
    toggle_playback(state, context);
}

fn close_status_menu(state: &mut AppState) {
    state.status_menu_track_id = None;
    state.status_menu_host = None;
}

fn toggle_status_menu(
    state: &mut AppState,
    track_id: String,
    host: StatusMenuHost,
    context: &mut ui::UiUpdateContext<Message>,
) {
    if !state.busy
        && state
            .library
            .tracks
            .iter()
            .any(|track| track.id == track_id)
    {
        if state.status_menu_track_id.as_deref() == Some(track_id.as_str())
            && state.status_menu_host == Some(host)
        {
            close_status_menu(state);
        } else {
            close_stage_menu(state);
            state.status_menu_track_id = Some(track_id);
            state.status_menu_host = Some(host);
        }
        context.request_repaint();
    }
}

fn clear_planner_drag(state: &mut AppState) {
    state.planner_drag_source_track_id = None;
    state.planner_drag_target = None;
    state.planner_drag_pointer = None;
}

fn rollback_persisted_note_drag(state: &mut AppState) {
    let Some(drag) = state.persisted_note_drag.take() else {
        return;
    };
    let NoteOwner::MainTrack(track_id) = &drag.address.owner else {
        return;
    };

    let mut note_restored = false;
    if let Some(track) = state
        .library
        .tracks
        .iter_mut()
        .find(|track| track.id == *track_id)
        && let Some(note) = track
            .notes
            .iter_mut()
            .find(|note| note.id == drag.address.note_id)
    {
        note.time_millis = drag.original_time_millis;
        track.notes.sort_by_key(|note| note.time_millis);
        note_restored = true;
    }
    if note_restored && state.library.selected_track_id.as_deref() == Some(track_id.as_str()) {
        state.review_cursor_millis = drag.original_time_millis;
        state.transport_position_millis = drag.original_time_millis;
    }
    if let Some(draft) = state
        .draft_note
        .as_mut()
        .filter(|draft| draft.address().as_ref() == Some(&drag.address))
    {
        draft.time_millis = drag.original_time_millis;
    }
}

fn rollback_reference_persisted_note_drag(state: &mut AppState) {
    let Some(drag) = state.reference_persisted_note_drag.take() else {
        return;
    };
    let NoteOwner::ReferenceTrack(reference_path) = &drag.address.owner else {
        return;
    };

    let mut note_restored = false;
    if let Some(reference) = state
        .library
        .reference_tracks
        .iter_mut()
        .find(|reference| reference.path == *reference_path)
        && let Some(note) = reference
            .notes
            .iter_mut()
            .find(|note| note.id == drag.address.note_id)
    {
        note.time_millis = drag.original_time_millis;
        reference.notes.sort_by_key(|note| note.time_millis);
        note_restored = true;
    }
    let selected_reference_matches = selected_track(state)
        .and_then(|track| track.reference_path.as_ref())
        .is_some_and(|path| path == reference_path);
    if note_restored && selected_reference_matches {
        state.reference_transport_position_millis = drag.original_time_millis;
    }
    if let Some(draft) = state
        .reference_draft_note
        .as_mut()
        .filter(|draft| draft.address().as_ref() == Some(&drag.address))
    {
        draft.time_millis = drag.original_time_millis;
    }
}

fn drag_message_position(message: ui::DragHandleMessage) -> Option<Point> {
    Some(match message {
        ui::DragHandleMessage::Started { position, .. }
        | ui::DragHandleMessage::Moved { position, .. }
        | ui::DragHandleMessage::Ended { position, .. }
        | ui::DragHandleMessage::DoubleActivate { position, .. }
        | ui::DragHandleMessage::Cancelled { position } => position,
    })
}

fn update_live_spectrogram_resize(state: &mut AppState, message: ui::DragHandleMessage) {
    match message {
        ui::DragHandleMessage::Started { origin, .. } => {
            state.live_spectrogram_resize = Some(LiveSpectrogramResize {
                start_height: spectrogram::clamp_height(state.live_spectrogram_height),
                start_pointer_y: origin.y,
            });
        }
        ui::DragHandleMessage::Moved { position, .. } => {
            if let Some(resize) = state.live_spectrogram_resize {
                state.live_spectrogram_height = spectrogram::clamp_height(
                    resize.start_height + position.y - resize.start_pointer_y,
                );
            }
        }
        ui::DragHandleMessage::Ended { .. } => {
            state.live_spectrogram_height =
                spectrogram::clamp_height(state.live_spectrogram_height);
            state.live_spectrogram_resize = None;
        }
        ui::DragHandleMessage::Cancelled { .. } => {
            if let Some(resize) = state.live_spectrogram_resize.take() {
                state.live_spectrogram_height = resize.start_height;
            }
        }
        ui::DragHandleMessage::DoubleActivate { .. } => {
            state.live_spectrogram_resize = None;
        }
    }
}

