fn favorite_toggle(track: &storage::Track, selected: bool, key: String) -> ui::View<Message> {
    let marker = if track.favorite { "★" } else { "☆" };
    let control = ui::button(marker)
        .subtle()
        .active(track.favorite)
        .selected(selected)
        .message(Message::ToggleFavorite(track.id.clone()))
        .key(key)
        .tooltip(if track.favorite {
            "Remove favorite"
        } else {
            "Mark favorite"
        })
        .size(FAVORITE_CONTROL_WIDTH, 24.0);
    ui::stack([control, favorite_marker(track.favorite)]).size(FAVORITE_CONTROL_WIDTH, 24.0)
}

fn replace_toggle(track: &storage::Track, key: String) -> ui::View<Message> {
    ui::button("↻")
        .subtle()
        .message(Message::ReplacePressed(track.id.clone()))
        .key(key)
        .tooltip("Replace track")
        .size(28.0, 24.0)
}

fn stage_dropdown(track: &storage::Track, open: bool, _selected: bool) -> ui::View<Message> {
    let stage_id = track.id.clone();
    let label = track.stage.label().to_owned();
    ui::dropdown_trigger(label, open)
        .toggle_message(Message::ToggleStageMenu(stage_id.clone()))
        .build()
        .fill_width()
        .height(24.0)
        .pointer_target(
            ui::pointer_target(true)
                .pointer_move(false)
                .pointer_press(true)
                .pointer_release(false)
                .pointer_drop(false)
                .wheel(false)
                .filter_map(move |message| match message {
                    ui::PointerShieldMessage::PointerPress { position, .. } => {
                        Some(Message::ToggleStageMenuAt {
                            track_id: stage_id.clone(),
                            position,
                        })
                    }
                    _ => None,
                }),
        )
        .key(format!("stage-dropdown-{}", track.id))
}

fn stage_menu_popover(track: &storage::Track, anchor: Point) -> ui::View<Message> {
    let options = stage_dropdown_options(track);
    let size = Vector2::new(STAGE_MENU_WIDTH, ui::dropdown_menu_height(options.len()));
    anchored_popover_from_parts(AnchoredPopoverParts::below(
        ui::dropdown_menu(options),
        ui::AnchoredPopoverAnchor::pointer(anchor),
        size,
    ))
}

fn reference_assignment_counts(library: &storage::Library) -> HashMap<&Path, usize> {
    let mut counts = HashMap::with_capacity(library.tracks.len());
    for track in &library.tracks {
        if let Some(path) = track.reference_path.as_deref() {
            *counts.entry(path).or_default() += 1;
        }
    }
    counts
}

fn settings_reference_row(
    reference: &storage::ReferenceTrack,
    assignment_count: usize,
    active: bool,
) -> ui::View<Message> {
    let path = reference.path.as_path();
    let name = reference_track_name(path);
    let assignment_label = if active {
        format!("{} assigned · ACTIVE", assignment_count,)
    } else {
        format!("{} assigned", assignment_count)
    };
    let remove_path = path.to_path_buf();
    let row_key = format!("settings-reference-{}", path.display());
    ui::list_row(
        row_key,
        [
            ui::column([
                ui::text(name)
                    .truncate()
                    .height(SETTINGS_REFERENCE_ROW_TITLE_HEIGHT)
                    .fill_width(),
                ui::text(assignment_label)
                    .truncate()
                    .height(SETTINGS_REFERENCE_ROW_METADATA_HEIGHT)
                    .fill_width()
                    .subtle(),
            ])
            .spacing(SETTINGS_REFERENCE_ROW_TEXT_SPACING)
            .fill_width()
            .height(SETTINGS_REFERENCE_ROW_TEXT_HEIGHT),
            ui::close_button()
                .subtle()
                .message(Message::RemoveReferenceTrack(remove_path))
                .key(format!("settings-remove-reference-{}", path.display()))
                .tooltip("Remove reference track")
                .size(
                    SETTINGS_REFERENCE_REMOVE_BUTTON_SIZE,
                    SETTINGS_REFERENCE_REMOVE_BUTTON_SIZE,
                ),
        ],
    )
    .fill_width()
    .height(SETTINGS_REFERENCE_ROW_HEIGHT)
}

fn reference_settings_window_view(state: &AppState) -> ui::View<Message> {
    let reference_count = state.library.reference_tracks.len();
    let references = if reference_count == 0 {
        ui::column([ui::text("No reference tracks cataloged yet.")
            .wrap()
            .height(36.0)
            .fill_width()
            .subtle()])
        .without_chrome()
        .fill_width()
        .fill_height()
    } else {
        let selected_reference_path =
            selected_track(state).and_then(|track| track.reference_path.as_deref());
        let assignment_counts = reference_assignment_counts(&state.library);
        let window = resolved_virtual_list_window(
            state.reference_settings_window,
            reference_count,
            None,
            false,
        );
        ui::virtual_list_windowed(|index| {
            let reference: &storage::ReferenceTrack = &state.library.reference_tracks[index];
            let assignment_count = assignment_counts
                .get(reference.path.as_path())
                .copied()
                .unwrap_or_default();
            let active = selected_reference_path == Some(reference.path.as_path());
            settings_reference_row(reference, assignment_count, active)
        })
        .window(window)
        .row_height(SETTINGS_REFERENCE_ROW_HEIGHT)
        .overscan_px(SETTINGS_REFERENCE_ROW_HEIGHT * VIRTUAL_LIST_OVERSCAN_ROWS as f32)
        .on_window_changed(Message::ReferenceSettingsWindowChanged)
        .retain_materialized_window()
        .view()
        .without_chrome()
        .id(REFERENCE_SETTINGS_SCROLL_VIEWPORT_ID)
        .fill_width()
        .fill_height()
    };
    ui::column([
        ui::text("REFERENCE TRACKS")
            .style(ui::WidgetStyle::strong(ui::WidgetTone::Neutral))
            .height(28.0)
            .fill_width(),
        references,
        ui::button("Add reference tracks")
            .primary()
            .message(Message::AddReferenceTracksPressed)
            .key("settings-add-reference-tracks")
            .fill_width()
            .height(34.0),
    ])
    .key("reference-settings-window")
    .style(ui::WidgetStyle::strong(ui::WidgetTone::Neutral))
    .padding(REFERENCE_SETTINGS_WINDOW_PADDING)
    .spacing(12.0)
    .fill()
}

#[allow(clippy::arc_with_non_send_sync)]
fn reference_settings_auxiliary_windows(state: &mut AppState) -> Vec<ui::AuxiliaryWindow<Message>> {
    if !state.settings_open {
        return Vec::new();
    }
    let surface = reference_settings_window_view(state).into_surface();
    vec![
        ui::AuxiliaryWindow::utility(
            "reference-settings",
            "Reference Tracks",
            REFERENCE_SETTINGS_WINDOW_WIDTH,
            REFERENCE_SETTINGS_WINDOW_HEIGHT,
            Arc::new(surface),
        )
        .on_close(Message::CloseSettings)
        .cache_on_close(),
    ]
}

