fn current_live_frame_for_source(
    state: &AppState,
    track_id: &str,
    source: AuditionSource,
) -> Option<Arc<transport::LiveSpectrogramFrame>> {
    match source {
        AuditionSource::Main => {
            if state.waveform_track_id.as_deref() != Some(track_id) {
                return None;
            }
            let live_state = state.transport.live_frame_state();
            let frame = state.live_spectrogram.as_ref()?;
            (live_frame_matches_current_session(frame, state.transport_generation, live_state)
                && frame.revision == state.live_spectrogram_revision)
                .then(|| Arc::clone(frame))
        }
        AuditionSource::Reference => {
            if state.reference_waveform_track_id.as_deref() != Some(track_id) {
                return None;
            }
            let reference_transport = state.reference_transport.as_ref()?;
            let live_state = reference_transport.live_frame_state();
            let frame = state.reference_live_spectrogram.as_ref()?;
            (live_frame_matches_current_session(
                frame,
                state.reference_transport_generation,
                live_state,
            ) && frame.revision == state.reference_live_spectrogram_revision)
                .then(|| Arc::clone(frame))
        }
    }
}

fn review_spectrogram_source(state: &AppState) -> AuditionSource {
    if state.reference_only_playback {
        AuditionSource::Reference
    } else {
        match (state.transport_playing, state.reference_transport_playing) {
            (true, false) => AuditionSource::Main,
            (false, true) => AuditionSource::Reference,
            (true, true) | (false, false) => state.audition_source,
        }
    }
}

fn live_spectrogram_display_sample_rate(
    state: &AppState,
    track_id: &str,
    source: AuditionSource,
    frame: Option<&transport::LiveSpectrogramFrame>,
) -> u32 {
    if let Some(frame) = frame {
        return frame.sample_rate;
    }

    // Before the analyzer publishes its first frame, match the selected
    // source's decoded waveform metadata so the empty shell uses the source
    // Nyquist range. Fall back to 48 kHz only when that metadata is unavailable.
    let sample_rate = match source {
        AuditionSource::Main => state
            .waveform_track_id
            .as_deref()
            .filter(|id| *id == track_id)
            .and(state.waveform.as_ref())
            .map(|waveform| waveform.sample_rate),
        AuditionSource::Reference => state
            .reference_waveform_track_id
            .as_deref()
            .filter(|id| *id == track_id)
            .and(state.reference_waveform.as_ref())
            .map(|waveform| waveform.sample_rate),
    };
    sample_rate
        .filter(|sample_rate| *sample_rate > 0)
        .unwrap_or(DEFAULT_LIVE_SPECTROGRAM_DISPLAY_SAMPLE_RATE)
}

fn live_spectrogram_frame_for_review(
    state: &AppState,
    track: &storage::Track,
) -> (AuditionSource, Option<Arc<transport::LiveSpectrogramFrame>>) {
    let source = review_spectrogram_source(state);
    let frame = current_live_frame_for_source(state, &track.id, source);
    (source, frame)
}

fn live_spectrogram_section(state: &AppState, track: &storage::Track) -> ui::View<Message> {
    let (source, frame) = live_spectrogram_frame_for_review(state, track);
    let label = frame.as_ref().map_or_else(
        || {
            if state.transport_playing
                || state.reference_transport_playing
                || state.transport.live_analysis_pending()
                || state
                    .reference_transport
                    .as_ref()
                    .is_some_and(transport::AudioTransport::live_analysis_pending)
            {
                String::from("LIVE SPECTROGRAM · BUILDING")
            } else {
                String::from("LIVE SPECTROGRAM · WAITING FOR PLAYBACK")
            }
        },
        |frame| {
            format!(
                "LIVE SPECTROGRAM · {} · {} BANDS",
                match source {
                    AuditionSource::Main => "MAIN",
                    AuditionSource::Reference => "REFERENCE",
                },
                frame.values.len() / frame.row_count.max(1),
            )
        },
    );
    let body_height = spectrogram::clamp_height(state.live_spectrogram_height);
    let display_sample_rate =
        live_spectrogram_display_sample_rate(state, &track.id, source, frame.as_deref());
    let body = spectrogram::view::<Message>(
        frame,
        display_sample_rate,
        state.live_spectrogram_mode,
        body_height,
        state.live_spectrogram_history_scale,
    )
    .id(LIVE_SPECTROGRAM_BODY_ID);
    let resize_handle = ui::panel_section_resize_header(
        "live-spectrogram-resize",
        spectrogram::RESIZE_HANDLE_HEIGHT,
        Message::ResizeLiveSpectrogram,
    )
    .id(LIVE_SPECTROGRAM_RESIZE_HANDLE_ID)
    .tooltip("Drag to resize the live spectrogram panel");
    let spectrum_selected = state.live_spectrogram_mode == LiveSpectrogramMode::Spectrum;
    let mode_toggle = ui::button("SPECTRUM")
        .subtle()
        .active(spectrum_selected)
        .selected(spectrum_selected)
        .message(Message::ToggleLiveSpectrogramMode)
        .key("live-spectrogram-mode-toggle")
        .tooltip("Toggle live waterfall / spectrum view")
        .width(82.0)
        .height(LIVE_SPECTROGRAM_HEADER_HEIGHT);
    let history_scale_slider = ui::slider(spectrogram::history_scale_to_normalized(
        state.live_spectrogram_history_scale,
    ))
    .subtle()
    .compact()
    .track_height(4.0)
    .message(|normalized| {
        Message::SetLiveSpectrogramHistoryScale(spectrogram::history_scale_from_normalized(
            normalized,
        ))
    })
    .key("Waterfall history scale")
    .tooltip("Waterfall history scale")
    .width(92.0)
    .height(LIVE_SPECTROGRAM_HEADER_HEIGHT);
    let header = ui::row([
        ui::spacer().fill_width(),
        ui::text(label)
            .style(ui::WidgetStyle::strong(ui::WidgetTone::Neutral))
            .height(LIVE_SPECTROGRAM_HEADER_HEIGHT)
            .align_text(ui::TextAlign::Right),
        history_scale_slider,
        mode_toggle,
    ])
    .spacing(8.0)
    .fill_width()
    .height(LIVE_SPECTROGRAM_HEADER_HEIGHT);
    ui::column([body, resize_handle, header])
        .spacing(LIVE_SPECTROGRAM_SECTION_SPACING)
        .fill_width()
        .height(
            body_height
                + spectrogram::RESIZE_HANDLE_HEIGHT
                + LIVE_SPECTROGRAM_SECTION_SPACING * 2.0
                + LIVE_SPECTROGRAM_HEADER_HEIGHT,
        )
}

fn review_panel(state: &AppState) -> ui::View<Message> {
    let Some(track) = selected_track(state) else {
        let content = ui::column([
            ui::text("Your review desk").height(30.0).fill_width(),
            ui::text("Import a track to begin reviewing.")
                .height(28.0)
                .fill_width(),
            ui::spacer().fill(),
        ])
        .padding(WORKSPACE_PANEL_PADDING)
        .spacing(WORKSPACE_PANEL_SPACING)
        .fill();
        return workspace_surface(content);
    };

    let note_ratios = state
        .waveform
        .as_ref()
        .filter(|_| {
            !state.waveform_busy
                && state.waveform_track_id.as_deref() == Some(track.id.as_str())
                && track.source_provenance().verified_proof().is_some()
        })
        .map(|waveform| {
            track
                .notes
                .iter()
                .filter_map(|note| {
                    waveform::ratio_for_millis(note.time_millis, waveform.duration_millis)
                        .map(|ratio| (ratio, note.done))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let main_note_addresses = state
        .waveform
        .as_ref()
        .filter(|_| {
            !state.waveform_busy
                && state.waveform_track_id.as_deref() == Some(track.id.as_str())
                && track.source_provenance().verified_proof().is_some()
        })
        .map(|waveform| {
            track
                .notes
                .iter()
                .filter_map(|note| {
                    waveform::ratio_for_millis(note.time_millis, waveform.duration_millis)
                        .map(|_| NoteAddress::main(track.id.clone(), note.id.clone()))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let hovered_note_ratio = note_ratio_for_address(state, track, state.hovered_note_id.as_ref());
    let selected_note_ratio = note_ratio_for_address(state, track, state.selected_note_id.as_ref());
    let cursor_ratio = state
        .waveform
        .as_ref()
        .filter(|_| {
            !state.waveform_busy
                && !state.transport_playing
                && state.waveform_track_id.as_deref() == Some(track.id.as_str())
        })
        .and_then(|waveform| {
            waveform::ratio_for_millis(state.review_cursor_millis, waveform.duration_millis)
        });
    let draft_ratio = state
        .draft_note
        .as_ref()
        .filter(|draft| draft.note_id.is_none() && main_annotations_available(state))
        .and_then(|draft| {
            state
                .waveform
                .as_ref()
                .filter(|_| {
                    !state.waveform_busy
                        && state.waveform_track_id.as_deref() == Some(track.id.as_str())
                })
                .and_then(|waveform| {
                    waveform::ratio_for_millis(draft.time_millis, waveform.duration_millis)
                })
        });
    let loop_selection = state
        .loop_selections
        .get(AuditionSource::Main)
        .map(|selection| (selection.start_ratio, selection.end_ratio));
    let waveform_view = if let Some(waveform) = state
        .waveform
        .as_ref()
        .filter(|_| state.waveform_track_id.as_deref() == Some(track.id.as_str()))
    {
        let main_note_addresses_for_drag = main_note_addresses.clone();
        waveform::view_with_source_progress_and_loop(
            waveform::WaveformSource::Main,
            state.waveform_generation,
            Arc::new(waveform.clone()),
            cursor_ratio,
            draft_ratio,
            note_ratios,
            hovered_note_ratio,
            selected_note_ratio,
            loop_selection,
            state
                .waveform_busy
                .then_some(state.waveform_progress)
                .flatten(),
            move |interaction| match interaction {
                waveform::WaveformInteraction::LoopDragStarted { ratio } => {
                    Message::WaveformLoopDragStarted { ratio }
                }
                waveform::WaveformInteraction::LoopDragEnded {
                    start_ratio,
                    end_ratio,
                } => Message::WaveformLoopDragEnded {
                    start_ratio,
                    end_ratio,
                },
                waveform::WaveformInteraction::LoopDragCancelled => {
                    Message::WaveformLoopDragCancelled
                }
                waveform::WaveformInteraction::Clicked { ratio, lower } => {
                    Message::WaveformClicked { ratio, lower }
                }
                waveform::WaveformInteraction::PlayheadDragStarted { ratio } => {
                    Message::WaveformPlayheadDragStarted { ratio }
                }
                waveform::WaveformInteraction::PlayheadDragEnded { ratio } => {
                    Message::WaveformPlayheadDragEnded { ratio }
                }
                waveform::WaveformInteraction::PlayheadDragCancelled => {
                    Message::WaveformPlayheadDragCancelled
                }
                waveform::WaveformInteraction::CommentDragStarted { ratio, note_index } => {
                    Message::CommentDragStarted {
                        ratio,
                        address: note_index
                            .and_then(|index| main_note_addresses_for_drag.get(index).cloned()),
                    }
                }
                waveform::WaveformInteraction::CommentDragEnded { ratio } => {
                    Message::CommentDragEnded { ratio }
                }
                waveform::WaveformInteraction::CommentDragCancelled => {
                    Message::CommentDragCancelled
                }
            },
        )
        .fill_width()
        .height(WAVEFORM_HEIGHT)
    } else {
        ui::column([
            ui::text(if state.waveform_busy {
                "Analyzing the real audio file…"
            } else {
                "Waveform unavailable for this file."
            })
            .height(28.0)
            .fill_width(),
            ui::text(
                "The imported path remains external to the native library; if it moved, re-import it.",
            )
                .wrap()
                .height(42.0)
                .fill_width()
                .subtle(),
        ])
        .padding(12.0)
        .spacing(8.0)
        .fill_width()
        .height(WAVEFORM_HEIGHT)
    };
    let meter_lufs = current_lufs_meter_value(state, &track.id);
    let waveform_with_meter = ui::row([
        chrome::lufs_meter(meter_lufs, state.waveform_busy)
            .width(LUFS_METER_WIDTH)
            .height(WAVEFORM_HEIGHT),
        waveform_view,
    ])
    .spacing(8.0)
    .fill_width()
    .height(WAVEFORM_HEIGHT);
    let main_waveform_header = ui::row([
        ui::spacer().fill_width(),
        ui::text("MAIN WAVEFORM")
            .style(ui::WidgetStyle::strong(ui::WidgetTone::Neutral))
            .height(MAIN_WAVEFORM_HEADER_HEIGHT)
            .width(132.0)
            .align_text(ui::TextAlign::Right),
        ui::text(track.original_name.clone())
            .truncate()
            .height(MAIN_WAVEFORM_HEADER_HEIGHT)
            .width(300.0)
            .align_text(ui::TextAlign::Right)
            .subtle(),
    ])
    .spacing(8.0)
    .fill_width()
    .height(MAIN_WAVEFORM_HEADER_HEIGHT);
    let main_section_height =
        WAVEFORM_HEIGHT + REFERENCE_SECTION_SPACING + MAIN_WAVEFORM_HEADER_HEIGHT;
    let main_waveform_section = ui::column([waveform_with_meter, main_waveform_header])
        .spacing(REFERENCE_SECTION_SPACING)
        .fill_width()
        .height(main_section_height);
    let reference_height = reference_section_height(state, track);
    let waveform_pair_height = main_section_height + WAVEFORM_SECTION_SPACING + reference_height;
    let reference_body_spacing =
        REFERENCE_SECTION_SPACING + MAIN_WAVEFORM_HEADER_HEIGHT + WAVEFORM_SECTION_SPACING;
    let reference_label_area_height = REFERENCE_SECTION_SPACING + REFERENCE_HEADER_HEIGHT;
    let waveform_pair = ui::column([
        main_waveform_section,
        reference_waveform_section(state, track),
    ])
    .spacing(WAVEFORM_SECTION_SPACING)
    .fill_width()
    .height(waveform_pair_height);
    let main_choice = audition_source_choice(
        "MAIN",
        AuditionSource::Main,
        state.audition_source == AuditionSource::Main,
        source_button_shows_stop(state, AuditionSource::Main),
    );
    let audition_source_control = if track.reference_path.is_some() {
        let reference_choice = audition_source_choice(
            "REF",
            AuditionSource::Reference,
            state.audition_source == AuditionSource::Reference,
            source_button_shows_stop(state, AuditionSource::Reference),
        );
        ui::column([
            ui::column([ui::spacer().fill(), main_choice, ui::spacer().fill()])
                .height(WAVEFORM_HEIGHT),
            ui::spacer().height(reference_body_spacing),
            ui::column([ui::spacer().fill(), reference_choice, ui::spacer().fill()])
                .height(REFERENCE_WAVEFORM_HEIGHT),
            ui::spacer().height(reference_label_area_height),
        ])
        .spacing(0.0)
        .width(AUDITION_SOURCE_SELECTOR_WIDTH)
        .height(waveform_pair_height)
    } else {
        ui::column([
            ui::column([ui::spacer().fill(), main_choice, ui::spacer().fill()])
                .height(WAVEFORM_HEIGHT),
            ui::spacer().fill(),
        ])
        .spacing(0.0)
        .width(AUDITION_SOURCE_SELECTOR_WIDTH)
        .height(waveform_pair_height)
    };
    let waveform_with_source = ui::row([audition_source_control, waveform_pair])
        .spacing(8.0)
        .fill_width()
        .height(waveform_pair_height);

    let content = ui::column([
        live_spectrogram_section(state, track),
        waveform_with_source,
        comments_panel(state, track),
    ])
    .padding(WORKSPACE_PANEL_PADDING)
    .spacing(WORKSPACE_PANEL_SPACING)
    .fill();
    workspace_surface(content)
}

fn reference_dropdown_paths(state: &AppState, track: &storage::Track) -> Vec<PathBuf> {
    let mut paths = state
        .library
        .reference_tracks
        .iter()
        .map(|reference| reference.path.clone())
        .collect::<Vec<_>>();
    if let Some(path) = track.reference_path.as_ref()
        && !paths.iter().any(|candidate| candidate == path)
    {
        paths.push(path.clone());
    }
    paths
}

fn review_reference_controls(state: &AppState, track: &storage::Track) -> ui::View<Message> {
    let menu_open = reference_menu_is_open(state, track);
    let selector_label = track
        .reference_path
        .as_ref()
        .map_or("Choose reference".to_owned(), |path| {
            reference_track_name(path)
        });
    let reference_id = track.id.clone();
    let selector = ui::dropdown_trigger(selector_label, menu_open)
        .toggle_message(Message::ToggleReferenceMenu(reference_id.clone()))
        .build()
        .key(format!("reference-dropdown-{}", track.id))
        .width(REFERENCE_MENU_WIDTH)
        .height(26.0)
        .pointer_target(
            ui::pointer_target(true)
                .pointer_move(false)
                .pointer_press(true)
                .pointer_release(false)
                .pointer_drop(false)
                .wheel(false)
                .filter_map(move |message| match message {
                    ui::PointerShieldMessage::PointerPress { position, .. } => {
                        Some(Message::ToggleReferenceMenuAt {
                            track_id: reference_id.clone(),
                            position,
                        })
                    }
                    _ => None,
                }),
        );
    let has_reference = track.reference_path.is_some();
    let action = ui::button(if has_reference {
        "Replace reference"
    } else {
        "Import reference"
    })
    .subtle()
    .message(Message::ReferencePressed(track.id.clone()))
    .width(142.0)
    .height(26.0);
    let match_control = if state.reference_waveform.is_some() && !state.reference_waveform_busy {
        ui::button("MATCH REF")
            .active(state.reference_match_enabled)
            .message(Message::ToggleReferenceMatch)
            .width(112.0)
            .height(26.0)
    } else {
        ui::button("MATCH REF")
            .subtle()
            .message(Message::ToggleReferenceMatch)
            .width(112.0)
            .height(26.0)
    };
    ui::row([
        ui::text("REF")
            .style(ui::WidgetStyle::strong(ui::WidgetTone::Accent))
            .width(28.0)
            .height(26.0),
        selector,
        match_control,
        action,
    ])
    .spacing(8.0)
    .height(26.0)
}

fn review_global_controls(state: &AppState, track: &storage::Track) -> ui::View<Message> {
    ui::row([
        review_reference_controls(state, track),
        ui::icon_button(review_transport_icon(&REVIEW_VOLUME_ICON, false))
            .bare()
            .focus(ui::FocusBehavior::None)
            .passive::<Message>()
            .key("review-transport-volume")
            .tooltip(format!(
                "Volume {:02}",
                (state.audition_volume * 100.0).round() as u32
            ))
            .size(20.0, 26.0),
        ui::slider(state.audition_volume)
            .primary()
            .compact()
            .track_height(5.0)
            .track_border()
            .on_edit(Message::AuditionVolumeChanged)
            .key("native-audition-volume")
            .height(26.0)
            .width(180.0),
    ])
    .spacing(6.0)
    .height(26.0)
}

fn reference_dropdown_options(
    state: &AppState,
    track: &storage::Track,
) -> Vec<ui::DropdownOption<Message>> {
    let selected_path = track.reference_path.as_ref();
    let track_id = track.id.clone();
    reference_dropdown_paths(state, track)
        .into_iter()
        .map(|path| {
            let selected = selected_path == Some(&path);
            ui::DropdownOption::new(
                reference_track_name(&path),
                selected,
                Message::SetReferenceTrack {
                    track_id: track_id.clone(),
                    path,
                },
            )
        })
        .collect()
}

fn reference_menu_is_open(state: &AppState, track: &storage::Track) -> bool {
    state.reference_menu_track_id.as_deref() == Some(track.id.as_str())
        && !reference_dropdown_paths(state, track).is_empty()
}

fn reference_section_height(state: &AppState, track: &storage::Track) -> f32 {
    let _ = (state, track);
    REFERENCE_WAVEFORM_HEIGHT + REFERENCE_SECTION_SPACING + REFERENCE_HEADER_HEIGHT
}

fn reference_waveform_section(state: &AppState, track: &storage::Track) -> ui::View<Message> {
    let has_reference = track.reference_path.is_some();
    let reference_waveform = state
        .reference_waveform
        .as_ref()
        .filter(|_| state.reference_waveform_track_id.as_deref() == Some(track.id.as_str()));
    let reference_cursor_ratio = reference_waveform
        .filter(|_| !state.reference_waveform_busy && !state.reference_transport_playing)
        .and_then(|waveform| {
            waveform::ratio_for_millis(
                state.reference_transport_position_millis,
                waveform.duration_millis,
            )
        });
    let reference_integrated_lufs =
        reference_waveform.and_then(|waveform| waveform.integrated_lufs);
    let reference_loop_bounds = reference_waveform.and_then(|waveform| {
        state
            .loop_selections
            .get(AuditionSource::Reference)
            .and_then(|selection| projected_loop_bounds(selection, waveform.duration_millis))
    });
    let reference_meter_lufs = current_reference_lufs_meter_value(state, &track.id);
    let reference_name = track.reference_path.as_ref().map_or_else(
        || String::from("No reference track"),
        |path| reference_track_name(path),
    );
    let reference_label = if let Some(reference_lufs) = reference_integrated_lufs {
        format!("REFERENCE · {reference_name} · {reference_lufs:.1} LUFS")
    } else if has_reference && state.reference_waveform_busy {
        format!("REFERENCE · {reference_name} · BUILDING")
    } else if has_reference {
        format!("REFERENCE · {reference_name}")
    } else {
        String::from("REFERENCE TRACK")
    };
    let reference_label = if let Some((start_millis, end_millis)) = reference_loop_bounds {
        format!(
            "{reference_label} · LOOP {}–{}",
            format_timestamp(start_millis),
            format_timestamp(end_millis),
        )
    } else {
        reference_label
    };
    let reference_body = if let Some(waveform) = reference_waveform {
        let loop_selection = state
            .loop_selections
            .get(AuditionSource::Reference)
            .map(|selection| (selection.start_ratio, selection.end_ratio));
        let notes = reference_notes_for_track(&state.library, track);
        let reference_annotations_available = track
            .reference_path
            .as_ref()
            .and_then(|path| {
                state
                    .library
                    .reference_tracks
                    .iter()
                    .find(|reference| &reference.path == path)
            })
            .is_some_and(|reference| reference.source_provenance().verified_proof().is_some());
        let note_ratios = notes
            .iter()
            .filter(|_| reference_annotations_available)
            .filter_map(|note| {
                waveform::ratio_for_millis(note.time_millis, waveform.duration_millis)
                    .map(|ratio| (ratio, note.done))
            })
            .collect::<Vec<_>>();
        let reference_note_addresses = notes
            .iter()
            .filter(|_| reference_annotations_available)
            .filter_map(|note| {
                waveform::ratio_for_millis(note.time_millis, waveform.duration_millis).map(|_| {
                    NoteAddress::reference(
                        track
                            .reference_path
                            .as_ref()
                            .expect("reference notes require a catalog path")
                            .clone(),
                        note.id.clone(),
                    )
                })
            })
            .collect::<Vec<_>>();
        let draft_ratio = state
            .reference_draft_note
            .as_ref()
            .filter(|draft| draft.note_id.is_none() && reference_annotations_available)
            .and_then(|draft| {
                waveform::ratio_for_millis(draft.time_millis, waveform.duration_millis)
            });
        let hovered_note_ratio = reference_note_ratio_for_address(
            state,
            track,
            state.hovered_reference_note_id.as_ref(),
        );
        let reference_note_addresses_for_drag = reference_note_addresses.clone();
        waveform::view_with_source_progress_and_loop(
            waveform::WaveformSource::Reference,
            state.reference_waveform_generation,
            Arc::new(waveform.clone()),
            reference_cursor_ratio,
            draft_ratio,
            note_ratios,
            hovered_note_ratio,
            reference_note_ratio_for_address(
                state,
                track,
                state.selected_reference_note_id.as_ref(),
            ),
            loop_selection,
            state
                .reference_waveform_busy
                .then_some(state.reference_waveform_progress)
                .flatten(),
            move |interaction| match interaction {
                waveform::WaveformInteraction::LoopDragStarted { ratio } => {
                    Message::ReferenceLoopDragStarted { ratio }
                }
                waveform::WaveformInteraction::LoopDragEnded {
                    start_ratio,
                    end_ratio,
                } => Message::ReferenceLoopDragEnded {
                    start_ratio,
                    end_ratio,
                },
                waveform::WaveformInteraction::LoopDragCancelled => {
                    Message::ReferenceLoopDragCancelled
                }
                waveform::WaveformInteraction::Clicked { ratio, lower } => {
                    if lower {
                        Message::ReferenceCommentClicked { ratio }
                    } else {
                        Message::ReferenceWaveformClicked { ratio }
                    }
                }
                waveform::WaveformInteraction::PlayheadDragStarted { ratio } => {
                    Message::ReferencePlayheadDragStarted { ratio }
                }
                waveform::WaveformInteraction::PlayheadDragEnded { ratio } => {
                    Message::ReferencePlayheadDragEnded { ratio }
                }
                waveform::WaveformInteraction::PlayheadDragCancelled => {
                    Message::ReferencePlayheadDragCancelled
                }
                waveform::WaveformInteraction::CommentDragStarted { ratio, note_index } => {
                    Message::ReferenceCommentDragStarted {
                        ratio,
                        address: note_index.and_then(|index| {
                            reference_note_addresses_for_drag.get(index).cloned()
                        }),
                    }
                }
                waveform::WaveformInteraction::CommentDragEnded { ratio } => {
                    Message::ReferenceCommentDragEnded { ratio }
                }
                waveform::WaveformInteraction::CommentDragCancelled => {
                    Message::ReferenceCommentDragCancelled
                }
            },
        )
        .fill_width()
        .height(REFERENCE_WAVEFORM_HEIGHT)
    } else {
        let message = if state.reference_waveform_busy && state.waveform_busy {
            "Reference queued behind main analysis…"
        } else if state.reference_waveform_busy {
            "Analyzing reference waveform…"
        } else if has_reference {
            "Reference waveform unavailable for this file."
        } else {
            "Import a reference track to compare it below."
        };
        ui::column([ui::text(message).height(24.0).fill_width()])
            .padding(10.0)
            .fill_width()
            .height(REFERENCE_WAVEFORM_HEIGHT)
    };
    let reference_meter = if has_reference {
        chrome::lufs_meter(reference_meter_lufs, state.reference_waveform_busy)
            .width(LUFS_METER_WIDTH)
            .height(REFERENCE_WAVEFORM_HEIGHT)
    } else {
        ui::spacer()
            .width(LUFS_METER_WIDTH)
            .height(REFERENCE_WAVEFORM_HEIGHT)
    };
    let body = ui::row([reference_meter, reference_body])
        .spacing(0.0)
        .fill_width()
        .height(REFERENCE_WAVEFORM_HEIGHT);
    let header = ui::row([
        ui::spacer()
            .width(LUFS_METER_WIDTH)
            .height(REFERENCE_HEADER_HEIGHT),
        ui::text(reference_label)
            .truncate()
            .height(REFERENCE_HEADER_HEIGHT)
            .fill_width()
            .align_text(ui::TextAlign::Right)
            .subtle(),
    ])
    .spacing(8.0)
    .fill_width()
    .height(REFERENCE_HEADER_HEIGHT);
    ui::column([body, header])
        .spacing(REFERENCE_SECTION_SPACING)
        .fill_width()
        .height(reference_section_height(state, track))
}

fn comments_panel(state: &AppState, track: &storage::Track) -> ui::View<Message> {
    let reference_available = track.reference_path.is_some();
    let reference_notes = reference_notes_for_track(&state.library, track);
    let main_unknown = track.source_provenance().is_unknown();
    let reference_unknown = track
        .reference_path
        .as_ref()
        .and_then(|path| {
            state
                .library
                .reference_tracks
                .iter()
                .find(|reference| &reference.path == path)
        })
        .is_some_and(|reference| reference.source_provenance().is_unknown());
    let source = if reference_available {
        if state.comment_source == CommentSource::Reference
            || (!state.comment_source_explicit
                && track.notes.is_empty()
                && !reference_notes.is_empty())
        {
            CommentSource::Reference
        } else {
            CommentSource::Main
        }
    } else {
        CommentSource::Main
    };
    let (notes, selected_note_id, empty_message) = match source {
        CommentSource::Main => (
            if main_unknown {
                &[]
            } else {
                track.notes.as_slice()
            },
            state.selected_note_id.as_ref(),
            "Click the lower main waveform rail to add a comment for this file.",
        ),
        CommentSource::Reference => (
            if reference_unknown {
                &[]
            } else {
                reference_notes
            },
            state.selected_reference_note_id.as_ref(),
            "Click the lower reference waveform rail to add a comment for this file.",
        ),
    };
    let open_count = notes.iter().filter(|note| !note.done).count();
    let unknown_owner = match source {
        CommentSource::Main if main_unknown => Some(HistoricalBindingOwner::Main {
            track_id: track.id.clone(),
        }),
        CommentSource::Reference if reference_unknown => track
            .reference_path
            .clone()
            .map(|path| HistoricalBindingOwner::Reference { path }),
        _ => None,
    };
    let tabs = ui::row([
        ui::button("MAIN")
            .selected(source == CommentSource::Main)
            .style(if source == CommentSource::Main {
                ui::WidgetStyle::normal(ui::WidgetTone::Accent)
            } else {
                ui::WidgetStyle::default()
            })
            .message(Message::SelectCommentSource(CommentSource::Main))
            .key("comments-tab-main")
            .width(76.0)
            .height(28.0),
        if reference_available {
            ui::button("REFERENCE")
                .selected(source == CommentSource::Reference)
                .style(if source == CommentSource::Reference {
                    ui::WidgetStyle::normal(ui::WidgetTone::Accent)
                } else {
                    ui::WidgetStyle::default()
                })
                .message(Message::SelectCommentSource(CommentSource::Reference))
                .key("comments-tab-reference")
                .width(112.0)
                .height(28.0)
        } else {
            ui::text("REFERENCE").subtle().width(112.0).height(28.0)
        },
    ])
    .spacing(4.0)
    .height(28.0);
    let mut children = vec![
        ui::row([
            ui::text("COMMENTS")
                .style(ui::WidgetStyle::strong(ui::WidgetTone::Neutral))
                .width(104.0)
                .height(28.0),
            tabs,
            ui::spacer().fill_width(),
            ui::text(format!("{} total · {} open", notes.len(), open_count))
                .height(28.0)
                .subtle(),
        ])
        .fill_width()
        .spacing(8.0),
    ];
    if let Some(owner) = unknown_owner {
        let path = match &owner {
            HistoricalBindingOwner::Main { .. } => track.path.clone(),
            HistoricalBindingOwner::Reference { path } => path.clone(),
        };
        let retained_count = match &owner {
            HistoricalBindingOwner::Main { .. } => track.notes.len(),
            HistoricalBindingOwner::Reference { path } => state
                .library
                .reference_tracks
                .iter()
                .find(|reference| &reference.path == path)
                .map_or(0, |reference| reference.notes.len()),
        };
        let warning = historical_source_warning(&owner, &path, retained_count);
        let binding_control = if state
            .historical_binding_in_flight
            .as_ref()
            .is_some_and(|request| request.candidate.owner == owner)
        {
            ui::text("Binding…").subtle().height(28.0)
        } else if let Some(candidate) = state
            .historical_binding_confirmation
            .as_ref()
            .filter(|candidate| candidate.owner == owner)
            .cloned()
        {
            ui::row([
                ui::button("Confirm binding")
                    .primary()
                    .message(Message::ConfirmBindHistoricalComments(candidate.clone()))
                    .height(28.0),
                ui::button("Cancel")
                    .subtle()
                    .message(Message::CancelBindHistoricalComments(candidate))
                    .height(28.0),
            ])
            .spacing(6.0)
        } else if historical_binding_candidate(state, owner.clone()).is_some() {
            ui::button("Bind historical comments to this file…")
                .primary()
                .message(Message::RequestBindHistoricalComments(owner))
                .height(28.0)
        } else {
            ui::text("Waiting for current source verification…")
                .subtle()
                .height(28.0)
        };
        children.push(
            ui::column([ui::text(warning).wrap().fill_width(), binding_control])
                .padding(10.0)
                .spacing(6.0)
                .fill_width(),
        );
    }
    if notes.is_empty() {
        children.push(
            ui::text(empty_message)
                .wrap()
                .height(42.0)
                .fill_width()
                .subtle(),
        );
    } else {
        let hovered_note_id = match source {
            CommentSource::Main => state.hovered_note_id.as_ref(),
            CommentSource::Reference => state.hovered_reference_note_id.as_ref(),
        };
        let editing_note = match source {
            CommentSource::Main => state
                .draft_note
                .as_ref()
                .filter(|draft| draft.note_id.is_some()),
            CommentSource::Reference => state
                .reference_draft_note
                .as_ref()
                .filter(|draft| draft.note_id.is_some()),
        };
        let focused_index = comment_note_index(
            notes,
            selected_note_id,
            source,
            &track.id,
            track.reference_path.as_deref(),
        )
        .or_else(|| {
            editing_note
                .and_then(NoteDraft::address)
                .as_ref()
                .and_then(|address| {
                    comment_note_index(
                        notes,
                        Some(address),
                        source,
                        &track.id,
                        track.reference_path.as_deref(),
                    )
                })
        });
        let window = resolved_virtual_list_window(
            comments_window(state, source),
            notes.len(),
            focused_index,
            true,
        );
        let track_id = track.id.as_str();
        let reference_path = track.reference_path.as_deref();
        let list = ui::virtual_list_windowed(|index| {
            let note = &notes[index];
            if source == CommentSource::Main {
                note_row(
                    index,
                    note,
                    NoteAddress::main(track_id, note.id.clone()),
                    selected_note_id,
                    hovered_note_id,
                    editing_note,
                )
            } else {
                reference_note_row(
                    index,
                    note,
                    NoteAddress::reference(
                        reference_path
                            .expect("reference rows require a catalog path")
                            .to_path_buf(),
                        note.id.clone(),
                    ),
                    selected_note_id,
                    hovered_note_id,
                    editing_note,
                )
            }
        })
        .window(window)
        .row_height(COMMENT_ROW_HEIGHT)
        .overscan_px(COMMENT_ROW_HEIGHT * VIRTUAL_LIST_OVERSCAN_ROWS as f32)
        .on_window_changed(move |change| Message::CommentsWindowChanged { source, change })
        .retain_materialized_window()
        .view()
        .without_chrome()
        .id(comments_scroll_viewport_id(source))
        .fill_width()
        .fill_height();
        children.push(list);
    }
    if source == CommentSource::Main && !main_unknown {
        if let Some(draft) = state
            .draft_note
            .as_ref()
            .filter(|draft| draft.note_id.is_none())
        {
            children.push(note_editor(draft));
        }
    } else if source == CommentSource::Reference
        && !reference_unknown
        && let Some(draft) = state
            .reference_draft_note
            .as_ref()
            .filter(|draft| draft.note_id.is_none())
    {
        children.push(reference_note_editor(draft));
    }
    let content = ui::column(children)
        .padding(12.0)
        .spacing(8.0)
        .fill_width()
        .fill_height();
    ui::stack([
        ui::card()
            .style(ui::WidgetStyle::strong(ui::WidgetTone::Neutral))
            .fill(),
        content,
    ])
    .fill_width()
    .fill_height()
}

fn comment_note_index(
    notes: &[storage::Note],
    address: Option<&NoteAddress>,
    source: CommentSource,
    track_id: &str,
    reference_path: Option<&Path>,
) -> Option<usize> {
    let address = address?;
    let owner_matches = match (&address.owner, source) {
        (NoteOwner::MainTrack(owner_id), CommentSource::Main) => owner_id == track_id,
        (NoteOwner::ReferenceTrack(owner_path), CommentSource::Reference) => {
            reference_path == Some(owner_path.as_path())
        }
        _ => false,
    };
    owner_matches.then(|| notes.iter().position(|note| note.id == address.note_id))?
}

fn reveal_comment_row(
    state: &mut AppState,
    context: &mut ui::UiUpdateContext<Message>,
    source: CommentSource,
    address: &NoteAddress,
) {
    let Some((index, total_items)) = selected_track(state).and_then(|track| {
        let notes = match source {
            CommentSource::Main => track.notes.as_slice(),
            CommentSource::Reference => reference_notes_for_track(&state.library, track),
        };
        comment_note_index(
            notes,
            Some(address),
            source,
            &track.id,
            track.reference_path.as_deref(),
        )
        .map(|index| (index, notes.len()))
    }) else {
        return;
    };
    let window = match source {
        CommentSource::Main => &mut state.main_comments_window,
        CommentSource::Reference => &mut state.reference_comments_window,
    };
    *window = resolved_virtual_list_window(*window, total_items, Some(index), true);
    context.scroll_into_view(
        comments_scroll_viewport_id(source),
        index as f32 * COMMENT_ROW_HEIGHT,
        COMMENT_ROW_HEIGHT,
        LIBRARY_REVEAL_MARGIN,
        LIBRARY_REVEAL_MARGIN,
    );
}

fn note_editor(draft: &NoteDraft) -> ui::View<Message> {
    let identity = draft.identity();
    let editor_identity = identity.clone();
    ui::column([
        ui::text(format!(
            "COMMENT AT {}",
            format_timestamp(draft.time_millis)
        ))
        .height(20.0)
        .fill_width()
        .subtle(),
        ui::text_input(draft.body.clone())
            .placeholder("Write a comment…")
            .message_event(move |input| {
                let submitted = input.is_submitted();
                let value = input.into_value();
                if submitted {
                    Message::SaveDraftNote(editor_identity.clone())
                } else {
                    Message::DraftNoteChanged {
                        identity: editor_identity.clone(),
                        body: value,
                    }
                }
            })
            .id(MAIN_COMMENT_EDITOR_ID)
            .fill_width()
            .height(38.0),
        ui::row([
            ui::button("Save comment")
                .primary()
                .message(Message::SaveDraftNote(identity.clone()))
                .height(28.0),
            ui::button("Cancel")
                .subtle()
                .message(Message::CancelDraftNote(identity))
                .height(28.0),
        ])
        .spacing(8.0)
        .fill_width(),
    ])
    .padding(10.0)
    .spacing(8.0)
    .fill_width()
}

fn reference_note_editor(draft: &NoteDraft) -> ui::View<Message> {
    let identity = draft.identity();
    let editor_identity = identity.clone();
    ui::column([
        ui::text(format!(
            "REFERENCE COMMENT AT {}",
            format_timestamp(draft.time_millis)
        ))
        .height(20.0)
        .fill_width()
        .subtle(),
        ui::text_input(draft.body.clone())
            .placeholder("Write a reference comment…")
            .message_event(move |input| {
                let submitted = input.is_submitted();
                let value = input.into_value();
                if submitted {
                    Message::SaveReferenceDraftNote(editor_identity.clone())
                } else {
                    Message::ReferenceDraftNoteChanged {
                        identity: editor_identity.clone(),
                        body: value,
                    }
                }
            })
            .id(REFERENCE_COMMENT_EDITOR_ID)
            .fill_width()
            .height(38.0),
        ui::row([
            ui::button("Save reference comment")
                .primary()
                .message(Message::SaveReferenceDraftNote(identity.clone()))
                .height(28.0),
            ui::button("Cancel")
                .subtle()
                .message(Message::CancelReferenceDraftNote(identity))
                .height(28.0),
        ])
        .spacing(8.0)
        .fill_width(),
    ])
    .padding(10.0)
    .spacing(8.0)
    .fill_width()
}

fn comment_row_style(selected: bool, domain_hovered: bool) -> ui::WidgetStyle {
    if selected && !domain_hovered {
        ui::WidgetStyle::normal(ui::WidgetTone::Accent)
    } else {
        ui::WidgetStyle::subtle(ui::WidgetTone::Accent)
    }
}

fn comment_row_palette(selected: bool, domain_hovered: bool) -> ui::DenseRowPalette {
    let style = comment_row_style(selected, domain_hovered);
    let mut palette =
        radiant::gui::list::dense_row_palette_from_style(&ThemeTokens::default(), style);
    if selected && domain_hovered {
        palette.selected = palette.selected_hovered;
    }
    palette
}

fn note_row(
    index: usize,
    note: &storage::Note,
    address: NoteAddress,
    selected_note_id: Option<&NoteAddress>,
    hovered_note_id: Option<&NoteAddress>,
    editing_note: Option<&NoteDraft>,
) -> ui::View<Message> {
    let selected = selected_note_id == Some(&address);
    let domain_hovered = hovered_note_id == Some(&address);
    let editing = editing_note.is_some_and(|draft| draft.address().as_ref() == Some(&address));
    let editing_identity = editing_note.map(NoteDraft::identity);
    let note_key = qualified_note_identity_key(&address);
    let note_body = note.body.clone();
    let note_time_millis = note.time_millis;
    let play_address = address.clone();
    let play_control = ui::icon_button(review_transport_icon(&REVIEW_SOURCE_PLAY_ICON, false))
        .subtle()
        .message(Message::PlayComment {
            address: play_address,
        })
        .key(format!("comment-play-{note_key}"))
        .tooltip("Play from comment")
        .size(28.0, 24.0);
    let body = if editing {
        let draft = editing_note.expect("an editing row should have a matching draft");
        let identity = editing_identity
            .as_ref()
            .expect("an editing row should have a matching draft identity")
            .clone();
        ui::text_input(draft.body.clone())
            .message_event(move |input| {
                if input.is_submitted() {
                    Message::SaveDraftNote(identity.clone())
                } else {
                    Message::DraftNoteChanged {
                        identity: identity.clone(),
                        body: input.into_value(),
                    }
                }
            })
            .id(main_inline_comment_editor_id(&address))
            .fill_width()
            .height(30.0)
    } else {
        ui::text(note_body)
            .style(if selected {
                ui::WidgetStyle::strong(ui::WidgetTone::Neutral)
            } else if note.done {
                ui::WidgetStyle::subtle(ui::WidgetTone::Neutral)
            } else {
                ui::WidgetStyle::normal(ui::WidgetTone::Neutral)
            })
            .wrap()
            .height(30.0)
            .fill_width()
    };
    let trailing_control = if editing {
        let identity =
            editing_identity.expect("an editing row should have a matching draft identity");
        ui::row([
            ui::button("Save")
                .primary()
                .message(Message::SaveDraftNote(identity.clone()))
                .height(28.0),
            ui::button("Cancel")
                .subtle()
                .message(Message::CancelDraftNote(identity))
                .height(28.0),
        ])
        .spacing(4.0)
        .height(28.0)
    } else {
        ui::row([
            play_control,
            ui::close_button()
                .subtle()
                .message(Message::DeleteNote(address.clone()))
                .key(format!("comment-remove-{note_key}"))
                .tooltip("Remove comment")
                .size(28.0, 24.0),
        ])
        .spacing(4.0)
        .height(28.0)
    };
    let row = ui::list_row(
        index,
        [
            ui::text(format_timestamp(note_time_millis))
                .style(if selected {
                    ui::WidgetStyle::subtle(ui::WidgetTone::Accent)
                } else {
                    ui::WidgetStyle::subtle(ui::WidgetTone::Neutral)
                })
                .height(30.0)
                .width(68.0)
                .subtle(),
            body,
            trailing_control,
        ],
    )
    .without_chrome()
    .fill_width();
    let row_key = address.clone();
    let hover_address = address.clone();
    let double_edit_address = address.clone();
    let row_actions = ui::row_actions()
        .primary(move || Message::SelectNote(row_key.clone()))
        .double_activate(move || Message::EditNote(double_edit_address.clone()));
    let row_style = comment_row_style(selected, domain_hovered);
    let mut row_surface = ui::interactive_row_underlay(row)
        .selected(selected)
        .style(row_style);
    if selected && domain_hovered {
        row_surface =
            row_surface.dense_chrome_palette(comment_row_palette(selected, domain_hovered));
    }
    let row_surface = row_surface
        .leading_marker_if(
            selected,
            ui::DenseRowMarkerStyle::new(
                DenseRowMarkerParts::leading(3.0)
                    .edge_inset(1.0)
                    .vertical_inset(3.0),
                TRACK_CARD_SELECTED_CORAL,
            ),
        )
        .stable_row_identity(0xCAD3_0002, note_key.clone())
        .actions(row_actions)
        .fill_width()
        .height(COMMENT_ROW_HEIGHT);
    ui::stack([
        row_surface,
        chrome::comment_hover(
            Message::CommentHoverStarted(hover_address.clone()),
            Message::CommentHoverEnded(hover_address),
        )
        .key(format!("comment-hover-{note_key}"))
        .fill(),
    ])
    .fill_width()
    .height(COMMENT_ROW_HEIGHT)
}

