fn refresh_selected_track_index(state: &mut AppState) {
    state.selected_track_index = state
        .library
        .selected_track_id
        .as_deref()
        .and_then(|id| state.library.tracks.iter().position(|track| track.id == id));
}

fn selected_track(state: &AppState) -> Option<&storage::Track> {
    let selected_id = state.library.selected_track_id.as_deref()?;
    if let Some(index) = state.selected_track_index
        && let Some(track) = state.library.tracks.get(index)
        && track.id == selected_id
    {
        return Some(track);
    }
    state
        .library
        .tracks
        .iter()
        .find(|track| track.id == selected_id)
}

fn normalize_startup_track_selection(library: &mut storage::Library) -> (Option<String>, bool) {
    let previous_selected_id = library.selected_track_id.clone();
    let startup_track_id = library
        .selected_track_id
        .as_deref()
        .filter(|selected_id| library.tracks.iter().any(|track| track.id == *selected_id))
        .map(String::from)
        .or_else(|| library.tracks.first().map(|track| track.id.clone()));
    let selection_changed = previous_selected_id.as_ref() != startup_track_id.as_ref();
    library.selected_track_id = startup_track_id.clone();
    (startup_track_id, selection_changed)
}

fn reference_notes_for_track<'a>(
    library: &'a storage::Library,
    track: &storage::Track,
) -> &'a [storage::Note] {
    let Some(path) = track.reference_path.as_ref() else {
        return &[];
    };
    library
        .reference_tracks
        .iter()
        .find(|reference| reference.path == *path)
        .map_or(&[], |reference| reference.notes.as_slice())
}

fn selected_reference_notes(state: &AppState) -> &[storage::Note] {
    selected_track(state)
        .map(|track| reference_notes_for_track(&state.library, track))
        .unwrap_or(&[])
}

fn selected_reference_track_mut(state: &mut AppState) -> Option<&mut storage::ReferenceTrack> {
    let selected_id = state.library.selected_track_id.as_ref()?.clone();
    let path = state
        .library
        .tracks
        .iter()
        .find(|track| track.id == selected_id)
        .and_then(|track| track.reference_path.clone())?;
    state
        .library
        .reference_tracks
        .iter_mut()
        .find(|reference| reference.path == path)
}

fn is_current_main_owner(state: &AppState, owner: &NoteOwner) -> bool {
    matches!(
        (owner, state.library.selected_track_id.as_deref()),
        (NoteOwner::MainTrack(owner_id), Some(selected_id)) if owner_id == selected_id
    )
}

fn selected_reference_owner(state: &AppState) -> Option<NoteOwner> {
    selected_track(state)
        .and_then(|track| track.reference_path.clone())
        .map(NoteOwner::ReferenceTrack)
}

fn is_current_reference_owner(state: &AppState, owner: &NoteOwner) -> bool {
    selected_reference_owner(state).as_ref() == Some(owner)
}

fn is_current_main_note_address(state: &AppState, address: &NoteAddress) -> bool {
    is_current_main_owner(state, &address.owner)
        && selected_track(state)
            .is_some_and(|track| track.notes.iter().any(|note| note.id == address.note_id))
}

fn is_current_reference_note_address(state: &AppState, address: &NoteAddress) -> bool {
    is_current_reference_owner(state, &address.owner)
        && selected_reference_notes(state)
            .iter()
            .any(|note| note.id == address.note_id)
}

fn note_address_for_owner(owner: &NoteOwner, note_id: &str) -> NoteAddress {
    NoteAddress {
        owner: owner.clone(),
        note_id: note_id.to_owned(),
    }
}

fn reference_track_name(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .map_or_else(|| path.to_string_lossy().into_owned(), ToOwned::to_owned)
}

fn note_ratio_for_address(
    state: &AppState,
    track: &storage::Track,
    address: Option<&NoteAddress>,
) -> Option<f32> {
    if track.source_provenance().is_unknown() {
        return None;
    }
    let address = address.filter(
        |address| matches!(&address.owner, NoteOwner::MainTrack(track_id) if track_id == &track.id),
    )?;
    let note = track.notes.iter().find(|note| note.id == address.note_id)?;
    let waveform = state
        .waveform
        .as_ref()
        .filter(|_| state.waveform_track_id.as_deref() == Some(track.id.as_str()))?;
    waveform::ratio_for_millis(note.time_millis, waveform.duration_millis)
}

#[cfg(test)]
fn note_ratio_for_id(
    state: &AppState,
    track: &storage::Track,
    note_id: Option<&str>,
) -> Option<f32> {
    let address = note_id.map(|note_id| NoteAddress::main(track.id.clone(), note_id));
    note_ratio_for_address(state, track, address.as_ref())
}

fn reference_note_ratio_for_address(
    state: &AppState,
    track: &storage::Track,
    address: Option<&NoteAddress>,
) -> Option<f32> {
    let reference_path = track.reference_path.as_ref()?;
    let address = address.filter(|address| {
        matches!(&address.owner, NoteOwner::ReferenceTrack(path) if path == reference_path)
    })?;
    let reference = state
        .library
        .reference_tracks
        .iter()
        .find(|reference| &reference.path == reference_path)?;
    if reference.source_provenance().is_unknown() {
        return None;
    }
    let note = reference_notes_for_track(&state.library, track)
        .iter()
        .find(|note| note.id == address.note_id)?;
    let waveform = state
        .reference_waveform
        .as_ref()
        .filter(|_| state.reference_waveform_track_id.as_deref() == Some(track.id.as_str()))?;
    waveform::ratio_for_millis(note.time_millis, waveform.duration_millis)
}

fn selected_track_mut(state: &mut AppState) -> Option<&mut storage::Track> {
    let selected_id = state.library.selected_track_id.as_deref()?.to_owned();
    if let Some(index) = state.selected_track_index
        && state
            .library
            .tracks
            .get(index)
            .is_some_and(|track| track.id == selected_id)
    {
        return state.library.tracks.get_mut(index);
    }
    state
        .library
        .tracks
        .iter_mut()
        .find(|track| track.id == selected_id)
}

fn decode_result_is_current(state: &AppState, track_id: &str, generation: u64) -> bool {
    state.library.selected_track_id.as_deref() == Some(track_id)
        && state.waveform_generation == generation
}

fn decode_progress_is_current(state: &AppState, track_id: &str, generation: u64) -> bool {
    decode_result_is_current(state, track_id, generation)
        && state
            .waveform_in_flight
            .as_ref()
            .is_some_and(|request| request.track_id == track_id && request.generation == generation)
}

fn take_matching_waveform_in_flight(
    state: &mut AppState,
    track_id: &str,
    generation: u64,
) -> Option<WaveformDecodeRequest> {
    let matches = state
        .waveform_in_flight
        .as_ref()
        .is_some_and(|request| request.track_id == track_id && request.generation == generation);
    matches.then(|| state.waveform_in_flight.take()).flatten()
}

fn reference_decode_result_is_current(state: &AppState, track_id: &str, generation: u64) -> bool {
    state.library.selected_track_id.as_deref() == Some(track_id)
        && state.reference_waveform_generation == generation
}

fn reference_decode_progress_is_current(state: &AppState, track_id: &str, generation: u64) -> bool {
    reference_decode_result_is_current(state, track_id, generation)
        && state
            .reference_waveform_in_flight
            .as_ref()
            .is_some_and(|request| request.track_id == track_id && request.generation == generation)
}

fn take_matching_reference_waveform_in_flight(
    state: &mut AppState,
    track_id: &str,
    generation: u64,
) -> Option<WaveformDecodeRequest> {
    let matches = state
        .reference_waveform_in_flight
        .as_ref()
        .is_some_and(|request| request.track_id == track_id && request.generation == generation);
    matches
        .then(|| state.reference_waveform_in_flight.take())
        .flatten()
}

fn transport_command_is_confirmed(snapshot: transport::Snapshot, token: u64) -> bool {
    snapshot.acknowledged_token >= token
}

fn format_timestamp(time_millis: u64) -> String {
    let total_seconds = time_millis / 1_000;
    format!("{:02}:{:02}", total_seconds / 60, total_seconds % 60)
}

fn plural(count: usize) -> &'static str {
    if count == 1 { "" } else { "s" }
}

