    fn planner_drag_handle_widget_id(frame: &radiant::runtime::SurfaceFrame) -> u64 {
        let grip_lines = frame
            .paint_plan
            .primitives
            .iter()
            .filter_map(|primitive| match primitive {
                PaintPrimitive::StrokePolyline(line) if line.points.len() == 2 => Some(line),
                _ => None,
            })
            .collect::<Vec<_>>();
        grip_lines
            .iter()
            .find_map(|line| {
                (grip_lines
                    .iter()
                    .filter(|candidate| candidate.widget_id == line.widget_id)
                    .count()
                    >= 3)
                    .then_some(line.widget_id)
            })
            .expect("the Planner drag handle should paint its three grip lines")
    }

    fn planner_drag_handle_point(frame: &radiant::runtime::SurfaceFrame) -> Point {
        let widget_id = planner_drag_handle_widget_id(frame);
        let grip_lines = frame
            .paint_plan
            .primitives
            .iter()
            .filter_map(|primitive| match primitive {
                PaintPrimitive::StrokePolyline(line)
                    if line.widget_id == widget_id && line.points.len() == 2 =>
                {
                    Some(line)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        let first_line = grip_lines
            .first()
            .expect("the Planner drag handle should have a first grip line");
        let start = first_line.points[0];
        let end = first_line.points[1];
        Point::new(
            (start.x + end.x) * 0.5,
            grip_lines
                .iter()
                .map(|line| (line.points[0].y + line.points[1].y) * 0.5)
                .sum::<f32>()
                / grip_lines.len() as f32,
        )
    }

    fn planner_drag_handle_point_in_viewport(
        frame: &radiant::runtime::SurfaceFrame,
        viewport: Rect,
    ) -> Point {
        let grip_lines = frame
            .paint_plan
            .primitives
            .iter()
            .filter_map(|primitive| match primitive {
                PaintPrimitive::StrokePolyline(line) if line.points.len() == 2 => Some(line),
                _ => None,
            })
            .collect::<Vec<_>>();
        let widget_id = grip_lines
            .iter()
            .find_map(|line| {
                let lines = grip_lines
                    .iter()
                    .filter(|candidate| candidate.widget_id == line.widget_id)
                    .collect::<Vec<_>>();
                (lines.len() >= 3
                    && lines.iter().all(|line| {
                        viewport.contains(Point::new(
                            (line.points[0].x + line.points[1].x) * 0.5,
                            (line.points[0].y + line.points[1].y) * 0.5,
                        ))
                    }))
                .then_some(line.widget_id)
            })
            .expect("the requested Planner viewport should contain a drag handle");
        let lines = grip_lines
            .iter()
            .filter(|line| line.widget_id == widget_id)
            .collect::<Vec<_>>();
        Point::new(
            (lines[0].points[0].x + lines[0].points[1].x) * 0.5,
            lines
                .iter()
                .map(|line| (line.points[0].y + line.points[1].y) * 0.5)
                .sum::<f32>()
                / lines.len() as f32,
        )
    }

