    fn verified_audition_waveform_for(path: &Path) -> crate::audio::VerifiedWaveform {
        let proof = crate::source::AudioSourceProof {
            sha256: "0".repeat(64),
            byte_len: 0,
        };
        let stamp = crate::source::SourceFileStamp {
            dev: 0,
            inode: 0,
            len: 0,
            mtime_nanos: 0,
            ctime_nanos: 0,
        };
        let ticket = crate::source::VerifiedSourceTicket::new(path.to_path_buf(), proof, stamp)
            .expect("test source ticket should be valid");
        crate::audio::VerifiedWaveform::new(audition_waveform(), ticket)
    }

    fn verified_audition_waveform() -> crate::audio::VerifiedWaveform {
        verified_audition_waveform_for(Path::new("/external/audition.wav"))
    }

    fn historical_main_binding_state() -> (
        AppState,
        PathBuf,
        crate::source::AudioSourceProof,
        Vec<Note>,
    ) {
        let track_id = String::from("historical-binding");
        let path = PathBuf::from("/external/historical-binding.wav");
        let notes = vec![
            Note {
                id: String::from("historical-note-1"),
                time_millis: 125,
                body: String::from("preserve this exact body"),
                done: false,
            },
            Note {
                id: String::from("historical-note-2"),
                time_millis: 875,
                body: String::from("and this completed note"),
                done: true,
            },
        ];
        let verified = verified_audition_waveform_for(&path);
        let ticket = verified.ticket().clone();
        let proof = ticket.proof().clone();
        let mut track = audition_track(&track_id);
        track.path = path.clone();
        track.reference_path = None;
        track.source_proof = crate::source::SourceProvenance::Unknown;
        track.notes = notes.clone();
        let mut state = AppState {
            busy: false,
            waveform: Some(verified.into_waveform()),
            waveform_source_ticket: Some(ticket),
            waveform_track_id: Some(track_id.clone()),
            waveform_generation: 7,
            ..AppState::default()
        };
        state.library.selected_track_id = Some(track_id);
        state.library.tracks.push(track);
        (state, path, proof, notes)
    }

    fn audition_volume_edit(
        start: f32,
        value: f32,
        terminal: Option<EditPhase>,
    ) -> SliderEditBatch {
        let provenance = InteractionProvenance::Programmatic;
        let begin = EditEvent::begin(start, provenance);
        let update = begin
            .update(value, provenance)
            .expect("volume edit update should follow begin");
        match terminal {
            None => SliderEditBatch::from_events(&[begin, update]).expect("volume edit batch"),
            Some(EditPhase::Commit) => {
                let commit = update
                    .commit(value, provenance)
                    .expect("volume edit commit should follow update");
                SliderEditBatch::from_events(&[begin, update, commit])
                    .expect("volume edit commit batch")
            }
            Some(EditPhase::Cancel) => {
                let cancel = update
                    .cancel(provenance)
                    .expect("volume edit cancel should follow update");
                SliderEditBatch::from_events(&[begin, update, cancel])
                    .expect("volume edit cancel batch")
            }
            Some(EditPhase::Begin | EditPhase::Update) => {
                panic!("volume edit helper only accepts terminal phases")
            }
        }
    }

    fn audition_state(ids: &[&str]) -> AppState {
        let queue = ids.iter().map(|id| String::from(*id)).collect::<Vec<_>>();
        let selected_id = queue.first().cloned();
        let mut state = AppState {
            busy: false,
            workspace_mode: WorkspaceMode::Audition,
            audition_queue: queue,
            audition_queue_index: 0,
            waveform: selected_id.as_ref().map(|_| audition_waveform()),
            waveform_track_id: selected_id.clone(),
            ..AppState::default()
        };
        state.library.selected_track_id = selected_id;
        state.library.tracks = ids.iter().map(|id| audition_track(id)).collect();
        state
    }

