    fn dropdown_surface_rect(primitives: &[PaintPrimitive], anchor: Point) -> Option<Rect> {
        primitives.iter().find_map(|primitive| match primitive {
            PaintPrimitive::FillPolygon(fill)
                if fill.color == ThemeTokens::default().surface_overlay =>
            {
                let min_x = fill
                    .points
                    .iter()
                    .map(|point| point.x)
                    .fold(f32::INFINITY, f32::min);
                let min_y = fill
                    .points
                    .iter()
                    .map(|point| point.y)
                    .fold(f32::INFINITY, f32::min);
                let max_x = fill
                    .points
                    .iter()
                    .map(|point| point.x)
                    .fold(f32::NEG_INFINITY, f32::max);
                let max_y = fill
                    .points
                    .iter()
                    .map(|point| point.y)
                    .fold(f32::NEG_INFINITY, f32::max);
                let rect = Rect::from_min_max(Point::new(min_x, min_y), Point::new(max_x, max_y));
                ((rect.min.x - anchor.x).abs() < 0.01 && (rect.min.y - anchor.y).abs() < 0.01)
                    .then_some(rect)
            }
            PaintPrimitive::FillRect(fill)
                if fill.color == ThemeTokens::default().surface_overlay
                    && (fill.rect.min.x - anchor.x).abs() < 0.01
                    && (fill.rect.min.y - anchor.y).abs() < 0.01 =>
            {
                Some(fill.rect)
            }
            _ => None,
        })
    }

    fn paint_plan_contains_icon(primitives: &[PaintPrimitive], icon: &ui::SvgIcon) -> bool {
        let mut expected_primitives = Vec::new();
        icon.append_paint(
            &mut expected_primitives,
            0,
            Rect::from_min_size(Point::new(0.0, 0.0), Vector2::new(16.0, 16.0)),
        );
        let Some(PaintPrimitive::Svg(expected)) = expected_primitives.first() else {
            return false;
        };
        primitives.iter().any(|primitive| {
            matches!(
                primitive,
                PaintPrimitive::Svg(actual) if actual.document == expected.document
            )
        })
    }

    fn last_fill_color_covering_point(
        primitives: &[PaintPrimitive],
        point: Point,
    ) -> Option<ui::Rgba8> {
        primitives
            .iter()
            .filter_map(|primitive| {
                let PaintPrimitive::FillRect(fill) = primitive else {
                    return None;
                };
                (point.x > fill.rect.min.x
                    && point.x < fill.rect.max.x
                    && point.y > fill.rect.min.y
                    && point.y < fill.rect.max.y)
                    .then_some(fill.color)
            })
            .next_back()
    }

    fn source_icon_stop_states(primitives: &[PaintPrimitive]) -> Vec<bool> {
        let mut expected_documents = Vec::new();
        for (shows_stop, icon) in [
            (false, super::audition_source_icon(false)),
            (true, super::audition_source_icon(true)),
        ] {
            let mut expected_primitives = Vec::new();
            icon.append_paint(
                &mut expected_primitives,
                0,
                Rect::from_min_size(Point::new(0.0, 0.0), Vector2::new(16.0, 16.0)),
            );
            let Some(PaintPrimitive::Svg(expected)) = expected_primitives.first() else {
                continue;
            };
            expected_documents.push((shows_stop, expected.document.clone()));
        }

        let mut states = primitives
            .iter()
            .filter_map(|primitive| {
                let PaintPrimitive::Svg(actual) = primitive else {
                    return None;
                };
                expected_documents
                    .iter()
                    .find_map(|(shows_stop, document)| {
                        (&actual.document == document).then_some((actual.rect.min.y, *shows_stop))
                    })
            })
            .collect::<Vec<_>>();
        states.sort_by(|left, right| left.0.total_cmp(&right.0));
        states
            .into_iter()
            .map(|(_, shows_stop)| shows_stop)
            .collect()
    }

    fn audition_source_icon_rects(primitives: &[PaintPrimitive]) -> Vec<Rect> {
        let mut expected_documents = Vec::new();
        for icon in [
            super::audition_source_icon(false),
            super::audition_source_icon(true),
        ] {
            let mut expected_primitives = Vec::new();
            icon.append_paint(
                &mut expected_primitives,
                0,
                Rect::from_min_size(Point::new(0.0, 0.0), Vector2::new(16.0, 16.0)),
            );
            let Some(PaintPrimitive::Svg(expected)) = expected_primitives.first() else {
                continue;
            };
            expected_documents.push(expected.document.clone());
        }

        let mut rects = primitives
            .iter()
            .filter_map(|primitive| {
                let PaintPrimitive::Svg(actual) = primitive else {
                    return None;
                };
                expected_documents
                    .contains(&actual.document)
                    .then_some(actual.rect)
            })
            .collect::<Vec<_>>();
        rects.sort_by(|left, right| left.min.y.total_cmp(&right.min.y));
        rects
    }

    fn waveform_lower_rail_rects(primitives: &[PaintPrimitive]) -> Vec<Rect> {
        let mut rects = primitives
            .iter()
            .filter_map(|primitive| match primitive {
                PaintPrimitive::FillRect(fill)
                    if fill.color
                        == ThemeTokens::default()
                            .surface_overlay
                            .blend_toward(ThemeTokens::default().bg_primary, 0.45)
                        && fill.rect.width() > 300.0
                        && fill.rect.height() > 20.0
                        && fill.rect.height() <= WAVEFORM_HEIGHT =>
                {
                    Some(fill.rect)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        rects.sort_by(|left, right| left.min.y.total_cmp(&right.min.y));
        rects
    }

    fn command_has_begin_drag(command: &Command<Message>) -> bool {
        match command {
            Command::BeginDrag { .. } => true,
            Command::Batch(commands) => commands.iter().any(command_has_begin_drag),
            _ => false,
        }
    }

    fn command_has_end_drag(command: &Command<Message>) -> bool {
        match command {
            Command::EndDrag => true,
            Command::Batch(commands) => commands.iter().any(command_has_end_drag),
            _ => false,
        }
    }

