        update(
            &mut state,
            Message::RemoveReferenceTrack(reference_path),
            &mut context,
        );

        assert!(state.settings_open);
        assert!(state.library.reference_tracks.is_empty());
        assert_eq!(state.library.tracks[0].reference_path, None);
