        let mut review_state = AppState {
            busy: false,
            workspace_mode: super::WorkspaceMode::Review,
            ..AppState::default()
        };
        review_state.library.selected_track_id = Some(String::from("library-target"));
        review_state
            .library
            .tracks
            .push(track("library-first", TrackStatus::Maybe));
        review_state
            .library
