    #[test]
    fn workspace_modes_paint_expected_surfaces_and_text_hierarchy() {
        let theme = ThemeTokens::default();
        let mut state = AppState {
            busy: false,
            ..AppState::default()
        };
        for (mode, eyebrow, subtitle, expected_surface) in [
            (
                WorkspaceMode::Review,
                "Your review desk",
                None,
                theme.surface_overlay,
            ),
            (
                WorkspaceMode::Planner,
                "FINISHING BOARD",
                None,
                theme.surface_raised,
            ),
            (
                WorkspaceMode::Audition,
                "AUDITION",
                Some("Fixed shuffle · one pass"),
                theme.surface_overlay,
            ),
        ] {
            state.workspace_mode = mode;
            let frame = project_surface(&state)
                .view_frame_at_size_with_default_theme(Vector2::new(1180.0, 720.0));
            let heading = frame
                .paint_plan
                .first_text_run(eyebrow)
                .unwrap_or_else(|| panic!("missing {eyebrow:?} in {mode:?}"));
            let surface = frame.paint_plan.fill_rects().find(|fill| {
                fill.color == expected_surface
                    && heading.rect.min.x >= fill.rect.min.x
                    && heading.rect.min.y >= fill.rect.min.y
                    && heading.rect.max.x <= fill.rect.max.x
                    && heading.rect.max.y <= fill.rect.max.y
                    && (heading.rect.min.x - (fill.rect.min.x + super::WORKSPACE_PANEL_PADDING))
                        .abs()
                        < 0.01
            });
            assert!(
                surface.is_some(),
                "{mode:?} should paint its expected neutral workspace surface with the shared inset"
            );
            assert_eq!(heading.color, theme.text_primary);
            if let Some(subtitle) = subtitle {
                assert_eq!(
                    frame.paint_plan.first_text_color(subtitle),
                    Some(theme.text_muted),
                    "{mode:?} subtitle should remain subtle"
                );
            } else {
                assert_eq!(
                    frame
                        .paint_plan
                        .first_text_color("Move every track toward release."),
                    None,
                    "{mode:?} should not paint the removed Planner subtitle"
                );
            }
        }
    }

    #[test]
    fn planner_paints_a_raised_board_behind_strong_columns() {
        let theme = ThemeTokens::default();
        let state = AppState {
            busy: false,
            workspace_mode: WorkspaceMode::Planner,
            ..AppState::default()
        };
        let frame = project_surface(&state)
            .view_frame_at_size_with_default_theme(Vector2::new(1_180.0, 900.0));
        let contains = |outer: Rect, inner: Rect| {
            inner.min.x >= outer.min.x
                && inner.min.y >= outer.min.y
                && inner.max.x <= outer.max.x
                && inner.max.y <= outer.max.y
        };
        let board_heading = frame
            .paint_plan
            .first_text_run("FINISHING BOARD")
            .expect("Planner should paint its board heading");
        let board = frame
            .paint_plan
            .fill_rects()
            .find(|fill| {
                fill.color == theme.surface_raised
                    && contains(fill.rect, board_heading.rect)
                    && (board_heading.rect.min.x
                        - (fill.rect.min.x + super::WORKSPACE_PANEL_PADDING))
                        .abs()
                        < 0.01
            })
            .expect("Planner should paint its outer board with the raised neutral surface");

        for stage in [
            TrackStage::SoundDesign,
            TrackStage::Production,
            TrackStage::Mixdown,
            TrackStage::Mastering,
        ] {
            let heading_label = super::planner_column_heading(stage);
            let heading = frame
                .paint_plan
                .first_text_run(heading_label)
                .unwrap_or_else(|| panic!("Planner should paint the {heading_label:?} heading"));
            let column = frame
                .paint_plan
                .fill_rects()
                .find(|fill| {
                    fill.color == theme.surface_overlay && contains(fill.rect, heading.rect)
                })
                .unwrap_or_else(|| {
                    panic!(
                        "Planner should paint the {heading_label:?} column with the overlay neutral surface"
                    )
                });
            assert!(
                column.rect.min.y > board.rect.min.y,
                "Planner columns should be nested below the outer board heading"
            );
        }

        assert!(
            board.color.r < theme.surface_overlay.r
                && board.color.g < theme.surface_overlay.g
                && board.color.b < theme.surface_overlay.b,
            "Planner board should be darker than its columns: board={:?}, columns={:?}",
            board.color,
            theme.surface_overlay
        );
    }

    #[test]
    fn planner_color_codes_stage_headers_and_count_badges() {
        let theme = ThemeTokens::default();
        let state = AppState {
            busy: false,
            workspace_mode: WorkspaceMode::Planner,
            ..AppState::default()
        };
        let frame = project_surface(&state)
            .view_frame_at_size_with_default_theme(Vector2::new(1_180.0, 900.0));
        let contains = |outer: Rect, inner: Rect| {
            inner.min.x >= outer.min.x
                && inner.min.y >= outer.min.y
                && inner.max.x <= outer.max.x
                && inner.max.y <= outer.max.y
        };

        for stage in [
            TrackStage::SoundDesign,
            TrackStage::Production,
            TrackStage::Mixdown,
            TrackStage::Mastering,
        ] {
            let heading = frame
                .paint_plan
                .first_text_run(super::planner_column_heading(stage))
                .expect("Planner should paint every stage heading");
            let expected_color = match stage {
                TrackStage::SoundDesign => theme.accent_warning,
                TrackStage::Production => theme.accent_mint,
                TrackStage::Mixdown => theme.highlight_cyan,
                TrackStage::Mastering => theme.accent_danger,
            };
            assert_eq!(
                super::planner_stage_visual_color(stage, &theme),
                expected_color,
                "Planner should map {:?} to its expected stage color",
                stage
            );
            let column = frame
                .paint_plan
                .fill_rects()
                .find(|fill| {
                    fill.color == theme.surface_overlay && contains(fill.rect, heading.rect)
                })
                .unwrap_or_else(|| {
                    panic!(
                        "Planner should paint the {:?} column with the overlay neutral surface",
                        stage
                    )
                });
            assert!(
                frame.paint_plan.fill_rects().any(|fill| {
                    fill.color == expected_color
                        && fill.rect.min.x >= column.rect.min.x
                        && fill.rect.max.x <= column.rect.max.x
                        && fill.rect.max.x <= heading.rect.min.x
                        && fill.rect.min.y < heading.rect.max.y
                        && fill.rect.max.y > heading.rect.min.y
                }),
                "Planner should paint a stage-colored rail for {:?}",
                stage
            );
            assert!(
                frame.paint_plan.stroke_rects().any(|stroke| {
                    stroke.color == expected_color
                        && stroke.rect.min.x >= column.rect.min.x
                        && stroke.rect.max.x <= column.rect.max.x
                        && stroke.rect.min.y < heading.rect.max.y
                        && stroke.rect.max.y > heading.rect.min.y
                }),
                "Planner should outline the {:?} count badge with its stage color",
                stage
            );
        }
    }

