    #[derive(Clone, Debug, PartialEq)]
    struct TrackCardPaintSnapshot {
        fill: ui::Rgba8,
        outline: ui::Rgba8,
        outline_width: f32,
        rail: ui::Rgba8,
        rail_width: f32,
        points: Arc<[Point]>,
    }

    fn track_card_paint_snapshots(primitives: &[PaintPrimitive]) -> Vec<TrackCardPaintSnapshot> {
        primitives
            .iter()
            .filter_map(|primitive| {
                let PaintPrimitive::FillPolygon(fill) = primitive else {
                    return None;
                };
                if fill.points.len() != 5 {
                    return None;
                }
                let (outline, outline_width) = primitives.iter().find_map(|primitive| {
                    let PaintPrimitive::StrokePolygon(stroke) = primitive else {
                        return None;
                    };
                    (stroke.widget_id == fill.widget_id
                        && stroke.points.as_ref() == fill.points.as_ref()
                        && (stroke.width - super::TRACK_CARD_OUTLINE_WIDTH).abs() < 0.01)
                        .then_some((stroke.color, stroke.width))
                })?;
                let rail = primitives.iter().find_map(|primitive| {
                    let PaintPrimitive::FillRect(rail) = primitive else {
                        return None;
                    };
                    (rail.widget_id == fill.widget_id
                        && (rail.rect.width() - super::TRACK_CARD_RAIL_WIDTH).abs() < 0.01)
                        .then_some(rail)
                })?;
                Some(TrackCardPaintSnapshot {
                    fill: fill.color,
                    outline,
                    outline_width,
                    rail: rail.color,
                    rail_width: rail.rect.width(),
                    points: Arc::clone(&fill.points),
                })
            })
            .collect()
    }

    #[test]
    fn track_card_chrome_is_paint_only_and_uses_shared_style() {
        let bounds = Rect::from_min_size(Point::new(10.0, 20.0), Vector2::new(200.0, 100.0));
        let theme = ThemeTokens::default();
        let widget = super::TrackCardChromeWidget::new(true, true);

        assert!(!widget.accepts_pointer_move());
        assert!(
            !widget.accepts_pointer_input(&WidgetInput::primary_press(Point::new(20.0, 30.0,)))
        );
        assert!(!widget.common().paint.suppresses_container_hover);
        assert!(!widget.common().paint.paints_focus);

        let mut primitives = Vec::new();
        widget.append_paint(
            &mut primitives,
            bounds,
            &radiant::layout::LayoutOutput::default(),
            &theme,
        );
        let snapshots = track_card_paint_snapshots(&primitives);
        assert_eq!(snapshots.len(), 1);
        let snapshot = &snapshots[0];
        assert_eq!(snapshot.fill, super::track_card_fill(true, &theme));
        assert_eq!(snapshot.outline, super::TRACK_CARD_SELECTED_CORAL);
        assert_eq!(snapshot.outline_width, super::TRACK_CARD_OUTLINE_WIDTH);
        assert_eq!(snapshot.rail, super::TRACK_CARD_SELECTED_CORAL);
        assert_eq!(snapshot.rail_width, super::TRACK_CARD_RAIL_WIDTH);
        assert_eq!(snapshot.points, super::track_card_points(bounds));
    }

    #[test]
    fn favorite_track_card_fill_is_shared_in_dark_and_light_themes() {
        for (name, theme) in [
            ("dark", ThemeTokens::default()),
            ("light", ThemeTokens::light()),
        ] {
            let favorite = super::track_card_fill(true, &theme);
            let non_favorite = super::track_card_fill(false, &theme);

            assert_eq!(non_favorite, theme.bg_primary);
            assert_ne!(favorite, non_favorite, "{name} card fills should differ");
            assert!(
                favorite.r > non_favorite.r
                    && favorite.g > non_favorite.g
                    && favorite.b > non_favorite.b,
                "favorite fill should be brighter in every RGB channel in {name} theme"
            );
            if name == "light" {
                assert!(
                    favorite.r >= 247 && favorite.g >= 247 && favorite.b >= 247,
                    "light favorite fill should remain near-white"
                );
            }
        }
    }

    #[test]
    fn favorite_card_stack_routes_clicks_to_one_toggle_control() {
        let track = audition_track("favorite-card-track");
        let track_id = track.id.clone();
        let bridge = DeclarativeOwnedRuntimeBridge::new(
            track.clone(),
            move |track| {
                favorite_toggle(track, false, String::from("favorite-card-control")).into_surface()
            },
            |track, message| {
                if let Message::ToggleFavorite(id) = message
                    && id == track.id
                {
                    track.favorite = !track.favorite;
                }
            },
        );
        let mut runtime = SurfaceRuntime::new(bridge, Vector2::new(28.0, 24.0));
        let frame = runtime.frame_with_default_theme();
        let star = frame
            .paint_plan
            .text_runs()
            .find(|run| run.text.as_str() == "☆")
            .expect("the composed favorite control should paint its inactive marker");
        let point = Point::new(
            star.rect.min.x + star.rect.width() * 0.5,
            star.rect.min.y + star.rect.height() * 0.5,
        );
        let targets = runtime.automation_target_snapshot();
        let actionable_favorites = targets
            .targets
            .iter()
            .filter(|target| target.interaction_target && target.label.as_deref() == Some("☆"))
            .count();

        assert_eq!(actionable_favorites, 1);
        assert_eq!(runtime.widget_at(point), Some(star.widget_id));
        runtime.dispatch_primary_click(point);
        assert!(runtime.bridge().state().favorite);
        assert_eq!(track_id, runtime.bridge().state().id);
    }

    #[test]
    fn library_track_cards_paint_persistent_rails_and_stronger_outlines() {
        let mut state = AppState {
            busy: false,
            ..AppState::default()
        };
        let mut selected = audition_track("selected-track");
        selected.favorite = true;
        let unselected = audition_track("unselected-track");
        state.library.selected_track_id = Some(selected.id.clone());
        state.library.tracks = vec![selected, unselected];

        let frame = project_surface(&state)
            .view_frame_at_size_with_default_theme(Vector2::new(800.0, 600.0));
        let theme = ThemeTokens::default();
        let is_track_card_polygon = |points: &[Point]| {
            if points.len() != 5 {
                return false;
            }
            let min_x = points
                .iter()
                .map(|point| point.x)
                .fold(f32::INFINITY, f32::min);
            let min_y = points
                .iter()
                .map(|point| point.y)
                .fold(f32::INFINITY, f32::min);
            let max_x = points
                .iter()
                .map(|point| point.x)
                .fold(f32::NEG_INFINITY, f32::max);
            let max_y = points
                .iter()
                .map(|point| point.y)
                .fold(f32::NEG_INFINITY, f32::max);
            max_x - min_x > 200.0 && max_y - min_y > 60.0
        };
        let card_fills = frame
            .paint_plan
            .fill_polygons()
            .filter(|fill| is_track_card_polygon(&fill.points))
            .collect::<Vec<_>>();
        assert_eq!(
            card_fills.len(),
            2,
            "selected and unselected library cards should each paint one chamfered base"
        );

        let selected_card_widget_id = card_fills
            .iter()
            .find_map(|fill| {
                frame.paint_plan.primitives.iter().find_map(|primitive| {
                    matches!(
                        primitive,
                        PaintPrimitive::StrokePolygon(stroke)
                            if stroke.widget_id == fill.widget_id
                                && stroke.color == super::TRACK_CARD_SELECTED_CORAL
                                && stroke.points.as_ref() == fill.points.as_ref()
                    )
                    .then_some(fill.widget_id)
                })
            })
            .expect("selected library card should paint a coral polygon outline");
        let unselected_card_widget_id = card_fills
            .iter()
            .find_map(|fill| {
                frame.paint_plan.primitives.iter().find_map(|primitive| {
                    matches!(
                        primitive,
                            PaintPrimitive::StrokePolygon(stroke)
                                if stroke.widget_id == fill.widget_id
                                && stroke.color == theme.grid_strong
                                && stroke.points.as_ref() == fill.points.as_ref()
                    )
                    .then_some(fill.widget_id)
                })
            })
            .expect("unselected library card should paint a neutral polygon outline");

        let selected_card_points = card_fills
            .iter()
            .find(|fill| fill.widget_id == selected_card_widget_id)
            .expect("selected card base should be paired with its outline")
            .points
            .clone();
        let unselected_card_points = card_fills
            .iter()
            .find(|fill| fill.widget_id == unselected_card_widget_id)
            .expect("unselected card base should be paired with its outline")
            .points
            .clone();
        let selected_card_fill = card_fills
            .iter()
            .find(|fill| fill.widget_id == selected_card_widget_id)
            .expect("selected card should have a polygon fill");
        let unselected_card_fill = card_fills
            .iter()
            .find(|fill| fill.widget_id == unselected_card_widget_id)
            .expect("unselected card should have a polygon fill");
        assert_eq!(
            selected_card_fill.color,
            super::track_card_fill(true, &theme),
            "favorite card should use the lighter favorite fill"
        );
        assert_eq!(
            unselected_card_fill.color,
            super::track_card_fill(false, &theme),
            "non-favorite card should retain the baseline fill"
        );
        assert_ne!(
            selected_card_fill.color, unselected_card_fill.color,
            "favorite and non-favorite card fills should differ"
        );
        assert!(
            selected_card_fill.color.r > unselected_card_fill.color.r
                && selected_card_fill.color.g > unselected_card_fill.color.g
                && selected_card_fill.color.b > unselected_card_fill.color.b,
            "favorite card fill should be lighter in every RGB channel"
        );
        let assert_bottom_right_chamfer = |points: &[Point]| {
            assert_eq!(points.len(), 5);
            let min_x = points
                .iter()
                .map(|point| point.x)
                .fold(f32::INFINITY, f32::min);
            let min_y = points
                .iter()
                .map(|point| point.y)
                .fold(f32::INFINITY, f32::min);
            let max_x = points
                .iter()
                .map(|point| point.x)
                .fold(f32::NEG_INFINITY, f32::max);
            let max_y = points
                .iter()
                .map(|point| point.y)
                .fold(f32::NEG_INFINITY, f32::max);
            assert!((points[0].x - min_x).abs() < 0.01);
            assert!((points[0].y - min_y).abs() < 0.01);
            assert!((points[1].x - max_x).abs() < 0.01);
            assert!((points[1].y - min_y).abs() < 0.01);
            assert!((points[2].x - max_x).abs() < 0.01);
            assert!((points[2].y - max_y).abs() > 0.01);
            assert!((points[3].x - max_x).abs() > 0.01);
            assert!((points[3].y - max_y).abs() < 0.01);
            assert!((points[4].x - min_x).abs() < 0.01);
            assert!((points[4].y - max_y).abs() < 0.01);
            assert!((points[1].x - points[3].x) > 0.0);
            assert!((points[4].y - points[2].y) > 0.0);
            assert!(((points[1].x - points[3].x) - (points[4].y - points[2].y)).abs() < 0.01);
        };
        assert_bottom_right_chamfer(&selected_card_points);
        assert_bottom_right_chamfer(&unselected_card_points);
        assert!(
            ((selected_card_points[1].x - selected_card_points[3].x)
                - (unselected_card_points[1].x - unselected_card_points[3].x))
                .abs()
                < 0.01,
            "selected and unselected cards should share one chamfer size"
        );

        let selected_card_stroke = frame
            .paint_plan
            .primitives
            .iter()
            .find_map(|primitive| match primitive {
                PaintPrimitive::StrokePolygon(stroke)
                    if stroke.widget_id == selected_card_widget_id =>
                {
                    Some(stroke)
                }
                _ => None,
            })
            .expect("selected library card should have one polygon outline");
        assert_eq!(selected_card_stroke.color, super::TRACK_CARD_SELECTED_CORAL);
        assert_eq!(selected_card_stroke.width, super::TRACK_CARD_OUTLINE_WIDTH);
        let unselected_card_stroke = frame
            .paint_plan
            .primitives
            .iter()
            .find_map(|primitive| match primitive {
                PaintPrimitive::StrokePolygon(stroke)
                    if stroke.widget_id == unselected_card_widget_id =>
                {
                    Some(stroke)
                }
                _ => None,
            })
            .expect("unselected library card should have one polygon outline");
        assert_eq!(unselected_card_stroke.color, theme.grid_strong);
        assert_eq!(
            unselected_card_stroke.width,
            super::TRACK_CARD_OUTLINE_WIDTH
        );
        assert!(
            !frame
                .paint_plan
                .fill_polygons_for_widget(selected_card_widget_id)
                .any(|fill| fill.color == super::TRACK_CARD_SELECTED_CORAL)
        );

        let selected_rails = frame
            .paint_plan
            .fill_rects_for_widget(selected_card_widget_id)
            .filter(|fill| fill.color == super::TRACK_CARD_SELECTED_CORAL)
            .collect::<Vec<_>>();
        assert_eq!(
            selected_rails.len(),
            1,
            "selected card should paint one coral rail"
        );
        assert_eq!(selected_rails[0].rect.width(), super::TRACK_CARD_RAIL_WIDTH);
        assert_eq!(
            selected_rails[0].rect.height(),
            selected_card_points
                .iter()
                .map(|point| point.y)
                .fold(f32::NEG_INFINITY, f32::max)
                - selected_card_points
                    .iter()
                    .map(|point| point.y)
                    .fold(f32::INFINITY, f32::min)
                - (super::TRACK_CARD_RAIL_VERTICAL_INSET * 2.0)
        );

        let unselected_rails = frame
            .paint_plan
            .fill_rects_for_widget(unselected_card_widget_id)
            .filter(|fill| fill.color == theme.grid_strong)
            .collect::<Vec<_>>();
        assert_eq!(
            unselected_rails.len(),
            1,
            "unselected card should paint one neutral strong-grid rail"
        );
        assert_eq!(
            unselected_rails[0].rect.width(),
            super::TRACK_CARD_RAIL_WIDTH
        );

        let selected_min_x = selected_card_points
            .iter()
            .map(|point| point.x)
            .fold(f32::INFINITY, f32::min);
        let selected_min_y = selected_card_points
            .iter()
            .map(|point| point.y)
            .fold(f32::INFINITY, f32::min);
        let selected_max_y = selected_card_points
            .iter()
            .map(|point| point.y)
            .fold(f32::NEG_INFINITY, f32::max);
        assert!(
            frame.paint_plan.fill_rects().any(|fill| {
                fill.color == super::TRACK_CARD_SELECTED_CORAL
                    && (fill.rect.width() - super::TRACK_CARD_RAIL_WIDTH).abs() < 0.01
                    && fill.rect.min.x >= selected_min_x
                    && fill.rect.min.x
                        <= selected_min_x
                            + super::TRACK_CARD_RAIL_EDGE_INSET
                            + super::TRACK_CARD_RAIL_WIDTH
                    && fill.rect.min.y >= selected_min_y
                    && fill.rect.max.y <= selected_max_y
            }),
            "the selected card should paint one leading coral rail"
        );
        assert!(!frame.paint_plan.primitives.iter().any(|primitive| {
            primitive.widget_id() == Some(unselected_card_widget_id)
                && matches!(
                    primitive,
                    PaintPrimitive::FillRect(fill)
                        if fill.color == super::TRACK_CARD_SELECTED_CORAL
                )
                || primitive.widget_id() == Some(unselected_card_widget_id)
                    && matches!(
                        primitive,
                        PaintPrimitive::FillPolygon(fill)
                            if fill.color == super::TRACK_CARD_SELECTED_CORAL
                    )
                || primitive.widget_id() == Some(unselected_card_widget_id)
                    && matches!(
                        primitive,
                    PaintPrimitive::StrokePolygon(stroke)
                            if stroke.color == super::TRACK_CARD_SELECTED_CORAL
                    )
        }));
        assert_eq!(
            frame
                .paint_plan
                .fill_rects_for_widget(selected_card_widget_id)
                .count(),
            1,
            "the interactive-row underlay must not duplicate the selected card rail"
        );
    }

    #[test]
    fn all_track_card_contexts_paint_shared_chrome_and_selection_states() {
        let mut favorite = audition_track("favorite-track-card");
        favorite.favorite = true;
        favorite.stage = TrackStage::Production;
        let mut selected = audition_track("selected-track-card");
        selected.stage = TrackStage::Production;
        let mut state = AppState {
            busy: false,
            ..AppState::default()
        };
        state.library.selected_track_id = Some(selected.id.clone());
        state.library.tracks = vec![favorite.clone(), selected.clone()];
        state.audition_queue = vec![favorite.id.clone(), selected.id.clone()];
        let theme = ThemeTokens::default();
        let mut expected_styles = None;

        for mode in [
            WorkspaceMode::Review,
            WorkspaceMode::Audition,
            WorkspaceMode::Planner,
        ] {
            state.workspace_mode = mode;
            let frame = project_surface(&state)
                .view_frame_at_size_with_default_theme(Vector2::new(1_400.0, 900.0));
            let cards = track_card_paint_snapshots(&frame.paint_plan.primitives);
            assert_eq!(
                cards.len(),
                2,
                "{mode:?} should paint one shared card chrome for each track"
            );

            let selected_card = cards
                .iter()
                .find(|card| card.outline == super::TRACK_CARD_SELECTED_CORAL)
                .expect("selected track should have the coral card outline");
            assert_eq!(selected_card.fill, super::track_card_fill(false, &theme));
            assert_eq!(selected_card.rail, super::TRACK_CARD_SELECTED_CORAL);

            let favorite_card = cards
                .iter()
                .find(|card| card.fill == super::track_card_fill(true, &theme))
                .expect("favorite track should have the lighter card fill");
            assert_eq!(favorite_card.outline, theme.grid_strong);
            assert_eq!(favorite_card.rail, theme.grid_strong);

            for card in &cards {
                assert_eq!(card.outline_width, super::TRACK_CARD_OUTLINE_WIDTH);
                assert_eq!(card.rail_width, super::TRACK_CARD_RAIL_WIDTH);
                assert_eq!(card.rail, card.outline);
                assert_eq!(card.points.len(), 5);
                assert!(
                    ((card.points[1].x - card.points[3].x) - super::TRACK_CARD_CHAMFER).abs()
                        < 0.01,
                    "{mode:?} card should use the shared bottom-right chamfer"
                );
            }

            let mut styles = cards
                .iter()
                .map(|card| {
                    (
                        card.fill,
                        card.outline,
                        card.outline_width.to_bits(),
                        card.rail,
                        card.rail_width.to_bits(),
                    )
                })
                .collect::<Vec<_>>();
            styles.sort_by_key(|(fill, outline, outline_width, rail, rail_width)| {
                (
                    fill.r,
                    fill.g,
                    fill.b,
                    outline.r,
                    outline.g,
                    outline.b,
                    *outline_width,
                    rail.r,
                    rail.g,
                    rail.b,
                    *rail_width,
                )
            });
            if let Some(expected_styles) = &expected_styles {
                assert_eq!(
                    &styles, expected_styles,
                    "{mode:?} should reuse Review's card chrome colors and dimensions"
                );
            } else {
                expected_styles = Some(styles);
            }
        }
    }

    #[test]
    fn library_track_card_content_inset_grows_bounds_without_resizing_controls() {
        let track_id = String::from("card-inset-track");
        let mut state = AppState {
            busy: false,
            ..AppState::default()
        };
        state.library.selected_track_id = Some(track_id.clone());
        state.library.tracks = vec![audition_track(&track_id)];
        let frame = project_surface(&state)
            .view_frame_at_size_with_default_theme(Vector2::new(800.0, 600.0));
        let theme = ThemeTokens::default();
        let card = frame
            .paint_plan
            .fill_polygons()
            .find(|fill| {
                fill.color == theme.bg_primary
                    && fill.points.len() == 5
                    && fill
                        .points
                        .iter()
                        .map(|point| point.x)
                        .fold(f32::NEG_INFINITY, f32::max)
                        - fill
                            .points
                            .iter()
                            .map(|point| point.x)
                            .fold(f32::INFINITY, f32::min)
                        > 200.0
                    && fill
                        .points
                        .iter()
                        .map(|point| point.y)
                        .fold(f32::NEG_INFINITY, f32::max)
                        - fill
                            .points
                            .iter()
                            .map(|point| point.y)
                            .fold(f32::INFINITY, f32::min)
                        > 60.0
            })
            .expect("the track row should paint one card base");
        let card_bounds = Rect::from_min_max(
            Point::new(
                card.points
                    .iter()
                    .map(|point| point.x)
                    .fold(f32::INFINITY, f32::min),
                card.points
                    .iter()
                    .map(|point| point.y)
                    .fold(f32::INFINITY, f32::min),
            ),
            Point::new(
                card.points
                    .iter()
                    .map(|point| point.x)
                    .fold(f32::NEG_INFINITY, f32::max),
                card.points
                    .iter()
                    .map(|point| point.y)
                    .fold(f32::NEG_INFINITY, f32::max),
            ),
        );
        let expected_height = 26.0
            + (ui::dropdown_trigger_height() * 2.0)
            + (super::TRACK_CARD_CONTENT_SPACING * 4.0)
            + 18.0
            + super::REMOVAL_CONFIRMATION_ROW_HEIGHT
            + (super::TRACK_CARD_CONTENT_INSET * 2.0);
        assert!(
            (card_bounds.height() - expected_height).abs() < 0.01,
            "card height should include the larger content inset: bounds={card_bounds:?}"
        );

        let control_bounds = |label: &str| {
            let run = frame
                .paint_plan
                .text_runs()
                .find(|run| {
                    run.text.as_str() == label
                        && run.rect.min.x < super::LIBRARY_WIDTH
                        && run.rect.min.y >= card_bounds.min.y
                        && run.rect.max.y <= card_bounds.max.y
                })
                .unwrap_or_else(|| panic!("missing {label:?} control label"));
            frame
                .layout
                .rects
                .get(&run.widget_id)
                .copied()
                .unwrap_or_else(|| panic!("missing {label:?} control bounds"))
        };
        let title_bounds = control_bounds(&track_id);
        let stage_bounds = control_bounds("Production / arrangement");
        let status_bounds = control_bounds("Inbox");
        for (label, bounds) in [("title", title_bounds), ("stage", stage_bounds)] {
            assert!(
                (bounds.min.x - card_bounds.min.x - super::TRACK_CARD_CONTENT_INSET).abs() < 0.01,
                "{label} should start at the card content inset: card={card_bounds:?}, control={bounds:?}"
            );
        }
        assert!(
            (status_bounds.min.x
                - card_bounds.min.x
                - super::TRACK_CARD_CONTENT_INSET
                - super::STATUS_RAIL_WIDTH
                - super::STATUS_RAIL_GAP)
                .abs()
                < 0.01,
            "status trigger should follow its inset rail and gap: card={card_bounds:?}, control={status_bounds:?}"
        );
        assert_eq!(stage_bounds.height(), 24.0);
        assert_eq!(status_bounds.height(), ui::dropdown_trigger_height());
        let status_rail = frame
            .paint_plan
            .fill_rects()
            .find(|fill| {
                fill.rect.width() == super::STATUS_RAIL_WIDTH
                    && fill.rect.height() == ui::dropdown_trigger_height()
                    && fill.rect.min.x >= card_bounds.min.x
                    && fill.rect.max.x <= card_bounds.max.x
            })
            .expect("the status dropdown should retain its compact semantic rail");
        assert!(
            (status_rail.rect.min.x - card_bounds.min.x - super::TRACK_CARD_CONTENT_INSET).abs()
                < 0.01
        );
    }

    #[test]
    fn library_cards_are_inset_from_scrollbar_and_separated() {
        let mut state = AppState {
            busy: false,
            ..AppState::default()
        };
        state.library.selected_track_id = Some(String::from("track-0"));
        state.library.tracks = (0..12)
            .map(|index| audition_track(&format!("track-{index}")))
            .collect();

        let frame = project_surface(&state)
            .view_frame_at_size_with_default_theme(Vector2::new(800.0, 600.0));
        let theme = ThemeTokens::default();
        let mut card_rects = frame
            .paint_plan
            .fill_polygons()
            .filter(|fill| {
                fill.color == theme.bg_primary
                    && fill.points.len() == 5
                    && fill
                        .points
                        .iter()
                        .map(|point| point.x)
                        .fold(f32::NEG_INFINITY, f32::max)
                        - fill
                            .points
                            .iter()
                            .map(|point| point.x)
                            .fold(f32::INFINITY, f32::min)
                        > 200.0
                    && fill
                        .points
                        .iter()
                        .map(|point| point.y)
                        .fold(f32::NEG_INFINITY, f32::max)
                        - fill
                            .points
                            .iter()
                            .map(|point| point.y)
                            .fold(f32::INFINITY, f32::min)
                        > 60.0
            })
            .map(|fill| {
                Rect::from_min_max(
                    Point::new(
                        fill.points
                            .iter()
                            .map(|point| point.x)
                            .fold(f32::INFINITY, f32::min),
                        fill.points
                            .iter()
                            .map(|point| point.y)
                            .fold(f32::INFINITY, f32::min),
                    ),
                    Point::new(
                        fill.points
                            .iter()
                            .map(|point| point.x)
                            .fold(f32::NEG_INFINITY, f32::max),
                        fill.points
                            .iter()
                            .map(|point| point.y)
                            .fold(f32::NEG_INFINITY, f32::max),
                    ),
                )
            })
            .collect::<Vec<_>>();
        card_rects.sort_by(|left, right| left.min.y.total_cmp(&right.min.y));
        assert!(
            card_rects.len() >= 2,
            "the frame should expose multiple library cards"
        );

        let first = card_rects[0];
        let library_origin_x = 18.0;
        assert!(
            (first.min.x - (library_origin_x + 10.0 + super::LIBRARY_LIST_INSET)).abs() < 0.01,
            "unexpected library card left inset: first={first:?} expected={}",
            library_origin_x + 10.0 + super::LIBRARY_LIST_INSET
        );
        assert!(
            (first.max.x
                - (library_origin_x + super::LIBRARY_WIDTH - 10.0 - super::LIBRARY_LIST_INSET))
                .abs()
                < 0.01
        );
        for pair in card_rects.windows(2) {
            assert!(
                pair[1].min.y - pair[0].max.y >= super::TRACK_CARD_LIST_SPACING - 0.01,
                "library cards should retain a visible vertical gap: {:?} then {:?}",
                pair[0],
                pair[1]
            );
        }

        let scrollbar = frame
            .paint_plan
            .fill_rects()
            .find(|fill| {
                (fill.rect.width() - 3.0).abs() < 0.01
                    && fill.rect.min.x > super::LIBRARY_WIDTH - 6.0
            })
            .expect("overflowing library content should paint a virtual scrollbar thumb");
        assert!(
            first.max.x < scrollbar.rect.min.x,
            "card right border must remain left of the scrollbar: card={first:?}, scrollbar={:?}",
            scrollbar.rect
        );
    }

    #[test]
    fn status_dropdown_uses_neutral_body_and_compact_semantic_rail() {
        let theme = ThemeTokens::default();
        let statuses = [
            (TrackStatus::Inbox, super::TRACK_CARD_SELECTED_CORAL),
            (TrackStatus::Refine, theme.accent_warning),
            (TrackStatus::Release, theme.highlight_cyan),
            (TrackStatus::Archive, theme.text_muted),
            (TrackStatus::Maybe, theme.accent_danger),
        ];

        for (status, expected_rail_color) in statuses {
            let mut track = audition_track("status-rail");
            track.status = status;
            let frame = ui::scene(status_dropdown_for_host(
                &track,
                false,
                false,
                StatusMenuHost::Library,
            ))
            .into_view()
            .view_frame_at_size_with_default_theme(Vector2::new(240.0, 80.0));
            let label = frame
                .paint_plan
                .text_runs()
                .find(|run| run.text.as_str() == status.label())
                .expect("status trigger should paint its selected label");
            let body = frame
                .paint_plan
                .fill_polygons()
                .find(|fill| {
                    fill.widget_id == label.widget_id && fill.color == theme.surface_overlay
                })
                .expect("status trigger should use a neutral dark body");
            let body_min_x = body
                .points
                .iter()
                .map(|point| point.x)
                .fold(f32::INFINITY, f32::min);
            let rail = frame
                .paint_plan
                .fill_rects()
                .find(|fill| {
                    fill.color == expected_rail_color
                        && (fill.rect.width() - super::STATUS_RAIL_WIDTH).abs() < 0.01
                })
                .expect("status trigger should paint one semantic color rail");
            assert!(rail.rect.max.x <= body_min_x);
            assert_eq!(rail.rect.height(), ui::dropdown_trigger_height());
            assert!(!frame.paint_plan.fill_polygons().any(|fill| {
                fill.widget_id == label.widget_id
                    && [
                        super::TRACK_CARD_SELECTED_CORAL,
                        theme.accent_warning,
                        theme.highlight_cyan,
                        theme.accent_danger,
                    ]
                    .contains(&fill.color)
            }));
        }
    }

