    #[test]
    fn successive_native_file_drop_events_queue_every_path_while_importing() {
        let mut state = AppState {
            busy: true,
            ..AppState::default()
        };
        let mut context = ui::UiUpdateContext::default();
        let first = PathBuf::from("/external/first.wav");
        let second = PathBuf::from("/external/second.wav");

        update(
            &mut state,
            Message::FileDropped(ui::NativeFileDrop::dropped(first.clone(), None, None)),
            &mut context,
        );
        update(
            &mut state,
            Message::FileDropped(ui::NativeFileDrop::dropped(second.clone(), None, None)),
            &mut context,
        );

        assert_eq!(
            state.pending_import_paths,
            std::collections::VecDeque::from([first, second])
        );
        assert_eq!(
            state.import_batch,
            Some(ImportBatchProgress {
                total: 2,
                completed: 0,
                failed: 0,
            })
        );
    }

    #[test]
    fn import_completion_advances_progress_continues_after_failure_and_clears() {
        let mut state = AppState {
            busy: true,
            import_batch: Some(ImportBatchProgress {
                total: 3,
                completed: 0,
                failed: 0,
            }),
            pending_import_commit: Some(PendingImportCommit::Main),
            pending_import_paths: std::collections::VecDeque::from([
                PathBuf::from("/external/second.wav"),
                PathBuf::from("/external/third.wav"),
            ]),
            ..AppState::default()
        };
        let mut context = ui::UiUpdateContext::default();

        update(
            &mut state,
            Message::ImportCompleted(Ok(Library::default())),
            &mut context,
        );
        assert_eq!(
            state.import_batch,
            Some(ImportBatchProgress {
                total: 3,
                completed: 1,
                failed: 0,
            })
        );
        assert_eq!(
            state.pending_import_paths,
            std::collections::VecDeque::from([PathBuf::from("/external/third.wav")])
        );
        assert!(state.busy);

        state.pending_import_commit = Some(PendingImportCommit::Main);
        update(
            &mut state,
            Message::ImportCompleted(Err(String::from("second failed"))),
            &mut context,
        );
        assert_eq!(
            state.import_batch,
            Some(ImportBatchProgress {
                total: 3,
                completed: 2,
                failed: 1,
            })
        );
        assert!(state.pending_import_paths.is_empty());
        assert!(state.busy);

        state.pending_import_commit = Some(PendingImportCommit::Main);
        update(
            &mut state,
            Message::ImportCompleted(Ok(Library::default())),
            &mut context,
        );
        assert!(state.import_batch.is_none());
        assert_eq!(state.status, "Imported 2 of 3 files; 1 failed.");
        assert!(!state.busy);
    }

    #[test]
    fn multi_file_import_status_projects_counter_and_determinate_bar() {
        let state = AppState {
            busy: true,
            import_batch: Some(ImportBatchProgress {
                total: 3,
                completed: 1,
                failed: 1,
            }),
            ..AppState::default()
        };
        let frame = project_surface(&state)
            .view_frame_at_size_with_default_theme(Vector2::new(1180.0, 720.0));
        let labels = frame.paint_plan.text_label_strings();

        assert!(
            labels
                .iter()
                .any(|label| { label == "Importing 2 of 3 · 2 remaining · 1 failed" })
        );
        assert!(
            labels
                .iter()
                .any(|label| label == "SPACE  play · ESC  stop · N  note")
        );
        assert!(labels.iter().any(|label| label == APP_VERSION_LABEL));
        let version_run = frame
            .paint_plan
            .text_runs()
            .find(|run| run.text.as_str() == APP_VERSION_LABEL)
            .expect("the import-progress status bar should render the app version");
        assert_eq!(version_run.align, PaintTextAlign::Right);
        assert!(
            version_run.rect.max.x > 1180.0 - 100.0,
            "the import-progress version label should stay at the far right: {:?}",
            version_run.rect
        );
        assert!(
            (version_run.rect.width() - STATUS_BAR_VERSION_WIDTH).abs() < 0.01,
            "the import-progress version label should reserve the shared width: {:?}",
            version_run.rect
        );
        assert!(
            (version_run.rect.max.x - (1180.0 - 26.0)).abs() < 0.01,
            "the import-progress version label should reach the status bar's right edge: {:?}",
            version_run.rect
        );
        let shortcut_run = frame
            .paint_plan
            .text_runs()
            .find(|run| run.text.as_str() == "SPACE  play · ESC  stop · N  note")
            .expect("the import-progress status bar should render the shortcut hint");
        assert!(
            shortcut_run.rect.max.x <= version_run.rect.min.x,
            "the import-progress shortcut hint must not overlap the version label: shortcut={:?}, version={:?}",
            shortcut_run.rect,
            version_run.rect
        );

        let minimum_frame_size = Vector2::new(900.0, 560.0);
        let minimum_frame =
            project_surface(&state).view_frame_at_size_with_default_theme(minimum_frame_size);
        let minimum_version_run = minimum_frame
            .paint_plan
            .text_runs()
            .find(|run| run.text.as_str() == APP_VERSION_LABEL)
            .expect("the minimum-size import-progress status bar should render the app version");
        let minimum_shortcut_run = minimum_frame
            .paint_plan
            .text_runs()
            .find(|run| run.text.as_str() == "SPACE  play · ESC  stop · N  note")
            .expect("the minimum-size import-progress status bar should render the shortcut hint");
        assert_eq!(minimum_version_run.align, PaintTextAlign::Right);
        assert!(
            (minimum_version_run.rect.width() - STATUS_BAR_VERSION_WIDTH).abs() < 0.01,
            "the minimum-size import-progress version label should reserve the shared width: {:?}",
            minimum_version_run.rect
        );
        assert!(
            (minimum_version_run.rect.max.x - (minimum_frame_size.x - 26.0)).abs() < 0.01,
            "the minimum-size import-progress version label should reach the status bar's right edge: {:?}",
            minimum_version_run.rect
        );
        assert!(
            minimum_shortcut_run.rect.max.x <= minimum_version_run.rect.min.x,
            "the minimum-size import-progress shortcut hint must not overlap the version label: shortcut={:?}, version={:?}",
            minimum_shortcut_run.rect,
            minimum_version_run.rect
        );

        let fills = frame.paint_plan.fill_rects().collect::<Vec<_>>();
        assert!(fills.windows(2).any(|pair| {
            let track = pair[0];
            let fill = pair[1];
            track.widget_id == fill.widget_id
                && (track.rect.min.y - fill.rect.min.y).abs() < f32::EPSILON
                && (track.rect.height() - fill.rect.height()).abs() < f32::EPSILON
                && (fill.rect.width() - track.rect.width() / 3.0).abs() < 0.01
        }));
    }

    fn admit_library_save_for_test(
        state: &mut AppState,
        context: &mut ui::UiUpdateContext<Message>,
    ) {
        update(state, Message::AdmitLibrarySave, context);
    }

    #[test]
    fn failed_library_save_stays_dirty_blocks_import_and_retries_same_revision() {
        let mut state = AppState::default();
        let mut context = ui::UiUpdateContext::default();

        schedule_library_save(&mut state, &mut context);
        assert!(state.save_admission_pending);
        admit_library_save_for_test(&mut state, &mut context);
        let attempt = state
            .save_in_flight
            .expect("the first mutation should dispatch a save");
        assert_eq!(attempt.revision, state.library_revision);
        let _ = context.into_command();

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt,
                result: Err(String::from("disk full")),
            },
            &mut context,
        );
        assert!(library_dirty(&state));
        assert_eq!(state.save_in_flight, None);
        assert_eq!(state.status, "disk full");

        let queued_path = PathBuf::from("/external/queued-after-save-failure.wav");
        schedule_import(&mut state, &mut context, queued_path.clone());
        assert_eq!(
            state.pending_import_paths,
            std::collections::VecDeque::from([queued_path])
        );
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-import-preflight"),
            None,
            "a dirty library must block import preflight"
        );

        let mut context = ui::UiUpdateContext::default();
        update(&mut state, Message::RetryLibrarySave, &mut context);
        let retry_attempt = state
            .save_in_flight
            .expect("retry should dispatch the same revision");
        assert_eq!(state.library_revision, attempt.revision);
        assert_eq!(state.persisted_library_revision, 0);
        assert_eq!(retry_attempt.revision, attempt.revision);
        assert_ne!(retry_attempt.id, attempt.id);
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-save-library"),
            Some(TaskPriority::BlockingIo)
        );
    }

    #[test]
    fn duplicate_failed_save_attempt_cannot_retire_same_revision_retry() {
        let mut state = AppState::default();
        let mut context = ui::UiUpdateContext::default();
        schedule_library_save(&mut state, &mut context);
        admit_library_save_for_test(&mut state, &mut context);
        let attempt_a = state
            .save_in_flight
            .expect("the first mutation should dispatch a save");
        let _ = context.into_command();

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: attempt_a,
                result: Err(String::from("first save failed")),
            },
            &mut context,
        );
        let queued_path = PathBuf::from("/external/retry-queued.wav");
        schedule_import(&mut state, &mut context, queued_path.clone());
        let _ = context.into_command();

        let mut context = ui::UiUpdateContext::default();
        update(&mut state, Message::RetryLibrarySave, &mut context);
        let attempt_b = state
            .save_in_flight
            .expect("retry should dispatch a distinct attempt");
        assert_eq!(attempt_b.revision, attempt_a.revision);
        assert_ne!(attempt_b.id, attempt_a.id);
        let _ = context.into_command();

        let status_before_duplicate = state.status.clone();
        let revision_before_duplicate = state.library_revision;
        let persisted_before_duplicate = state.persisted_library_revision;
        let pending_before_duplicate = state.pending_import_paths.clone();
        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: attempt_a,
                result: Err(String::from("stale duplicate failure")),
            },
            &mut context,
        );
        assert_eq!(state.save_in_flight, Some(attempt_b));
        assert_eq!(state.library_revision, revision_before_duplicate);
        assert_eq!(state.persisted_library_revision, persisted_before_duplicate);
        assert_eq!(state.status, status_before_duplicate);
        assert_eq!(state.pending_import_paths, pending_before_duplicate);
        let command = context.into_command();
        assert_eq!(command.business_task_priority("cadence-save-library"), None);
        assert_eq!(
            command.business_task_priority("cadence-import-preflight"),
            None
        );

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: attempt_b,
                result: Ok(()),
            },
            &mut context,
        );
        assert!(!library_dirty(&state));
        assert_eq!(state.save_in_flight, None);
        assert!(state.pending_import_paths.is_empty());
        assert!(state.busy);
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-import-preflight"),
            Some(TaskPriority::Background)
        );

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::AudioImportPreflightCompleted {
                request: AudioImportRequest {
                    target: AudioImportTarget::Main,
                    path: queued_path,
                },
                result: Err(String::from("queued import failed")),
            },
            &mut context,
        );
        assert!(!state.busy);
        assert!(state.import_batch.is_none());
    }

    #[test]
    fn matching_retry_save_success_resumes_queued_import_and_clears_dirty_state() {
        let mut state = AppState::default();
        let queued_path = PathBuf::from("/external/queued-after-retry.wav");
        let mut context = ui::UiUpdateContext::default();
        schedule_library_save(&mut state, &mut context);
        admit_library_save_for_test(&mut state, &mut context);
        let attempt = state
            .save_in_flight
            .expect("the first mutation should dispatch a save");
        let _ = context.into_command();

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt,
                result: Err(String::from("temporary save failure")),
            },
            &mut context,
        );
        schedule_import(&mut state, &mut context, queued_path.clone());
        let _ = context.into_command();

        let mut context = ui::UiUpdateContext::default();
        update(&mut state, Message::RetryLibrarySave, &mut context);
        let retry_attempt = state
            .save_in_flight
            .expect("retry should dispatch the same revision");
        assert_eq!(retry_attempt.revision, attempt.revision);
        assert_ne!(retry_attempt.id, attempt.id);
        let _ = context.into_command();

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: retry_attempt,
                result: Ok(()),
            },
            &mut context,
        );

        assert!(!library_dirty(&state));
        assert_eq!(state.save_in_flight, None);
        assert!(state.busy, "the retained import should resume after save");
        assert!(state.pending_import_paths.is_empty());
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-import-preflight"),
            Some(TaskPriority::Background)
        );
    }

    #[test]
    fn newer_mutation_dispatches_after_older_save_and_stale_completion_is_ignored() {
        let mut state = AppState::default();
        let mut context = ui::UiUpdateContext::default();

        schedule_library_save(&mut state, &mut context);
        admit_library_save_for_test(&mut state, &mut context);
        let first_attempt = state
            .save_in_flight
            .expect("first mutation should dispatch");
        let first_revision = first_attempt.revision;
        let _ = context.into_command();
        let mut context = ui::UiUpdateContext::default();
        schedule_library_save(&mut state, &mut context);
        assert_eq!(state.library_revision, first_revision + 1);
        assert_eq!(state.save_in_flight, Some(first_attempt));
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-save-library"),
            None
        );

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: first_attempt,
                result: Ok(()),
            },
            &mut context,
        );
        let second_revision = first_revision + 1;
        assert_eq!(state.persisted_library_revision, first_revision);
        assert!(state.save_admission_pending);
        admit_library_save_for_test(&mut state, &mut context);
        let second_attempt = state
            .save_in_flight
            .expect("newer revision should dispatch after the first success");
        assert_eq!(second_attempt.revision, second_revision);
        assert_ne!(second_attempt.id, first_attempt.id);
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-save-library"),
            Some(TaskPriority::BlockingIo)
        );

        let status_after_first_success = state.status.clone();
        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: first_attempt,
                result: Err(String::from("stale duplicate")),
            },
            &mut context,
        );
        assert_eq!(state.status, status_after_first_success);
        assert_eq!(state.save_in_flight, Some(second_attempt));
        assert_eq!(
            context
                .into_command()
                .business_task_priority("cadence-save-library"),
            None
        );

        let mut context = ui::UiUpdateContext::default();
        update(
            &mut state,
            Message::LibrarySaved {
                attempt: second_attempt,
                result: Ok(()),
            },
            &mut context,
        );
        assert!(!library_dirty(&state));
        assert_eq!(state.persisted_library_revision, second_revision);
        assert_eq!(state.save_in_flight, None);
    }

